#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
enum CommandCenterSection {
    #[default]
    Sessions,
    System,
    Usage,
    Maintenance,
}

fn paint_command_center_section_icon(
    ui: &Ui,
    rect: Rect,
    section: CommandCenterSection,
    color: Color32,
) {
    let center = egui::pos2(rect.left() + 17.0, rect.center().y);
    let stroke = Stroke::new(1.25, color);
    let painter = ui.painter();
    match section {
        CommandCenterSection::Sessions => {
            painter.circle_stroke(center, 5.0, stroke);
            painter.line_segment(
                [
                    center + egui::vec2(-3.5, 3.5),
                    center + egui::vec2(-5.0, 6.0),
                ],
                stroke,
            );
        }
        CommandCenterSection::System => {
            let points = [
                center + egui::vec2(-7.0, 0.0),
                center + egui::vec2(-3.0, 0.0),
                center + egui::vec2(-1.0, -4.0),
                center + egui::vec2(2.0, 4.0),
                center + egui::vec2(4.0, -2.0),
                center + egui::vec2(7.0, -2.0),
            ];
            for pair in points.windows(2) {
                painter.line_segment([pair[0], pair[1]], stroke);
            }
        }
        CommandCenterSection::Usage => {
            for (index, height) in [5.0, 9.0, 7.0].into_iter().enumerate() {
                let left = center.x - 6.0 + index as f32 * 4.5;
                painter.rect_filled(
                    Rect::from_min_size(
                        egui::pos2(left, center.y + 5.0 - height),
                        egui::vec2(2.5, height),
                    ),
                    0.5,
                    color,
                );
            }
        }
        CommandCenterSection::Maintenance => {
            painter.circle_stroke(center, 3.5, stroke);
            for direction in [
                egui::vec2(0.0, -6.5),
                egui::vec2(0.0, 6.5),
                egui::vec2(-6.5, 0.0),
                egui::vec2(6.5, 0.0),
            ] {
                painter.line_segment([center + direction * 0.72, center + direction], stroke);
            }
        }
    }
}

fn format_compact_count(value: u64) -> String {
    match value {
        value if value >= 1_000_000_000 => format!("{:.1}B", value as f64 / 1_000_000_000.0),
        value if value >= 1_000_000 => format!("{:.1}M", value as f64 / 1_000_000.0),
        value if value >= 10_000 => format!("{:.0}K", value as f64 / 1_000.0),
        value if value >= 1_000 => format!("{:.1}K", value as f64 / 1_000.0),
        value => value.to_string(),
    }
}

fn format_optional_compact_count(value: Option<u64>) -> String {
    value
        .map(format_compact_count)
        .unwrap_or_else(|| "—".into())
}

fn usage_stat(ui: &mut Ui, label: &str, value: String) {
    ui.vertical(|ui| {
        ui.label(RichText::new(label).small().color(MUTED));
        ui.strong(value);
    });
    ui.add_space(24.0);
}

impl CommandCenterSection {
    const ALL: [(Self, &'static str); 4] = [
        (Self::Sessions, "Sessions"),
        (Self::System, "System"),
        (Self::Usage, "Usage"),
        (Self::Maintenance, "Maintenance"),
    ];

    fn from_route(target: &str) -> Self {
        let section = target
            .split_once('?')
            .map(|(_, query)| {
                query
                    .split('&')
                    .find_map(|pair| pair.strip_prefix("section="))
                    .unwrap_or("sessions")
            })
            .unwrap_or("sessions");
        match section {
            "system" => Self::System,
            "usage" => Self::Usage,
            "maintenance" => Self::Maintenance,
            _ => Self::Sessions,
        }
    }

    #[cfg(feature = "agent-automation")]
    fn as_str(self) -> &'static str {
        match self {
            Self::Sessions => "sessions",
            Self::System => "system",
            Self::Usage => "usage",
            Self::Maintenance => "maintenance",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SidebarSessionGesture {
    ResumeInPlace,
    OpenInTab,
    OpenInWindow,
    TogglePin,
    Archive,
}

fn sidebar_session_gesture(modifiers: egui::Modifiers) -> SidebarSessionGesture {
    if modifiers.alt && modifiers.shift {
        return SidebarSessionGesture::Archive;
    }
    let primary_modifier = modifiers.command || modifiers.ctrl || modifiers.mac_cmd;
    if primary_modifier && modifiers.shift {
        return SidebarSessionGesture::OpenInWindow;
    }
    if primary_modifier {
        return SidebarSessionGesture::OpenInTab;
    }
    if modifiers.shift {
        return SidebarSessionGesture::TogglePin;
    }
    SidebarSessionGesture::ResumeInPlace
}

fn sidebar_row_click_modifiers(ui: &Ui, rect: Rect) -> egui::Modifiers {
    ui.input(|input| {
        input
            .events
            .iter()
            .rev()
            .find_map(|event| match event {
                egui::Event::PointerButton {
                    pos,
                    button: egui::PointerButton::Primary,
                    pressed: false,
                    modifiers,
                } if rect.contains(*pos) => Some(*modifiers),
                _ => None,
            })
            .unwrap_or(input.modifiers)
    })
}

