    #[cfg(feature = "agent-automation")]
    pub fn load_files_preview_fixture_for_automation(
        &mut self,
        root: &std::path::Path,
        image_preview: bool,
        svg_preview: bool,
        pdf_preview: bool,
        pdf_scroll_preview: bool,
        html_preview: bool,
    ) -> Result<(), String> {
        std::fs::create_dir_all(root)
            .map_err(|error| format!("create fixture project: {error}"))?;
        std::fs::write(
            root.join("README.md"),
            "# Files preview fixture\n\nThis is a distinct, isolated Files and preview screen.\n",
        )
        .map_err(|error| format!("write fixture README: {error}"))?;
        std::fs::write(
            root.join("Cargo.toml"),
            "[package]\nname = \"hermes-preview-fixture\"\nversion = \"0.1.0\"\n",
        )
        .map_err(|error| format!("write fixture manifest: {error}"))?;
        std::fs::write(
            root.join("main.rs"),
            "fn main() {\n    println!(\"Hello from the preview fixture\");\n}\n",
        )
        .map_err(|error| format!("write fixture source: {error}"))?;
        std::fs::write(
            root.join("preview.html"),
            "<!doctype html><html><head><meta charset=\"utf-8\"><title>Preview fixture</title><style>body{font:16px sans-serif;background:#f6f4ef;color:#252d3a;padding:32px}h1{color:#3972b9}button{padding:8px 12px}</style></head><body><h1>Rendered HTML preview</h1><p>This is a distinct local HTML fixture.</p><img src=\"preview-asset.svg\" onload=\"document.title='asset-loaded:'+this.naturalWidth\"><button id=\"fixture-action\" onclick=\"this.textContent='Clicked'\">Click fixture action</button></body></html>",
        )
        .map_err(|error| format!("write fixture HTML: {error}"))?;
        std::fs::write(
            root.join("preview-asset.svg"),
            "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\"><circle cx=\"8\" cy=\"8\" r=\"7\" fill=\"blue\"/></svg>",
        )
        .map_err(|error| format!("write fixture relative SVG: {error}"))?;
        std::fs::write(root.join(".gitignore"), "ignored-preview.txt\n")
            .map_err(|error| format!("write fixture ignore rules: {error}"))?;
        std::fs::write(root.join("ignored-preview.txt"), "hidden until requested\n")
            .map_err(|error| format!("write ignored fixture: {error}"))?;
        let git_init = std::process::Command::new("git")
            .args(["init", "--quiet"])
            .current_dir(root)
            .status()
            .map_err(|error| format!("initialize fixture repository: {error}"))?;
        if !git_init.success() {
            return Err("initialize fixture repository: git init failed".into());
        }
        let image_path = root.join("preview.png");
        image::RgbaImage::from_fn(320, 180, |x, y| {
            let stripe = ((x / 32 + y / 18) % 2) == 0;
            let color = if stripe {
                [73, 130, 206, 255]
            } else {
                [37, 45, 58, 255]
            };
            image::Rgba(color)
        })
        .save(&image_path)
        .map_err(|error| format!("write fixture image: {error}"))?;
        let svg_path = root.join("vector.svg");
        std::fs::write(
            &svg_path,
            r##"<svg xmlns="http://www.w3.org/2000/svg" width="320" height="180" viewBox="0 0 320 180"><rect width="320" height="180" fill="#252d3a"/><circle cx="160" cy="90" r="64" fill="#4990e0"/><path d="M120 90h80M160 50v80" stroke="#ffffff" stroke-width="8"/></svg>"##,
        )
        .map_err(|error| format!("write fixture vector: {error}"))?;
        let pdf_path = root.join("preview.pdf");
        let pdf_fixture = if pdf_scroll_preview {
            pdf_preview_fixture_bytes_for_pages(6)
        } else {
            pdf_preview_fixture_bytes()
        };
        std::fs::write(&pdf_path, pdf_fixture)
            .map_err(|error| format!("write fixture PDF: {error}"))?;

        let session_id = "files-preview-fixture";
        let profile = "fixture-profile";
        let cwd = root.to_string_lossy().into_owned();
        self.route = AppRoute::Session(session_id.into());
        self.active_session_profile = Some(profile.into());
        self.active_runtime_session_id = Some("runtime-files-preview-fixture".into());
        self.sessions.push(SessionSummary {
            connection_id: None,
            cwd: Some(cwd),
            id: session_id.into(),
            lineage_root_id: None,
            profile: Some(profile.into()),
            title: "Files preview fixture".into(),
            preview: "Inspect a project tree and transient file preview.".into(),
            message_count: 2,
            source: "fixture".into(),
            started_at: 0.0,
            last_active: None,
            pinned: false,
            unread: false,
            archived: false,
        });
        self.transcript = vec![
            json!({"role":"user","content":"Show the project files."}),
            json!({"role":"assistant","content": if html_preview { "The HTML source is open with a rendered Preview mode available." } else if pdf_scroll_preview { "The six-page PDF is open in a continuous preview pane." } else if pdf_preview { "The two-page PDF is open in a transient preview pane." } else if svg_preview { "The SVG image is open in a transient preview pane." } else if image_preview { "The PNG image is open in a transient preview pane." } else { "The Rust source file is open with syntax highlighting in a transient preview pane." }}),
        ];
        self.workspace
            .preferences
            .pane_open
            .insert(FILES.into(), true);
        self.workspace.apply_active_profile()?;
        self.files.set_root(Some(root.to_path_buf()));

        let preview_path = if html_preview {
            root.join("preview.html")
        } else if pdf_preview {
            pdf_path
        } else if svg_preview {
            svg_path
        } else if image_preview {
            image_path
        } else {
            root.join("main.rs")
        };
        self.workspace.open_file_preview(&preview_path)?;
        self.file_previews.request(&preview_path);
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        let mut tree_ready = false;
        let mut preview_ready = false;
        while std::time::Instant::now() < deadline {
            tree_ready |= self.files.poll();
            preview_ready |= self.file_previews.poll();
            if tree_ready && preview_ready {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(2));
        }
        self.status = "Files preview fixture · isolated local files · gateway disabled".into();
        Ok(())
    }

