    fn chrome_style() -> PanelChromeStyle {
        PanelChromeStyle {
            titlebar: PANEL_ALT,
            title: TEXT,
            control: Color32::from_rgb(43, 47, 55),
            control_hover: Color32::from_rgb(61, 69, 82),
            control_text: MUTED,
            control_border: BORDER,
            focus: ACCENT,
            corner_radius: 0.0,
            font: FontId::proportional(12.0),
        }
    }

    fn toolbar(&mut self, ui: &mut Ui) {
        ui.allocate_ui_with_layout(
            Vec2::new(ui.available_width(), 48.0),
            Layout::left_to_right(Align::Center),
            |ui| {
                ui.add_space(12.0);
                ui.horizontal_centered(|ui| {
                    ui.label(RichText::new("Hermes").size(17.0).strong().color(TEXT));
                    ui.add_space(16.0);
                    ui.label(RichText::new(&self.status).size(12.0).color(MUTED));
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        if ui.button("New window").clicked() {
                            self.execute_registered_action(RegisteredUiAction::OpenNewWindow)
                                .unwrap_or_else(|error| self.status = error);
                        }
                        if matches!(self.route, AppRoute::Session(_))
                            && ui.button("Move session to new window").clicked()
                        {
                            self.execute_registered_action(
                                RegisteredUiAction::MoveCurrentSessionToNewWindow,
                            )
                            .unwrap_or_else(|error| self.status = error);
                        }
                        let left_open = self.positional_side_open(true);
                        if ui
                            .button(if left_open {
                                "Hide left side"
                            } else {
                                "Show left side"
                            })
                            .on_hover_text("Toggle the dock group at the physical left edge")
                            .clicked()
                        {
                            self.toggle_positional_side(true);
                        }
                        let right_open = self.positional_side_open(false);
                        if ui
                            .button(if right_open {
                                "Hide right side"
                            } else {
                                "Show right side"
                            })
                            .on_hover_text("Toggle the dock group at the physical right edge")
                            .clicked()
                        {
                            self.toggle_positional_side(false);
                        }
                        if ui.button("Settings").clicked() {
                            self.execute_registered_action(RegisteredUiAction::Navigate {
                                path: "/settings".into(),
                            })
                            .unwrap_or_else(|error| self.status = error);
                        }
                        let previous = self.workspace.preferences.mode;
                        let mut selected_mode = previous;
                        egui::ComboBox::new("interface-mode", "Interface mode")
                            .selected_text(match previous {
                                InterfaceMode::Advanced => "Advanced",
                                InterfaceMode::Simple => "Simple",
                            })
                            .show_ui(ui, |ui| {
                                ui.selectable_value(
                                    &mut selected_mode,
                                    InterfaceMode::Advanced,
                                    "Advanced",
                                );
                                ui.selectable_value(
                                    &mut selected_mode,
                                    InterfaceMode::Simple,
                                    "Simple",
                                );
                            });
                        if previous != selected_mode {
                            self.execute_registered_action(RegisteredUiAction::SetInterfaceMode {
                                mode: selected_mode,
                            })
                            .unwrap_or_else(|error| self.status = error);
                        }
                        let active = self.workspace.active_profile().to_owned();
                        let options = self
                            .workspace
                            .profile_ids()
                            .into_iter()
                            .map(|option| {
                                let title = self.workspace.profile_title(&option);
                                (option, title)
                            })
                            .collect::<Vec<_>>();
                        let title = self.workspace.profile_title(&active);
                        let mut selected = active.clone();
                        egui::ComboBox::new("layout-profile", "Layout profile")
                            .close_behavior(egui::PopupCloseBehavior::CloseOnClickOutside)
                            .selected_text(title)
                            .show_ui(ui, |ui| {
                                let preset_draft_id =
                                    ui.scope_id().with("layout-preset-name-draft");
                                let mut preset_name = ui.ctx().data(|data| {
                                    data.get_temp::<String>(preset_draft_id).unwrap_or_default()
                                });
                                ui.horizontal(|ui| {
                                    ui.add(
                                        egui::TextEdit::singleline(&mut preset_name)
                                            .hint_text("Save current layout as…")
                                            .desired_width(150.0),
                                    )
                                    .accessible_name("Save current layout as…");
                                    if ui
                                        .button("Save")
                                        .accessible_name("Save user layout")
                                        .clicked()
                                    {
                                        match self.workspace.save_user_layout_preset(&preset_name) {
                                            Ok(id) => {
                                                selected = id.clone();
                                                self.status = format!(
                                                    "Saved layout: {}",
                                                    self.workspace.profile_title(&id)
                                                );
                                                preset_name.clear();
                                                ui.close();
                                            }
                                            Err(error) => self.status = error,
                                        }
                                    }
                                });
                                if self.workspace.is_user_profile(&active)
                                    && ui.button("Delete selected user layout").clicked()
                                {
                                    match self.workspace.delete_user_layout_preset(&active) {
                                        Ok(()) => {
                                            selected = self.workspace.active_profile().to_owned();
                                            self.status = "Deleted user layout".into();
                                            ui.close();
                                        }
                                        Err(error) => self.status = error,
                                    }
                                }
                                for (option, title) in options {
                                    let response = ui.selectable_value(
                                        &mut selected,
                                        option.to_owned(),
                                        title,
                                    );
                                    if response.clicked() {
                                        ui.close();
                                    }
                                }
                                ui.ctx().data_mut(|data| {
                                    data.insert_temp(preset_draft_id, preset_name)
                                });
                            });
                        if selected != active {
                            if self
                                .execute_registered_action(
                                    RegisteredUiAction::SelectLayoutProfile {
                                        profile_id: selected.clone(),
                                    },
                                )
                                .is_err()
                            {
                                self.status = format!(
                                    "Could not apply {} layout",
                                    self.workspace.profile_title(&selected)
                                );
                            }
                        }
                    });
                });
            },
        );
    }

    fn pane_controls(&mut self, ui: &mut Ui) {
        ui.allocate_ui_with_layout(
            Vec2::new(ui.available_width(), 36.0),
            Layout::left_to_right(Align::Center),
            |ui| {
                ui.add_space(10.0);
                ui.horizontal_centered(|ui| {
                    for (id, label) in [
                        (SESSIONS, "Sessions"),
                        (BOTS, "Bots"),
                        (REVIEW, "Review"),
                        (FILES, "Files"),
                        (TERMINAL, "Terminal"),
                    ] {
                        let open = if self.narrow_viewport
                            && matches!(id, SESSIONS | BOTS | REVIEW | FILES)
                        {
                            self.narrow_pane_overlay
                                .as_ref()
                                .is_some_and(|overlay| overlay.panel == id)
                        } else {
                            self.workspace.pane_is_open(id)
                        };
                        let response = ui.selectable_label(open, label).on_hover_text(match id {
                            SESSIONS => "Toggle sessions sidebar (Ctrl/Cmd+B)",
                            FILES => "Toggle file browser (Ctrl/Cmd+J)",
                            _ => label,
                        });
                        if response.clicked() {
                            self.execute_registered_action(RegisteredUiAction::TogglePane {
                                panel: id.into(),
                            })
                            .unwrap_or_else(|error| self.status = error);
                        }
                    }
                });
            },
        );
    }

    fn toggle_positional_side(&mut self, left: bool) {
        if self.narrow_viewport {
            let panel = self.panel_on_physical_side(left);
            self.toggle_narrow_pane(&panel);
            return;
        }
        match self.workspace.toggle_positional_edge(left) {
            Ok(true) => {
                self.status = if left {
                    "Left dock group minimized/restored".into()
                } else {
                    "Right dock group minimized/restored".into()
                };
            }
            Ok(false) => {
                let panel = if left { SESSIONS } else { FILES };
                self.execute_registered_action(RegisteredUiAction::TogglePane {
                    panel: panel.into(),
                })
                .unwrap_or_else(|error| self.status = error);
            }
            Err(error) => self.status = error,
        }
    }

    fn panel_on_physical_side(&self, left: bool) -> String {
        if let Some(panel) = self
            .workspace
            .narrow_collapsible_panels(!left)
            .into_iter()
            .next()
        {
            return panel;
        }
        let sessions_on_right = self.workspace.semantic_panel_is_right(SESSIONS);
        if sessions_on_right == !left {
            SESSIONS.into()
        } else {
            FILES.into()
        }
    }

    fn positional_side_open(&self, left: bool) -> bool {
        if self.narrow_viewport {
            self.narrow_pane_overlay
                .as_ref()
                .is_some_and(|overlay| overlay.panel == self.panel_on_physical_side(left))
        } else {
            self.workspace.positional_edge_open(left)
        }
    }

    fn toggle_narrow_pane(&mut self, panel: &str) {
        let current = self.narrow_pane_overlay.as_ref();
        self.narrow_pane_overlay = match current {
            Some(overlay) if overlay.panel == panel && overlay.pinned => None,
            Some(overlay) if overlay.panel == panel => Some(NarrowPaneOverlay {
                panel: panel.into(),
                pinned: true,
            }),
            _ => Some(NarrowPaneOverlay {
                panel: panel.into(),
                pinned: true,
            }),
        };
    }

    fn show_narrow_pane_overlay(&mut self, ctx: &egui::Context) {
        if !self.narrow_viewport {
            return;
        }
        let modal_open = self.route.is_overlay()
            || self.first_run_setup_visible
            || self.find_in_page_open
            || self.command_palette_open
            || self.recent_session_switcher.is_some()
            || self.rename_session.is_some();
        let escape = ctx.input(|input| input.key_pressed(egui::Key::Escape));
        if escape && !modal_open && self.narrow_pane_overlay.is_some() {
            ctx.input_mut(|input| {
                input.consume_key(egui::Modifiers::NONE, egui::Key::Escape);
            });
            self.narrow_pane_overlay = None;
        }

        let pointer = ctx.input(|input| input.pointer.hover_pos());
        if let Some(pos) = pointer {
            let screen = ctx.content_rect();
            let edge_panel = if pos.x <= screen.left() + 6.0 {
                Some(self.panel_on_physical_side(true))
            } else if pos.x >= screen.right() - 6.0 {
                Some(self.panel_on_physical_side(false))
            } else {
                None
            };
            if let Some(panel) = edge_panel {
                if self
                    .narrow_pane_overlay
                    .as_ref()
                    .is_none_or(|overlay| !overlay.pinned)
                {
                    self.narrow_pane_overlay = Some(NarrowPaneOverlay {
                        panel: panel.into(),
                        pinned: false,
                    });
                }
            } else if self
                .narrow_pane_overlay
                .as_ref()
                .is_some_and(|overlay| !overlay.pinned)
            {
                let inside = self
                    .narrow_overlay_rect(ctx)
                    .is_some_and(|rect| rect.contains(pos));
                if !inside {
                    self.narrow_pane_overlay = None;
                }
            }
        }

        let Some(overlay) = self.narrow_pane_overlay.clone() else {
            return;
        };
        let screen = ctx.content_rect();
        let panel_width = 237.0_f32.min(screen.width() * 0.85);
        let right = self.workspace.narrow_panel_is_right(&overlay.panel);
        let left = if right {
            screen.right() - panel_width
        } else {
            screen.left()
        };
        let rect = Rect::from_min_size(
            egui::pos2(left, screen.top()),
            Vec2::new(panel_width, screen.height()),
        );
        let tab_panels = self
            .workspace
            .dock
            .snapshot()
            .document
            .root
            .as_deref()
            .map(|root| collect_dock_tab_groups(Some(root)))
            .unwrap_or_default()
            .into_iter()
            .find(|group| group.panels.iter().any(|panel| panel.0 == overlay.panel))
            .map(|group| {
                group
                    .panels
                    .into_iter()
                    .filter(|panel| matches!(panel.0.as_str(), SESSIONS | BOTS | REVIEW | FILES))
                    .map(|panel| panel.0)
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        egui::Area::new(Id::NULL.with("hermes-narrow-pane-overlay"))
            .order(egui::Order::Foreground)
            .fixed_pos(rect.min)
            .show(ctx, |ui| {
                egui::Frame::new()
                    .fill(PANEL)
                    .stroke(Stroke::new(1.0, BORDER))
                    .show(ui, |ui| {
                        ui.set_min_size(rect.size());
                        ui.set_max_size(rect.size());
                        ui.horizontal(|ui| {
                            ui.strong(panel_title(&overlay.panel));
                            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                                if ui.small_button("Close").clicked() {
                                    self.narrow_pane_overlay = None;
                                }
                                if ui
                                    .small_button(if overlay.pinned { "Pinned" } else { "Pin" })
                                    .clicked()
                                {
                                    if let Some(current) = self.narrow_pane_overlay.as_mut() {
                                        current.pinned = !current.pinned;
                                    }
                                }
                            });
                        });
                        ui.separator();
                        if tab_panels.len() > 1 {
                            ui.horizontal(|ui| {
                                for panel in &tab_panels {
                                    let label = panel_title(panel);
                                    if ui
                                        .selectable_label(overlay.panel == *panel, label)
                                        .clicked()
                                    {
                                        self.narrow_pane_overlay = Some(NarrowPaneOverlay {
                                            panel: panel.clone(),
                                            pinned: overlay.pinned,
                                        });
                                    }
                                }
                            });
                        }
                        let panel_rect = ui.available_rect_before_wrap();
                        self.draw_panel(ui, &overlay.panel, panel_rect, rect, false);
                    });
            });
    }

    fn narrow_overlay_rect(&self, ctx: &egui::Context) -> Option<Rect> {
        let overlay = self.narrow_pane_overlay.as_ref()?;
        let screen = ctx.content_rect();
        let width = 237.0_f32.min(screen.width() * 0.85);
        let right = self.workspace.narrow_panel_is_right(&overlay.panel);
        let left = if right {
            screen.right() - width
        } else {
            screen.left()
        };
        Some(Rect::from_min_size(
            egui::pos2(left, screen.top()),
            Vec2::new(width, screen.height()),
        ))
    }

    fn draw_panel(
        &mut self,
        ui: &mut egui::Ui,
        id: &str,
        rect: Rect,
        drop_rect: Rect,
        show_titlebar: bool,
    ) {
        if rect.width() < 2.0 || rect.height() < 2.0 {
            return;
        }
        let rect = rect.intersect(ui.clip_rect());
        if rect.width() < 2.0 || rect.height() < 2.0 {
            return;
        }
        let mut child = ui.new_child(
            egui::UiBuilder::new()
                .max_rect(rect)
                .layout(Layout::top_down(Align::Min)),
        );
        let descriptor = self
            .workspace
            .dock
            .snapshot()
            .document
            .descriptor(&PanelId::from(id))
            .cloned();
        let is_session_tile = descriptor
            .as_ref()
            .is_some_and(|descriptor| descriptor.role == "hermes_session_tile");
        let is_file_preview = descriptor
            .as_ref()
            .is_some_and(|descriptor| descriptor.role == "hermes_file_preview");
        let title = match id {
            SESSIONS => "Sessions",
            BOTS => "Bots",
            WORKSPACE => self.route.title(),
            REVIEW => "Review",
            FILES => "Files",
            TERMINAL => "Terminal",
            _ => descriptor
                .as_ref()
                .map(|descriptor| descriptor.title_key.as_str())
                .unwrap_or(id),
        };
        let controls = if id == SESSIONS || id == WORKSPACE {
            vec![]
        } else if is_session_tile {
            vec![PanelChromeControl {
                glyph: "×",
                accessible_label: "Close session tab",
                tooltip: "Close session tab",
                enabled: true,
            }]
        } else if is_file_preview {
            vec![PanelChromeControl {
                glyph: "×",
                accessible_label: "Close file preview",
                tooltip: "Close file preview",
                enabled: true,
            }]
        } else {
            vec![PanelChromeControl {
                glyph: "×",
                accessible_label: "Hide panel",
                tooltip: "Hide panel",
                enabled: true,
            }]
        };
        if show_titlebar {
            let bar = child.allocate_space(Vec2::new(rect.width(), 32.0)).1;
            let response = panel_title_bar(
                &mut child,
                Id::unique(("panel-title", id)),
                bar,
                title,
                &Self::chrome_style(),
                &controls,
            );
            response
                .drag
                .widget_info(|| egui::WidgetInfo::labeled(Role::Group, true, title));
            if response.drag.drag_started() {
                self.begin_panel_drag(PanelId::from(id));
            }
            if !response.activated_controls.is_empty() {
                if is_session_tile {
                    self.request_close_session_pane(&PanelId::from(id));
                } else if is_file_preview {
                    self.workspace
                        .close_file_preview(&PanelId::from(id))
                        .unwrap_or_else(|error| self.status = error);
                    ui.ctx().request_repaint();
                } else {
                    self.execute_registered_action(RegisteredUiAction::TogglePane {
                        panel: id.into(),
                    })
                    .unwrap_or_else(|error| self.status = error);
                }
            }
        }
        self.update_panel_drop_target(&child, id, drop_rect);
        child.add_space(8.0);
        match id {
            SESSIONS => self.sessions_content(&mut child),
            BOTS => self.bots_panel(&mut child),
            WORKSPACE => self.workspace_content(&mut child),
            REVIEW => self.empty_panel(&mut child, "No review is active"),
            FILES => self.files_panel(&mut child),
            TERMINAL => self.empty_panel(
                &mut child,
                "Terminal is unavailable while the backend is offline",
            ),
            _ if is_session_tile => {
                self.session_pane_content(
                    &mut child,
                    descriptor.as_ref().expect("matched descriptor"),
                );
            }
            _ if is_file_preview => {
                if let Some(path) = descriptor
                    .as_ref()
                    .and_then(|descriptor| descriptor.metadata.get("hermes.file.path"))
                {
                    let markdown_cache = &mut self.markdown_cache;
                    self.file_previews
                        .open(&mut child, std::path::Path::new(path), markdown_cache);
                } else {
                    self.empty_panel(&mut child, "File preview path is missing");
                }
            }
            _ => {}
        }
    }

    fn bots_panel(&mut self, ui: &mut Ui) {
        self.load_bot_roster(false);
        let connected = self.gateway_connected && self.gateway_endpoint.is_some();
        let snapshot = self.bot_roster_for_current_endpoint().cloned();
        let pending = self.bot_roster_refresh.is_some();
        let error = self.bot_roster_error.clone();
        let profile = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone());

        ui.horizontal(|ui| {
            ui.heading("Bots");
            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                if ui
                    .add_enabled(connected, egui::Button::new("Refresh"))
                    .clicked()
                {
                    self.load_bot_roster(true);
                }
            });
        });
        if let Some(profile) = profile.as_deref() {
            ui.label(RichText::new(format!("Gateway profile · {profile}")).color(MUTED));
        }
        ui.separator();

        if !connected {
            ui.label(
                RichText::new("Connect to your Hermes backend to load its bot roster.")
                    .color(MUTED),
            );
            return;
        }
        if profile
            .as_deref()
            .is_some_and(|profile| profile.eq_ignore_ascii_case("all"))
        {
            ui.label(
                RichText::new("Select a specific Hermes profile to view its bots.").color(MUTED),
            );
            return;
        }
        if let Some(error) = error.as_deref() {
            ui.label(
                RichText::new(format!("Bot roster refresh failed: {error}"))
                    .color(Color32::from_rgb(231, 155, 108)),
            );
        }
        let Some(snapshot) = snapshot else {
            if pending {
                ui.horizontal(|ui| {
                    ui.spinner();
                    ui.label("Loading bots from the active gateway profile…");
                });
            } else if let Some(error) = error {
                ui.label(RichText::new(format!("Could not load bots: {error}")).color(MUTED));
                if ui.button("Retry").clicked() {
                    self.load_bot_roster(true);
                }
            } else {
                ui.label(RichText::new("Waiting for Hermes gateway…").color(MUTED));
            }
            return;
        };
        if snapshot.profiles.is_empty() {
            ui.label(
                RichText::new("No bots are configured for this gateway profile.").color(MUTED),
            );
            return;
        }
        egui::ScrollArea::vertical()
            .auto_shrink([false, false])
            .show_rows(ui, 78.0, snapshot.profiles.len(), |ui, rows| {
                for index in rows {
                    let bot = &snapshot.profiles[index];
                    ui.push_id(&bot.name, |ui| {
                        egui::Frame::group(ui.style()).show(ui, |ui| {
                            ui.horizontal(|ui| {
                                ui.strong(bot.display_name.as_deref().unwrap_or(&bot.name));
                                if let Some(title) =
                                    bot.title.as_deref().filter(|title| !title.is_empty())
                                {
                                    ui.label(RichText::new(title).color(MUTED));
                                }
                            });
                            ui.label(
                                RichText::new(format!(
                                    "{}{}",
                                    bot.name,
                                    bot.handle
                                        .as_deref()
                                        .map(|handle| format!(" · {handle}"))
                                        .unwrap_or_default()
                                ))
                                .small()
                                .color(MUTED),
                            );
                            if let Some(description) =
                                bot.description.as_deref().filter(|text| !text.is_empty())
                            {
                                ui.label(description);
                            }
                        });
                        ui.add_space(4.0);
                    });
                }
            });
    }

    fn files_panel(&mut self, ui: &mut Ui) {
        let root = match &self.route {
            AppRoute::Session(session_id) => self
                .sessions
                .iter()
                .find(|session| {
                    session.id == *session_id
                        && session.profile == self.active_session_profile
                        && !session.archived
                })
                .and_then(|session| session.cwd.as_deref())
                .map(std::path::PathBuf::from),
            _ => None,
        };
        self.files.set_root(root);
        if let Some(root) = self.files.root().map(std::path::Path::to_path_buf) {
            self.files
                .set_show_ignored(self.workspace.shows_ignored_files(&root));
        }
        if self.files.poll() {
            ui.ctx().request_repaint();
        }

        ui.horizontal(|ui| {
            ui.label(RichText::new("PROJECT FILES").strong().color(TEXT));
            if let Some(root) = self.files.root() {
                ui.label(
                    RichText::new(
                        root.file_name()
                            .map(|name| name.to_string_lossy())
                            .unwrap_or_else(|| root.display().to_string().into()),
                    )
                    .small()
                    .color(MUTED),
                )
                .on_hover_text(root.display().to_string());
            }
            let refresh = ui.small_button("↻").on_hover_text("Refresh project files");
            refresh.widget_info(|| egui::WidgetInfo::labeled(egui::Role::Button, false, "Refresh"));
            if refresh.clicked() {
                self.files.refresh();
            }
            if let Some(root) = self.files.root().map(std::path::Path::to_path_buf) {
                let mut show_ignored = self.workspace.shows_ignored_files(&root);
                let accessible_name = if show_ignored {
                    "Hide gitignored files"
                } else {
                    "Show gitignored files"
                };
                let glyph = if show_ignored { "◉" } else { "◎" };
                let response = ui
                    .add(egui::Button::new(glyph).small().selected(show_ignored))
                    .on_hover_text(accessible_name);
                response.widget_info(|| {
                    egui::WidgetInfo::labeled(egui::Role::Button, show_ignored, accessible_name)
                });
                if response.clicked() {
                    show_ignored = !show_ignored;
                    match self.workspace.set_show_ignored_files(&root, show_ignored) {
                        Ok(_) => {
                            self.files.set_show_ignored(show_ignored);
                            ui.ctx().request_repaint();
                        }
                        Err(error) => {
                            self.status = format!("Could not save Files preference: {error}")
                        }
                    }
                }
            }
        });
        ui.separator();
        let opened = egui::ScrollArea::vertical()
            .id_salt("hermes-files-tree-scroll")
            .show(ui, |ui| self.files.draw(ui))
            .inner;
        if let Some(path) = opened {
            match self.workspace.open_file_preview(&path) {
                Ok(_) => {
                    self.file_previews.request(&path);
                    ui.ctx().request_repaint();
                }
                Err(error) => self.status = error,
            }
        }
    }

    fn draw_split_resize_handles(
        &mut self,
        ui: &mut Ui,
        layout: &doofusdock_core::LayoutDocument,
        snapshot: &doofusdock_presentation::Snapshot,
    ) {
        let mut splits = Vec::new();
        collect_dock_splits(layout.root.as_deref(), &mut splits);
        for split in splits {
            let Some(bounds) = snapshot.nodes.get(&split.node) else {
                continue;
            };
            let rect = Rect::from_min_max(
                egui::pos2(bounds.x as f32, bounds.y as f32),
                egui::pos2((bounds.x + bounds.w) as f32, (bounds.y + bounds.h) as f32),
            );
            let horizontal = split.orientation == Orientation::Horizontal;
            let extent = if horizontal {
                rect.width()
            } else {
                rect.height()
            };
            if extent <= 0.0 || split.weights.len() < 2 {
                continue;
            }
            let weights = self
                .split_resize
                .as_ref()
                .filter(|resize| resize.split == split.node)
                .map_or_else(
                    || split.weights.clone(),
                    |resize| resize.current_weights.clone(),
                );
            let divider_size = 8.0;
            let mut position = if horizontal { rect.left() } else { rect.top() };
            for divider in 0..weights.len() - 1 {
                position += extent * weights[divider] as f32;
                let handle_rect = if horizontal {
                    Rect::from_min_max(
                        egui::pos2(position - divider_size * 0.5, rect.top()),
                        egui::pos2(position + divider_size * 0.5, rect.bottom()),
                    )
                } else {
                    Rect::from_min_max(
                        egui::pos2(rect.left(), position - divider_size * 0.5),
                        egui::pos2(rect.right(), position + divider_size * 0.5),
                    )
                };
                let label = format!("Resize split {} divider {}", split.node.0, divider + 1);
                let response = resize_handle(
                    ui,
                    Id::unique(("hermes-split-resize", &split.node.0, divider)),
                    handle_rect,
                    if horizontal {
                        ResizeAxis::Horizontal
                    } else {
                        ResizeAxis::Vertical
                    },
                    true,
                    &label,
                    ResizeHandleStyle {
                        idle: BORDER,
                        hovered: ACCENT,
                        dragged: Color32::from_rgb(132, 184, 255),
                    },
                );
                if response.drag_started()
                    && let Some(start) = response.interact_pointer_pos()
                {
                    self.split_resize = Some(SplitResizeSession {
                        split: split.node.clone(),
                        revision: layout.revision,
                        divider,
                        initial_weights: split.weights.clone(),
                        current_weights: split.weights.clone(),
                        extent,
                        start,
                    });
                    self.status = "Resize split · release to apply".into();
                }
                if let Some(resize) = &mut self.split_resize
                    && resize.split == split.node
                    && resize.divider == divider
                    && (response.dragged() || response.drag_stopped())
                    && let Some(pointer) = ui.input(|input| input.pointer.interact_pos())
                {
                    let delta = pointer - resize.start;
                    let delta_axis = if horizontal { delta.x } else { delta.y };
                    resize.current_weights = resized_split_weights(
                        &resize.initial_weights,
                        resize.divider,
                        delta_axis,
                        resize.extent,
                    );
                }
            }
        }
    }

    fn finish_split_resize(&mut self) {
        let Some(resize) = self.split_resize.take() else {
            return;
        };
        let snapshot = self.workspace.dock.snapshot();
        if snapshot.revision != resize.revision {
            self.status = "Split resize cancelled because the layout changed".into();
            return;
        }
        match self.workspace.dock.transact(
            snapshot.revision,
            CommandId::from(format!(
                "resize-split-{}-r{}",
                resize.split.0, resize.revision
            )),
            [Operation::ResizeSplit {
                split: resize.split,
                weights: resize.current_weights,
            }],
        ) {
            Ok(_) => {
                self.workspace.save_layout();
                if let Some(error) = &self.workspace.persistence_error {
                    self.status = format!("Split resized; persistence failed: {error}");
                } else {
                    self.status = "Split resized".into();
                }
            }
            Err(error) => self.status = error.to_string(),
        }
    }

    fn begin_panel_drag(&mut self, panel: PanelId) {
        let snapshot = self.workspace.dock.snapshot();
        match DragSession::begin(snapshot.revision, vec![panel.clone()]) {
            Ok(drag) => {
                self.panel_drag = Some(drag);
                self.panel_drag_source = Some(panel);
                self.status = "Move panel · drop to tab or split".into();
            }
            Err(error) => self.status = error.to_string(),
        }
    }

    fn update_panel_drop_target(&mut self, ui: &Ui, panel_id: &str, rect: Rect) {
        let (Some(source), Some(drag)) = (&self.panel_drag_source, &mut self.panel_drag) else {
            return;
        };
        let target_panel = PanelId::from(panel_id);
        if source == &target_panel {
            return;
        }
        let Some(pointer) = ui.input(|input| input.pointer.hover_pos()) else {
            return;
        };
        if !rect.contains(pointer) {
            return;
        }
        let snapshot = self.workspace.dock.snapshot();
        let Some(node) = find_panel_node(snapshot.document.root.as_deref(), panel_id) else {
            return;
        };
        let edge = compute_drop_edge(rect, pointer);
        let target = PanelDropTarget {
            panel: target_panel,
            node,
            edge,
            preview: compute_drop_preview(rect, edge),
        };
        if let Err(error) = drag.update_preview(snapshot.revision, Some(target)) {
            self.status = error.to_string();
            self.panel_drag = None;
            self.panel_drag_source = None;
        }
    }

    fn paint_panel_drop_preview(&self, ui: &Ui) {
        let Some(target) = self
            .panel_drag
            .as_ref()
            .and_then(DragSession::preview_target)
        else {
            return;
        };
        ui.painter().rect_filled(
            target.preview,
            2.0,
            Color32::from_rgba_unmultiplied(104, 164, 245, 72),
        );
        ui.painter().rect_stroke(
            target.preview,
            2.0,
            Stroke::new(2.0, ACCENT),
            egui::StrokeKind::Inside,
        );
    }

    fn finish_panel_drag(&mut self) {
        let Some(drag) = self.panel_drag.take() else {
            return;
        };
        let source = self.panel_drag_source.take();
        let revision = self.workspace.dock.snapshot().revision;
        match drag.commit(revision) {
            Ok(Some(target)) => {
                let Some(source) = source else {
                    return;
                };
                self.commit_panel_drop(source, target);
            }
            Ok(None) => self.status = "Panel move cancelled".into(),
            Err(error) => self.status = error.to_string(),
        }
    }

    fn finish_tab_reorder(&mut self) -> bool {
        let Some(reorder) = self.tab_reorder.take() else {
            return false;
        };
        let Some(target_index) = reorder.target_index else {
            // No tab in the source strip is under the pointer at release; keep
            // the normal panel drag alive so it can commit a dock/split drop.
            return false;
        };
        self.panel_drag = None;
        self.panel_drag_source = None;
        let snapshot = self.workspace.dock.snapshot();
        if snapshot.revision != reorder.revision {
            self.status = "Tab reorder cancelled because the layout changed".into();
            return true;
        }
        let Some(source_index) = collect_dock_tab_groups(snapshot.document.root.as_deref())
            .into_iter()
            .find(|group| group.node == reorder.container)
            .and_then(|group| {
                group
                    .panels
                    .iter()
                    .position(|panel| panel == &reorder.source)
            })
        else {
            self.status = "Tab reorder cancelled because its source tab disappeared".into();
            return true;
        };
        if source_index == target_index {
            self.status = "Tab order unchanged".into();
            return true;
        }
        // ReorderPanel's index is the pre-removal insertion slot. Adjust it so
        // dropping on a tab means that tab's final canonical position.
        let insertion_index = if target_index > source_index {
            target_index + 1
        } else {
            target_index
        };
        match self.workspace.dock.transact(
            reorder.revision,
            CommandId::from(format!(
                "reorder-tab-{}-{}-r{}",
                reorder.container.0, reorder.source.0, reorder.revision
            )),
            [Operation::ReorderPanel {
                panel: reorder.source,
                container: reorder.container,
                index: insertion_index,
            }],
        ) {
            Ok(_) => {
                self.workspace.save_layout();
                self.status = "Dock tabs reordered".into();
            }
            Err(error) => self.status = error.to_string(),
        }
        true
    }

    fn finish_pinned_session_reorder(&mut self) {
        let Some(reorder) = self.pinned_session_reorder.take() else {
            return;
        };
        let Some(endpoint) = self.gateway_endpoint.as_ref() else {
            self.status =
                "Pinned-session reorder cancelled because the gateway disconnected".into();
            return;
        };
        if gateway_pin_order_scope(endpoint) != reorder.connection_key {
            self.status = "Pinned-session reorder cancelled because the gateway changed".into();
            return;
        }
        if self.workspace.pinned_session_order(&reorder.connection_key)
            != reorder.initial_persisted_order
        {
            self.status = "Pinned-session reorder cancelled because the saved order changed".into();
            return;
        }
        let mut order = reorder.visible_order;
        if !move_session_id(
            &mut order,
            &reorder.source_session_id,
            &reorder.target_session_id,
        ) {
            self.status = "Pinned-session order unchanged".into();
            return;
        }
        match self
            .workspace
            .reorder_pinned_session_order(&reorder.connection_key, order)
        {
            Ok(()) => self.status = "Pinned sessions reordered".into(),
            Err(error) => self.status = format!("Pinned-session reorder failed: {error}"),
        }
    }

    fn finish_recent_session_reorder(&mut self) {
        let Some(reorder) = self.recent_session_reorder.take() else {
            return;
        };
        let Some(endpoint) = self.gateway_endpoint.as_ref() else {
            self.status =
                "Recent-session reorder cancelled because the gateway disconnected".into();
            return;
        };
        if sidebar_recent_order_scope(endpoint) != reorder.scope_key {
            self.status = "Recent-session reorder cancelled because the profile changed".into();
            return;
        }
        if self.workspace.sidebar_session_order(&reorder.scope_key)
            != reorder.initial_persisted_order
        {
            self.status = "Recent-session reorder cancelled because the saved order changed".into();
            return;
        }
        if self.show_archived_sessions || !self.session_filter.trim().is_empty() {
            self.status =
                "Recent-session reorder cancelled because the session view changed".into();
            return;
        }
        let pin_order = self
            .workspace
            .pinned_session_order(&gateway_pin_order_scope(endpoint));
        let (_, recent) = partition_sidebar_sessions(self.sessions.clone(), &pin_order, true);
        let groups = session_date_groups_now(recent);
        let Some(group) = groups
            .iter()
            .find(|group| group.key == reorder.date_group_key)
        else {
            self.status = "Recent-session reorder cancelled because its date group changed".into();
            return;
        };
        let group_ids = group
            .sessions
            .iter()
            .map(|session| session.id.clone())
            .collect::<Vec<_>>();
        if group_ids.len() != reorder.date_group_ids.len()
            || group_ids.iter().cloned().collect::<BTreeSet<_>>()
                != reorder
                    .date_group_ids
                    .iter()
                    .cloned()
                    .collect::<BTreeSet<_>>()
            || !group_ids.iter().any(|id| id == &reorder.target_session_id)
        {
            self.status = "Recent-session reorder cancelled because its date group changed".into();
            return;
        }
        let mut reordered_group = reorder.date_group_ids.clone();
        if !move_session_id(
            &mut reordered_group,
            &reorder.source_session_id,
            &reorder.target_session_id,
        ) {
            self.status = "Recent-session order unchanged".into();
            return;
        }
        let mut all_order = reorder.visible_order;
        let Some(first_slot) = all_order
            .iter()
            .position(|id| reorder.date_group_ids.contains(id))
        else {
            self.status =
                "Recent-session reorder cancelled because the visible order changed".into();
            return;
        };
        let group_slots = all_order
            .iter()
            .enumerate()
            .filter_map(|(index, id)| reorder.date_group_ids.contains(id).then_some(index))
            .collect::<Vec<_>>();
        if group_slots.len() != reordered_group.len() {
            self.status =
                "Recent-session reorder cancelled because the visible order changed".into();
            return;
        }
        for (slot, id) in group_slots.into_iter().zip(reordered_group) {
            all_order[slot] = id;
        }
        if !all_order
            .iter()
            .skip(first_slot)
            .any(|id| reorder.date_group_ids.contains(id))
        {
            self.status =
                "Recent-session reorder cancelled because the visible order changed".into();
            return;
        }
        match self
            .workspace
            .set_sidebar_session_order(&reorder.scope_key, all_order)
        {
            Ok(()) => self.status = "Recent sessions reordered within date group".into(),
            Err(error) => self.status = format!("Recent-session reorder failed: {error}"),
        }
    }

    fn commit_panel_drop(&mut self, source: PanelId, target: PanelDropTarget) {
        let snapshot = self.workspace.dock.snapshot();
        let operation = panel_drop_operation(source, target);
        match self.workspace.dock.transact(
            snapshot.revision,
            CommandId::from("panel-drag-drop"),
            [operation],
        ) {
            Ok(_) => {
                self.workspace.save_layout();
                self.status = "Panel layout updated".into();
            }
            Err(error) => self.status = error.to_string(),
        }
    }

    fn cancel_panel_drag(&mut self) {
        self.panel_drag = None;
        self.panel_drag_source = None;
        self.status = "Panel move cancelled".into();
    }

    fn sessions_content(&mut self, ui: &mut egui::Ui) {
        ui.add_space(4.0);
        let new = ui.add_sized(
            [ui.available_width() - 20.0, 34.0],
            egui::Button::new(RichText::new("+  New session").color(TEXT)),
        );
        if new.clicked() {
            self.create_blank_session_tab();
        }
        self.sidebar_route(ui, AppRoute::Capabilities);
        self.sidebar_route(ui, AppRoute::Messaging);
        self.sidebar_route(ui, AppRoute::Artifacts);
        self.sidebar_route(ui, AppRoute::Cron);
        ui.add_space(18.0);
        let view_label = if self.show_archived_sessions {
            "Show active sessions"
        } else {
            "Show archived sessions"
        };
        if ui.button(view_label).accessible_name(view_label).clicked() {
            self.show_archived_sessions = !self.show_archived_sessions;
            self.session_search_request_id = None;
            self.session_search_pending = false;
            self.session_search_results.clear();
            self.session_search_error = None;
            self.session_search_changed_at = None;
            if self.show_archived_sessions {
                self.load_archived_sessions();
            } else if !self.session_filter.trim().is_empty() {
                self.session_search_changed_at = Some(std::time::Instant::now());
            }
        }
        let search = ui
            .add(
                egui::TextEdit::singleline(&mut self.session_filter)
                    .hint_text("Search sessions")
                    .desired_width(ui.available_width()),
            )
            .accessible_name("Search sessions");
        if search.changed() {
            let query_is_empty = self.session_filter.trim().is_empty();
            self.session_search_request_id = None;
            self.session_search_results.clear();
            self.session_search_error = None;
            self.session_search_pending = false;
            self.session_search_changed_at =
                (!query_is_empty && !self.show_archived_sessions).then(std::time::Instant::now);
        }
        let query = self.session_filter.trim().to_owned();
        if query.is_empty() {
            self.session_search_changed_at = None;
            self.session_search_request_id = None;
            self.session_search_pending = false;
            self.session_search_error = None;
            self.session_search_results.clear();
        } else if !self.show_archived_sessions
            && let Some(changed_at) = self.session_search_changed_at
        {
            let debounce = std::time::Duration::from_millis(200);
            if changed_at.elapsed() >= debounce {
                self.session_search_changed_at = None;
                if self.gateway_connected {
                    if let Some(gateway) = &self.gateway_discovery {
                        let request_id = operation_id("session-search");
                        match gateway.search_sessions(request_id.clone(), query.clone()) {
                            Ok(()) => {
                                self.session_search_request_id = Some(request_id);
                                self.session_search_pending = true;
                            }
                            Err(error) => {
                                self.session_search_error = Some(error);
                            }
                        }
                    }
                }
            } else {
                ui.ctx()
                    .request_repaint_after(debounce - changed_at.elapsed());
            }
        }
        ui.add_space(8.0);
        let tree_profile = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone());
        if !self.show_archived_sessions && query.is_empty() {
            if let Some(profile) = tree_profile.as_deref() {
                if let Some(tree) = self.project_trees.get(profile).cloned() {
                    let mut open_project_session = None;
                    let mut enter_project_id = None;
                    let mut delete_project_id = None;
                    let mut dismiss_auto_project_id = None;
                    let mut leave_project_view = false;
                    let mut retry_project_id = None;
                    let mut retry_project_list = false;
                    let mut request_preview_project_id = None;
                    let mut show_more_project_key = None;
                    let endpoint_instance_id = self
                        .gateway_endpoint
                        .as_ref()
                        .map(|endpoint| endpoint.instance_id.clone())
                        .unwrap_or_default();
                    if let Some(error) = self.project_list_errors.get(profile) {
                        ui.label(
                            RichText::new(format!("Project list refresh issue: {error}"))
                                .size(10.0)
                                .color(MUTED),
                        );
                        retry_project_list = ui.button("Retry project list").clicked();
                    }
                    ui.collapsing("Projects", |ui| {
                        if let Some(error) = &self.auto_project_dismissal_sync_error {
                            ui.label(
                                RichText::new(format!("Project visibility sync issue: {error}"))
                                    .size(10.0)
                                    .color(MUTED),
                            );
                        }
                        if let Some(error) = self.project_tree_errors.get(profile) {
                            ui.label(
                                RichText::new(format!("Project tree refresh issue: {error}"))
                                    .size(10.0)
                                    .color(MUTED),
                            );
                        }
                        if let Some(error) = self.project_delete_errors.get(profile) {
                            ui.label(
                                RichText::new(format!("Project deletion failed: {error}"))
                                    .size(10.0)
                                    .color(MUTED),
                            );
                        }
                        let mut show_all_project_sessions =
                            self.workspace.preferences.show_all_project_sessions;
                        if ui
                            .checkbox(&mut show_all_project_sessions, "Show all sessions")
                            .accessible_name("Show all project sessions")
                            .changed()
                        {
                            match self
                                .workspace
                                .set_show_all_project_sessions(show_all_project_sessions)
                            {
                                Ok(()) => self.refresh_project_tree_colors(None),
                                Err(error) => self.status = error,
                            }
                        }
                        if let Some(selected_id) = self
                            .selected_project_id
                            .as_deref()
                            .filter(|_| self.selected_project_profile.as_deref() == Some(profile))
                        {
                            if ui.button("← All projects").clicked() {
                                leave_project_view = true;
                            }
                            let project = self
                                .entered_project_tree
                                .as_ref()
                                .filter(|project| project.id == selected_id)
                                .or_else(|| {
                                    tree.projects.iter().find(|project| project.id == selected_id)
                                });
                            if let Some(project) = project {
                                ui.label(RichText::new(&project.label).strong());
                                if project.is_auto
                                    && !project.is_no_project
                                    && ui
                                        .button("Hide from sidebar")
                                        .accessible_name(format!(
                                            "Hide auto project {} from sidebar",
                                            project.id
                                        ))
                                        .clicked()
                                {
                                    dismiss_auto_project_id =
                                        Some((profile.to_owned(), project.id.clone()));
                                }
                                if let Some(path) = &project.path {
                                    ui.label(RichText::new(path).size(10.0).color(MUTED));
                                }
                                if self.project_sessions_refresh.is_some() {
                                    ui.label(
                                        RichText::new("Loading project sessions…")
                                            .size(10.0)
                                            .color(MUTED),
                                    );
                                }
                                if let Some(error) = &self.project_sessions_error {
                                    ui.label(
                                        RichText::new(format!("Project sessions unavailable: {error}"))
                                            .size(10.0)
                                            .color(MUTED),
                                    );
                                    if ui.button("Retry").clicked() {
                                        retry_project_id = Some(selected_id.to_owned());
                                    }
                                }
                                for repo in &project.repos {
                                    let repo_name = if repo.label.trim().is_empty() {
                                        repo.id.as_str()
                                    } else {
                                        repo.label.as_str()
                                    };
                                    ui.collapsing(
                                        format!("{repo_name} · {}", repo.session_count),
                                        |ui| {
                                            for group in &repo.groups {
                                                let group_name = if group.label.trim().is_empty() {
                                                    group.id.as_str()
                                                } else {
                                                    group.label.as_str()
                                                };
                                                ui.collapsing(group_name, |ui| {
                                                    if let Some(path) = &group.path {
                                                        ui.label(
                                                            RichText::new(path)
                                                                .size(10.0)
                                                                .color(MUTED),
                                                        );
                                                    }
                                                    for session in &group.sessions {
                                                        let title = if session.title.trim().is_empty() {
                                                            session.id.as_str()
                                                        } else {
                                                            session.title.as_str()
                                                        };
                                                        if ui
                                                            .selectable_label(false, title)
                                                            .accessible_name(format!(
                                                                "Open project session {} in profile {}",
                                                                session.id,
                                                                session.profile.as_deref().unwrap_or("unknown")
                                                            ))
                                                            .on_hover_text(&session.id)
                                                            .clicked()
                                                        {
                                                            open_project_session = Some(session.clone());
                                                        }
                                                    }
                                                });
                                            }
                                        },
                                    );
                                }
                            }
                        } else {
                        let mut visible_project_count = 0;
                        for project in &tree.projects {
                            if !project_tree_entry_is_visible(
                                project,
                                &self.workspace.preferences.dismissed_auto_project_ids,
                            ) {
                                continue;
                            }
                            visible_project_count += 1;
                            let preview_key = (
                                profile.to_owned(),
                                endpoint_instance_id.clone(),
                                project.id.clone(),
                            );
                            let expansion = self.project_preview_expansions.get(&preview_key);
                            let project_name = if project.label.trim().is_empty() {
                                project.id.as_str()
                            } else {
                                project.label.as_str()
                            };
                            let label = format!("{project_name} · {}", project.session_count);
                            let list_active_id = self.project_list_active_id(profile);
                            let active_project = list_active_id == Some(project.id.as_str());
                            let label = if active_project {
                                format!("{label} · Active")
                            } else {
                                label
                            };
                            ui.collapsing(label, |ui| {
                                if ui.button("Open project").clicked() {
                                    enter_project_id = Some(project.id.clone());
                                }
                                if project.is_auto
                                    && !project.is_no_project
                                    && ui
                                        .button("Hide from sidebar")
                                        .accessible_name(format!(
                                            "Hide auto project {} from sidebar",
                                            project.id
                                        ))
                                        .clicked()
                                {
                                    dismiss_auto_project_id =
                                        Some((profile.to_owned(), project.id.clone()));
                                }
                                if !profile.eq_ignore_ascii_case("all")
                                    && !project.is_auto
                                    && !project.is_no_project
                                    && ui
                                        .add_enabled(
                                            self.project_delete_pending.is_none(),
                                            egui::Button::new("Delete project…"),
                                        )
                                        .accessible_name(format!("Delete project {}", project.id))
                                        .clicked()
                                {
                                    delete_project_id = Some((profile.to_owned(), project.id.clone()));
                                }
                                let preview_total = project.session_count.max(project.preview_sessions.len());
                                if expansion.is_none()
                                    && !self.workspace.preferences.show_all_project_sessions
                                    && preview_total > project.preview_sessions.len()
                                    && ui.button(format!("Show all {preview_total} sessions")).clicked()
                                {
                                    if profile.eq_ignore_ascii_case("all") {
                                        enter_project_id = Some(project.id.clone());
                                    } else {
                                        request_preview_project_id = Some(project.id.clone());
                                    }
                                }
                                if self.project_preview_refreshes.values().any(|pending| pending.key == preview_key) {
                                    ui.label(RichText::new("Loading project sessions…").size(10.0).color(MUTED));
                                }
                                if let Some(error) = self.project_preview_errors.get(&preview_key) {
                                    ui.label(RichText::new(format!("Project sessions unavailable: {error}")).size(10.0).color(MUTED));
                                    if !profile.eq_ignore_ascii_case("all")
                                        && ui.button("Retry project sessions").clicked()
                                    {
                                        request_preview_project_id = Some(project.id.clone());
                                    }
                                }
                                if let Some(path) = &project.path {
                                    ui.label(RichText::new(path).size(10.0).color(MUTED));
                                }
                                if let Some(expansion) = expansion {
                                    let rows = merge_project_preview_sessions(
                                        &project.preview_sessions,
                                        &expansion.sessions,
                                        profile,
                                        &self.project_session_lifecycle,
                                    );
                                    for session in rows.iter().take(expansion.visible_count) {
                                        let title = if session.title.trim().is_empty() {
                                            session.id.as_str()
                                        } else {
                                            session.title.as_str()
                                        };
                                        if ui
                                            .selectable_label(false, title)
                                            .accessible_name(format!(
                                                "Open project session {} in profile {}",
                                                session.id,
                                                session.profile.as_deref().unwrap_or("unknown")
                                            ))
                                            .on_hover_text(&session.id)
                                            .clicked()
                                        {
                                            open_project_session = Some(session.clone());
                                        }
                                    }
                                    let remaining = rows.len().saturating_sub(expansion.visible_count);
                                    if remaining > 0 {
                                        let next_count = remaining.min(PROJECT_SESSION_PAGE_SIZE);
                                        if ui.button(format!("Show more {next_count} sessions")).clicked() {
                                            show_more_project_key = Some(preview_key.clone());
                                        }
                                    }
                                } else {
                                    for session in &project.preview_sessions {
                                        let title = if session.title.trim().is_empty() {
                                            session.id.as_str()
                                        } else {
                                            session.title.as_str()
                                        };
                                        if ui
                                            .selectable_label(false, title)
                                            .accessible_name(format!(
                                                "Open project session {} in profile {}",
                                                session.id,
                                                session.profile.as_deref().unwrap_or("unknown")
                                            ))
                                            .on_hover_text(&session.id)
                                            .clicked()
                                        {
                                            open_project_session = Some(session.clone());
                                        }
                                    }
                                }
                                for repo in &project.repos {
                                    let repo_name = if repo.label.trim().is_empty() {
                                        repo.id.as_str()
                                    } else {
                                        repo.label.as_str()
                                    };
                                    ui.collapsing(
                                        format!("{repo_name} · {}", repo.session_count),
                                        |ui| {
                                            if let Some(path) = &repo.path {
                                                ui.label(
                                                    RichText::new(path).size(10.0).color(MUTED),
                                                );
                                            }
                                            for group in &repo.groups {
                                                let group_name = if group.label.trim().is_empty() {
                                                    group.id.as_str()
                                                } else {
                                                    group.label.as_str()
                                                };
                                                ui.collapsing(group_name, |ui| {
                                                    if let Some(path) = &group.path {
                                                        ui.label(
                                                            RichText::new(path)
                                                                .size(10.0)
                                                                .color(MUTED),
                                                        );
                                                    }
                                                    if expansion.is_none() {
                                                    for session in &group.sessions {
                                                        let title =
                                                            if session.title.trim().is_empty() {
                                                                session.id.as_str()
                                                            } else {
                                                                session.title.as_str()
                                                            };
                                                        if ui
                                                            .selectable_label(false, title)
                                                            .accessible_name(format!(
                                                                "Open project session {} in profile {}",
                                                                session.id,
                                                                session.profile.as_deref().unwrap_or("unknown")
                                                            ))
                                                            .on_hover_text(&session.id)
                                                            .clicked()
                                                        {
                                                            open_project_session =
                                                                Some(session.clone());
                                                        }
                                                    }
                                                    }
                                                });
                                            }
                                        },
                                    );
                                }
                            });
                        }
                        if visible_project_count == 0 {
                            ui.label(RichText::new("No projects").size(11.0).color(MUTED));
                        }
                        }
                    });
                    if leave_project_view {
                        self.leave_project_sessions();
                    }
                    if let Some((profile_id, project_id)) = dismiss_auto_project_id {
                        self.dismiss_auto_project(&profile_id, &project_id);
                    }
                    if retry_project_list {
                        self.load_project_list(true);
                    }
                    if let Some((profile, project_id)) = delete_project_id {
                        self.project_delete_errors.remove(&profile);
                        self.project_delete_confirmation = Some((profile, project_id));
                    }
                    if let Some(project_id) = enter_project_id.or(retry_project_id) {
                        self.enter_project_sessions(&project_id);
                    }
                    if let Some(project_id) = request_preview_project_id {
                        self.request_project_preview(&project_id);
                    }
                    if let Some(key) = show_more_project_key {
                        self.reveal_more_project_preview(&key);
                    }
                    if let Some(session) = open_project_session {
                        self.execute_registered_action(RegisteredUiAction::OpenSession {
                            session_id: session.id,
                            profile: session.profile.or_else(|| {
                                (!profile.eq_ignore_ascii_case("all")).then(|| profile.to_owned())
                            }),
                        })
                        .unwrap_or_else(|error| self.status = error);
                    }
                } else {
                    ui.collapsing("Projects", |ui| {
                        if let Some(error) = self.project_tree_errors.get(profile) {
                            ui.label(
                                RichText::new(format!("Project tree unavailable: {error}"))
                                    .size(11.0)
                                    .color(MUTED),
                            );
                        } else {
                            ui.label(
                                RichText::new("Loading project tree…")
                                    .size(11.0)
                                    .color(MUTED),
                            );
                        }
                    });
                }
            }
        }
        self.project_delete_dialog(ui.ctx());
        let sessions = if self.show_archived_sessions {
            self.archived_sessions
                .iter()
                .filter(|session| session_matches_filter(session, &query))
                .cloned()
                .collect::<Vec<_>>()
        } else {
            merge_session_search_results(
                &self.sessions,
                &query,
                &self.session_search_results,
                self.session_search_pending,
            )
        };
        let no_sessions = sessions.is_empty();
        let pin_order = if !self.show_archived_sessions && query.is_empty() {
            self.gateway_endpoint
                .as_ref()
                .map(|endpoint| {
                    self.workspace
                        .pinned_session_order(&gateway_pin_order_scope(endpoint))
                })
                .unwrap_or_default()
        } else {
            Vec::new()
        };
        let (pinned_sessions, recent_sessions) = partition_sidebar_sessions(
            sessions,
            &pin_order,
            !self.show_archived_sessions && query.is_empty(),
        );
        let pinned_count = pinned_sessions.len();
        if pinned_count > 0 {
            ui.label(RichText::new("Pinned").size(12.0).color(MUTED));
        }
        let date_grouping_enabled = !self.show_archived_sessions && query.is_empty();
        let mut recent_groups = if date_grouping_enabled {
            session_date_groups_now(recent_sessions)
        } else {
            vec![RecentSessionDateGroup {
                key: "unfiltered".into(),
                label: None,
                sessions: recent_sessions,
            }]
        };
        let recent_reorder_enabled = date_grouping_enabled
            && self
                .gateway_endpoint
                .as_ref()
                .is_some_and(|endpoint| !endpoint.profile_id.eq_ignore_ascii_case("all"));
        let recent_order_scope = self
            .gateway_endpoint
            .as_ref()
            .filter(|_| recent_reorder_enabled)
            .map(sidebar_recent_order_scope);
        let persisted_recent_order = recent_order_scope
            .as_deref()
            .map(|scope| self.workspace.sidebar_session_order(scope))
            .unwrap_or_default();
        let current_recent_order = recent_groups
            .iter()
            .flat_map(|group| group.sessions.iter().map(|session| session.id.clone()))
            .collect::<Vec<_>>();
        let resolved_recent_order =
            reconcile_recent_session_order(&current_recent_order, &persisted_recent_order);
        order_recent_session_groups(&mut recent_groups, &resolved_recent_order);
        let recent_visible_order = recent_groups
            .iter()
            .flat_map(|group| group.sessions.iter().map(|session| session.id.clone()))
            .collect::<Vec<_>>();
        let mut rendered_sessions = pinned_sessions
            .iter()
            .cloned()
            .map(|session| (session, true, None, None, Vec::<String>::new()))
            .collect::<Vec<_>>();
        for group in &recent_groups {
            let group_ids = group
                .sessions
                .iter()
                .map(|session| session.id.clone())
                .collect::<Vec<_>>();
            for (index, session) in group.sessions.iter().cloned().enumerate() {
                rendered_sessions.push((
                    session,
                    false,
                    (index == 0).then(|| group.label.clone()).flatten(),
                    Some(group.key.clone()),
                    group_ids.clone(),
                ));
            }
        }
        if self.archived_sessions_loading && self.show_archived_sessions {
            ui.label(
                RichText::new("Loading archived sessions…")
                    .size(11.0)
                    .color(MUTED),
            );
        }
        if self.archived_sessions_error.is_some() && self.show_archived_sessions {
            ui.label(
                RichText::new(format!(
                    "Archived sessions unavailable: {}",
                    self.archived_sessions_error.as_deref().unwrap_or_default()
                ))
                .size(11.0)
                .color(MUTED),
            );
        }
        if self.session_search_pending && !self.show_archived_sessions {
            ui.label(
                RichText::new("Searching all sessions…")
                    .size(11.0)
                    .color(MUTED),
            );
        }
        if let Some(error) = self
            .session_search_error
            .as_ref()
            .filter(|_| !self.show_archived_sessions)
        {
            ui.label(
                RichText::new(format!("Full-history search unavailable: {error}"))
                    .size(11.0)
                    .color(MUTED),
            );
        }
        if let Some(error) = &self.session_list_error {
            ui.label(
                RichText::new(format!("Session recency refresh unavailable: {error}"))
                    .size(11.0)
                    .color(MUTED),
            );
        }
        if let Some(error) = self
            .session_peer_sync_error
            .as_deref()
            .filter(|_| self.session_list_error.is_none())
        {
            ui.label(
                RichText::new(format!("Cross-window session updates unavailable: {error}"))
                    .size(11.0)
                    .color(MUTED),
            );
        }
        if no_sessions {
            if self.show_archived_sessions && !self.archived_sessions_loading {
                ui.label(
                    RichText::new(if query.is_empty() {
                        "No archived sessions"
                    } else {
                        "No matching archived sessions"
                    })
                    .size(13.0)
                    .color(MUTED),
                );
            } else if !self.show_archived_sessions && query.is_empty() && self.sessions.is_empty() {
                ui.label(RichText::new("No sessions yet").size(13.0).color(MUTED));
            } else if !self.show_archived_sessions && !self.session_search_pending {
                ui.label(
                    RichText::new("No matching sessions")
                        .size(13.0)
                        .color(MUTED),
                );
            }
        }
        let mut pinned_row_rects = Vec::with_capacity(pinned_count);
        let mut recent_row_rects = Vec::with_capacity(recent_visible_order.len());
        let mut pinned_drag_stopped = false;
        let mut recent_heading_shown = false;
        for (session, pinned_row, date_group_label, date_group_key, date_group_ids) in
            rendered_sessions.drain(..)
        {
            if !pinned_row && !recent_heading_shown {
                if pinned_count > 0 {
                    ui.add_space(8.0);
                    ui.label(RichText::new("Recent sessions").size(12.0).color(MUTED));
                }
                recent_heading_shown = true;
            }
            if !pinned_row && let Some(label) = date_group_label {
                ui.add_space(8.0);
                ui.label(RichText::new(label).size(11.0).color(MUTED));
            }
            let title = if session.title.trim().is_empty() {
                session.id.clone()
            } else {
                session.title.clone()
            };
            let status_profile = session.profile.as_deref().or_else(|| {
                self.gateway_endpoint
                    .as_ref()
                    .map(|endpoint| endpoint.profile_id.as_str())
            });
            let live_status = status_profile.and_then(|profile| {
                self.active_session_statuses
                    .get(&(profile.to_owned(), session.id.clone()))
            });
            let status_label = match live_status.map(|status| status.status) {
                Some(ActiveSessionStatusKind::Working) => Some("working"),
                Some(ActiveSessionStatusKind::Waiting) => Some("waiting for input"),
                _ => None,
            };
            let visible_title = match status_label {
                Some("working") => format!("◌ {title}"),
                Some("waiting for input") => format!("! {title}"),
                _ => title.clone(),
            };
            let profile_label = session.profile.as_deref().unwrap_or_default();
            let foreign_profile = session.profile.as_deref().is_some_and(|profile| {
                self.gateway_endpoint
                    .as_ref()
                    .is_some_and(|endpoint| profile != endpoint.profile_id)
            });
            let scoped_profile_row =
                !profile_label.is_empty() && (self.show_archived_sessions || foreign_profile);
            let row_name = if scoped_profile_row {
                let owner = format!(
                    "{title}, profile {}, session {}",
                    session.profile.as_deref().unwrap_or_default(),
                    session.id
                );
                status_label.map_or(owner.clone(), |status| format!("{owner}, {status}"))
            } else {
                let owner = format!("{title}, session {}", session.id);
                status_label.map_or(owner.clone(), |status| format!("{owner}, {status}"))
            };
            let selected = self.route == AppRoute::Session(session.id.clone());
            let session_color_id = session.durable_session_id();
            let explicit_session_color = self.workspace.session_color(session_color_id);
            let project_profile = session.profile.as_deref().or_else(|| {
                self.gateway_endpoint
                    .as_ref()
                    .map(|endpoint| endpoint.profile_id.as_str())
            });
            let session_color = session_dot_color(
                explicit_session_color,
                project_profile,
                &session.id,
                session_color_id,
                &self.project_session_colors,
            );
            let mut row_response = None;
            let recent_row_reorderable =
                !pinned_row && recent_reorder_enabled && date_group_ids.len() > 1;
            if pinned_row && pinned_count > 1 {
                ui.horizontal(|ui| {
                    let handle = ui
                        .add_sized(
                            [22.0, 24.0],
                            egui::Button::new("⋮⋮")
                                .frame(false)
                                .sense(egui::Sense::drag()),
                        )
                        .accessible_name(format!("Reorder pinned session {}", session.id));
                    if handle.drag_started()
                        && let Some(endpoint) = self.gateway_endpoint.as_ref()
                    {
                        let connection_key = gateway_pin_order_scope(endpoint);
                        self.pinned_session_reorder = Some(PinnedSessionReorder {
                            initial_persisted_order: self
                                .workspace
                                .pinned_session_order(&connection_key),
                            connection_key,
                            source_session_id: session.id.clone(),
                            target_session_id: session.id.clone(),
                            visible_order: pinned_sessions
                                .iter()
                                .map(|session| session.id.clone())
                                .collect(),
                        });
                        self.status = "Reordering pinned sessions · release to move".into();
                    }
                    pinned_drag_stopped |= handle.drag_stopped();
                    ui.label(RichText::new("●").size(10.0).color(session_color));
                    row_response = Some(
                        ui.selectable_label(selected, RichText::new(&visible_title).color(TEXT)),
                    );
                });
            } else if recent_row_reorderable {
                ui.horizontal(|ui| {
                    let handle = ui
                        .add_sized(
                            [22.0, 24.0],
                            egui::Button::new("⋮⋮")
                                .frame(false)
                                .sense(egui::Sense::drag()),
                        )
                        .accessible_name(format!("Reorder recent session {}", session.id));
                    if handle.drag_started()
                        && let Some(scope_key) = recent_order_scope.as_ref()
                    {
                        self.recent_session_reorder = Some(RecentSessionReorder {
                            scope_key: scope_key.clone(),
                            source_session_id: session.id.clone(),
                            target_session_id: session.id.clone(),
                            date_group_key: date_group_key.clone().unwrap_or_default(),
                            date_group_ids: date_group_ids.clone(),
                            visible_order: recent_visible_order.clone(),
                            initial_persisted_order: self
                                .workspace
                                .sidebar_session_order(scope_key),
                        });
                        self.status =
                            "Reordering recent sessions within this date group · release to move"
                                .into();
                    }
                    ui.label(RichText::new("●").size(10.0).color(session_color));
                    row_response = Some(
                        ui.selectable_label(selected, RichText::new(&visible_title).color(TEXT)),
                    );
                });
            } else {
                ui.horizontal(|ui| {
                    ui.label(RichText::new("●").size(10.0).color(session_color));
                    row_response = Some(
                        ui.selectable_label(selected, RichText::new(&visible_title).color(TEXT)),
                    );
                });
            }
            let row = row_response
                .expect("session row is rendered in either the pinned or recent list")
                .accessible_name(row_name);
            if pinned_row {
                if self
                    .pinned_session_reorder
                    .as_ref()
                    .is_some_and(|reorder| reorder.target_session_id == session.id)
                {
                    ui.painter().rect_stroke(
                        row.rect,
                        2.0,
                        Stroke::new(1.5, ACCENT),
                        egui::StrokeKind::Inside,
                    );
                }
                pinned_row_rects.push((session.id.clone(), row.rect));
            } else if recent_row_reorderable {
                if self
                    .recent_session_reorder
                    .as_ref()
                    .is_some_and(|reorder| reorder.target_session_id == session.id)
                {
                    ui.painter().rect_stroke(
                        row.rect,
                        2.0,
                        Stroke::new(1.5, ACCENT),
                        egui::StrokeKind::Inside,
                    );
                }
                recent_row_rects.push((session.id.clone(), row.rect));
            }
            let row_gesture = if row.middle_clicked() {
                Some(SidebarSessionGesture::OpenInTab)
            } else if row.clicked() {
                Some(sidebar_session_gesture(sidebar_row_click_modifiers(
                    ui, row.rect,
                )))
            } else {
                None
            };
            if let Some(gesture) = row_gesture {
                let result = match gesture {
                    SidebarSessionGesture::ResumeInPlace => {
                        self.open_sidebar_session_in_place(session.clone())
                    }
                    SidebarSessionGesture::OpenInTab => {
                        self.open_sidebar_session_in_tab(session.clone())
                    }
                    SidebarSessionGesture::OpenInWindow => {
                        self.queue_sidebar_session_window(&session)
                    }
                    SidebarSessionGesture::TogglePin => {
                        self.start_session_pin_update(
                            session.clone(),
                            !(session.pinned || pinned_row),
                        );
                        Ok(())
                    }
                    SidebarSessionGesture::Archive => {
                        self.start_session_archive_update(session.clone(), !session.archived);
                        Ok(())
                    }
                };
                result.unwrap_or_else(|error| self.status = error);
            }
            let action_key = self.session_summary_identity_key(&session);
            let pin_pending = self.pending_session_pins.contains_key(&action_key);
            let unread_pending = self.pending_session_unreads.contains_key(&action_key);
            let archive_pending = self
                .pending_session_archives
                .contains_key(&self.session_summary_identity_key(&session));
            let rename_pending = self.pending_session_renames.contains_key(&action_key);
            let is_pinned = session.pinned || pinned_row;
            let pin_verb = if is_pinned { "Unpin" } else { "Pin" };
            let pin_label = if scoped_profile_row {
                format!("{pin_verb} profile {profile_label} session {}", session.id)
            } else if is_pinned {
                format!("Unpin session {}", session.id)
            } else {
                format!("Pin session {}", session.id)
            };
            let unread_verb = if session.unread {
                "Mark read"
            } else {
                "Mark unread"
            };
            let unread_label = if scoped_profile_row {
                format!(
                    "{unread_verb} profile {profile_label} session {}",
                    session.id
                )
            } else if session.unread {
                format!("Mark read session {}", session.id)
            } else {
                format!("Mark unread session {}", session.id)
            };
            let archive_verb = if session.archived {
                "Unarchive"
            } else {
                "Archive"
            };
            let archive_label = if scoped_profile_row {
                format!(
                    "{archive_verb} profile {profile_label} session {}",
                    session.id
                )
            } else if session.archived {
                format!("Unarchive session {}", session.id)
            } else {
                format!("Archive session {}", session.id)
            };
            let menu = ui.menu_button("⋯", |ui| {
                let rename_label = if scoped_profile_row {
                    format!("Rename profile {profile_label} session {}", session.id)
                } else {
                    format!("Rename session {}", session.id)
                };
                if ui
                    .add_enabled(
                        self.gateway_connected && !rename_pending,
                        egui::Button::new(rename_label),
                    )
                    .clicked()
                {
                    self.rename_draft = session.title.clone();
                    self.rename_session = Some(session.clone());
                    ui.close();
                }
                if ui
                    .add_enabled(
                        self.gateway_connected && !pin_pending,
                        egui::Button::new(&pin_label),
                    )
                    .clicked()
                {
                    self.start_session_pin_update(session.clone(), !is_pinned);
                    ui.close();
                }
                if ui
                    .add_enabled(
                        self.gateway_connected && !unread_pending,
                        egui::Button::new(&unread_label),
                    )
                    .clicked()
                {
                    self.start_session_unread_update(session.clone(), !session.unread);
                    ui.close();
                }
                if ui
                    .add_enabled(
                        self.gateway_connected && !archive_pending,
                        egui::Button::new(&archive_label),
                    )
                    .clicked()
                {
                    self.start_session_archive_update(session.clone(), !session.archived);
                    ui.close();
                }
                ui.menu_button("Appearance", |ui| {
                    let color_id = session.durable_session_id();
                    let selected_color = self.workspace.session_color(color_id).map(str::to_owned);
                    let mut chosen_color = None;
                    for hues in SESSION_COLOR_HUES.chunks(6) {
                        ui.horizontal(|ui| {
                            for hue in hues {
                                let color = format!("hsl({hue} 68% 58%)");
                                let selected = selected_color.as_deref() == Some(color.as_str());
                                let mut button = egui::Button::new(" ")
                                    .fill(session_swatch_color(*hue))
                                    .corner_radius(egui::CornerRadius::same(10));
                                if selected {
                                    button = button.stroke(Stroke::new(2.0, TEXT));
                                }
                                if ui
                                    .add_sized([20.0, 20.0], button)
                                    .accessible_name(format!("Color {color}"))
                                    .clicked()
                                {
                                    chosen_color = Some(color);
                                }
                            }
                        });
                    }
                    if let Some(color) = chosen_color {
                        match self.workspace.set_session_color(color_id, Some(&color)) {
                            Ok(()) => self.status = format!("Session color set to {color}"),
                            Err(error) => self.status = error,
                        }
                        ui.close();
                    }
                    if ui
                        .add_sized([132.0, 24.0], egui::Button::new("No color"))
                        .clicked()
                    {
                        match self.workspace.set_session_color(color_id, None) {
                            Ok(()) => self.status = "Session color cleared".into(),
                            Err(error) => self.status = error,
                        }
                        ui.close();
                    }
                });
            });
            let menu_name = if scoped_profile_row {
                format!(
                    "Session actions profile {profile_label} session {}",
                    session.id
                )
            } else {
                format!("Session actions session {}", session.id)
            };
            menu.response.accessible_name(menu_name);
            if !session.preview.is_empty() {
                ui.label(RichText::new(&session.preview).size(11.0).color(MUTED));
            }
            ui.label(
                RichText::new(format!(
                    "{} · {} messages · {}{}",
                    session_age_label(
                        session_recency_timestamp(&session),
                        std::time::SystemTime::now()
                            .duration_since(std::time::UNIX_EPOCH)
                            .map_or(0.0, |duration| duration.as_secs_f64())
                    ),
                    session.message_count,
                    if session.source.is_empty() {
                        "Hermes"
                    } else {
                        &session.source
                    },
                    if scoped_profile_row {
                        format!(" · profile {profile_label}")
                    } else {
                        String::new()
                    }
                ))
                .size(10.0)
                .color(MUTED),
            );
            ui.add_space(4.0);
        }
        if let Some(pointer) = ui.input(|input| input.pointer.interact_pos())
            && let Some((session_id, _)) = pinned_row_rects
                .iter()
                .find(|(_, rect)| rect.contains(pointer))
            && let Some(reorder) = &mut self.pinned_session_reorder
        {
            reorder.target_session_id = session_id.clone();
        }
        if let Some(pointer) = ui.input(|input| input.pointer.interact_pos())
            && let Some((session_id, _)) = recent_row_rects
                .iter()
                .find(|(_, rect)| rect.contains(pointer))
            && let Some(reorder) = &mut self.recent_session_reorder
        {
            reorder.target_session_id = session_id.clone();
        }
        if self.pinned_session_reorder.is_some()
            && (pinned_drag_stopped || ui.input(|input| input.pointer.primary_released()))
        {
            self.finish_pinned_session_reorder();
        } else if self.pinned_session_reorder.is_some()
            && ui.input(|input| input.key_pressed(egui::Key::Escape))
        {
            self.pinned_session_reorder = None;
            self.status = "Pinned-session reorder cancelled".into();
        } else if self.recent_session_reorder.is_some()
            && (pinned_drag_stopped || ui.input(|input| input.pointer.primary_released()))
        {
            self.finish_recent_session_reorder();
        } else if self.recent_session_reorder.is_some()
            && ui.input(|input| input.key_pressed(egui::Key::Escape))
        {
            self.recent_session_reorder = None;
            self.status = "Recent-session reorder cancelled".into();
        }
    }

    fn sidebar_route(&mut self, ui: &mut egui::Ui, target: AppRoute) {
        let selected = self.route == target;
        if ui.selectable_label(selected, target.title()).clicked() {
            let path = target.path();
            self.execute_registered_action(RegisteredUiAction::Navigate { path })
                .unwrap_or_else(|error| self.status = error);
        }
    }

    fn workspace_content(&mut self, ui: &mut egui::Ui) {
        if self.route.is_overlay() {
            return;
        }
        ui.add_space(24.0);
        match self.route.clone() {
            AppRoute::NewChat => self.new_chat_content(ui),
            AppRoute::Session(session_id) => self.session_content(ui, &session_id),
            AppRoute::Capabilities => self.capabilities_content(ui),
            AppRoute::Messaging => self.messaging_content(ui),
            AppRoute::Artifacts => self.artifacts_content(ui),
            AppRoute::Cron => self.cron_content(ui),
            AppRoute::Extension(_) => self.route_unavailable(
                ui,
                "This contributed route has no registered native renderer.",
            ),
            AppRoute::Unknown(path) => {
                self.route_unavailable(ui, &format!("Unknown Hermes route: {path}"))
            }
            overlay if overlay.is_overlay() => {
                self.route_unavailable(ui, "This screen is shown as an overlay.")
            }
            _ => self.route_unavailable(ui, "Connect to Hermes to continue."),
        }
        if matches!(self.route, AppRoute::NewChat | AppRoute::Session(_)) {
            self.approval_cards(ui);
            self.clarify_cards(ui);
            self.batch_clarify_cards(ui);
            self.composer(ui);
        }
    }

    fn step_transcript_find(&mut self, direction: isize) {
        let matches = transcript_search_matches(&self.transcript, &self.find_in_page_query);
        if matches.is_empty() {
            self.find_in_page_match = 0;
            self.find_in_page_target = None;
            self.find_in_page_scroll_pending = false;
            return;
        }
        let count = matches.len();
        self.find_in_page_match = if direction >= 0 {
            (self.find_in_page_match + 1) % count
        } else {
            (self.find_in_page_match + count - 1) % count
        };
        self.find_in_page_target = Some(matches[self.find_in_page_match]);
        self.find_in_page_scroll_pending = true;
    }

    fn transcript_find_bar(&mut self, ui: &mut Ui) {
        if !self.find_in_page_open {
            return;
        }

        let mut changed = false;
        let mut next = false;
        let mut previous = false;
        let mut close = false;
        ui.horizontal(|ui| {
            let response = ui
                .add(
                    egui::TextEdit::singleline(&mut self.find_in_page_query)
                        .id_salt("chat.find.query")
                        .desired_width(240.0)
                        .hint_text("Find in transcript"),
                )
                .accessible_name("Find in transcript");
            if self.find_in_page_focus_pending {
                response.request_focus();
                self.find_in_page_focus_pending = false;
            }
            changed = response.changed();
            let matches = transcript_search_matches(&self.transcript, &self.find_in_page_query);
            let label = if matches.is_empty() {
                "0/0".to_owned()
            } else {
                format!(
                    "{}/{}",
                    self.find_in_page_match.min(matches.len() - 1) + 1,
                    matches.len()
                )
            };
            ui.label(label)
                .on_hover_text("Matching messages in the loaded transcript");
            previous = ui
                .button("Previous")
                .on_hover_text("Previous match · Shift+Enter")
                .clicked();
            next = ui
                .button("Next")
                .on_hover_text("Next match · Enter")
                .clicked();
            close = ui
                .button("×")
                .on_hover_text("Close transcript search · Escape")
                .clicked();
            let enter =
                response.has_focus() && ui.input(|input| input.key_pressed(egui::Key::Enter));
            if enter {
                if ui.input(|input| input.modifiers.shift) {
                    previous = true;
                } else {
                    next = true;
                }
            }
        });

        if changed {
            self.find_in_page_match = 0;
            self.find_in_page_target =
                transcript_search_matches(&self.transcript, &self.find_in_page_query)
                    .first()
                    .copied();
            self.find_in_page_scroll_pending = self.find_in_page_target.is_some();
        }
        if close {
            self.find_in_page_open = false;
            self.find_in_page_query.clear();
            self.find_in_page_match = 0;
            self.find_in_page_target = None;
            self.find_in_page_scroll_pending = false;
            self.find_in_page_route = None;
            return;
        }

        if next || previous {
            self.step_transcript_find(if next { 1 } else { -1 });
        } else if transcript_search_matches(&self.transcript, &self.find_in_page_query).is_empty() {
            self.find_in_page_match = 0;
            self.find_in_page_target = None;
            self.find_in_page_scroll_pending = false;
        }
        ui.add_space(6.0);
    }

    fn session_content(&mut self, ui: &mut Ui, session_id: &str) {
        self.transcript_find_bar(ui);
        let resume_error = self
            .session_chat_views
            .get(&self.session_identity_key(session_id, self.active_session_profile.as_deref()))
            .and_then(|view| view.resume_error.clone());
        if let Some(error) = resume_error {
            ui.label(RichText::new("Couldn't open this session").color(Color32::LIGHT_RED));
            ui.label(RichText::new(error).size(12.0).color(MUTED));
            if ui
                .add_enabled(self.gateway_connected, egui::Button::new("Retry"))
                .accessible_name(format!("Retry opening session {session_id}"))
                .clicked()
            {
                self.retry_session_resume(session_id, self.active_session_profile.clone());
            }
        } else if self.transcript.is_empty() {
            if !self.gateway_connected {
                self.route_unavailable(ui, "Connect to Hermes to open this session.");
            } else if self.transcript_has_more {
                let loading = self.older_transcript_request.is_some();
                let load_older = ui
                    .add_enabled(
                        !loading,
                        egui::Button::new(if loading {
                            "Loading earlier messages…"
                        } else {
                            "Show earlier messages"
                        }),
                    )
                    .accessible_name(if loading {
                        "Loading earlier messages"
                    } else {
                        "Show earlier messages"
                    });
                if load_older.clicked() {
                    self.load_older_transcript(session_id.to_owned());
                }
                if let Some(error) = &self.older_transcript_error {
                    ui.label(RichText::new(error).size(12.0).color(Color32::LIGHT_RED));
                }
            } else if self.active_runtime_session_id.is_some() {
                self.route_unavailable(ui, "This session has no messages yet.");
            } else {
                self.route_unavailable(ui, &format!("Loading session {session_id}…"));
            }
        } else {
            if self.transcript_has_more {
                let loading = self.older_transcript_request.is_some();
                let load_older = ui
                    .add_enabled(
                        self.gateway_connected && !loading,
                        egui::Button::new(if loading {
                            "Loading earlier messages…"
                        } else {
                            "Show earlier messages"
                        }),
                    )
                    .accessible_name(if loading {
                        "Loading earlier messages"
                    } else {
                        "Show earlier messages"
                    });
                if load_older.clicked() {
                    self.load_older_transcript(session_id.to_owned());
                }
            }
            if let Some(error) = &self.older_transcript_error {
                ui.label(RichText::new(error).size(12.0).color(Color32::LIGHT_RED));
            }
            let messages = self.transcript.clone();
            let search_matches = transcript_search_matches(&messages, &self.find_in_page_query);
            let timestamps_enabled = self.timestamps_enabled;
            let technical_tool_payloads =
                self.workspace.preferences.mode == InterfaceMode::Advanced;
            let find_target = self.find_in_page_target;
            let scroll_target = self
                .find_in_page_scroll_pending
                .then_some(find_target)
                .flatten();
            if scroll_target.is_some_and(|index| index < messages.len()) {
                self.find_in_page_scroll_pending = false;
            }
            let retry_pending =
                self.active_runtime_session_id
                    .as_deref()
                    .is_some_and(|runtime_id| {
                        let key = self.session_identity_key(
                            runtime_id,
                            self.active_session_profile.as_deref(),
                        );
                        self.pending_submissions.contains_key(&key)
                    });
            let mut retry_failed_submission = None;
            let active_profile = self.active_session_profile.clone();
            let tool_images = messages
                .iter()
                .enumerate()
                .filter_map(|(index, message)| {
                    (message.get("type").and_then(|value| value.as_str()) == Some("tool_call"))
                        .then(|| {
                            tool_image_artifact(
                                message,
                                index,
                                session_id,
                                active_profile.as_deref(),
                            )
                        })
                        .flatten()
                        .map(|artifact| (index, artifact))
                })
                .collect::<BTreeMap<_, _>>();
            let markdown_cache = &mut self.markdown_cache;
            let mut open_tool_image = None;
            let mut request_tool_image_previews = Vec::new();
            egui::ScrollArea::vertical()
                .max_height((ui.available_height() - 76.0).max(120.0))
                .show(ui, |ui| {
                    ui.set_max_width(ui.available_width().min(860.0));
                    for (index, message) in messages.into_iter().enumerate() {
                        let (speaker, body) = transcript_message(&message);
                        let structured_error = structured_provider_error_presentation(&message);
                        let error_detail = message
                            .get("error")
                            .and_then(serde_json::Value::as_str)
                            .filter(|error| !error.trim().is_empty())
                            .map(str::to_owned);
                        let partial_content = message
                            .get("content")
                            .filter(|content| {
                                !content.is_null() && !content.as_str().is_some_and(str::is_empty)
                            })
                            .map(|content| bounded_transcript_value(content, 6_000));
                        let tool_image = tool_images.get(&index);
                        let matched = search_matches.contains(&index);
                        let selected_match = find_target == Some(index) && matched;
                        let frame = if matched {
                            egui::Frame::group(ui.style()).fill(if selected_match {
                                Color32::from_rgb(68, 57, 28)
                            } else {
                                Color32::from_rgb(43, 40, 31)
                            })
                        } else {
                            egui::Frame::group(ui.style())
                        };
                        let frame = if selected_match {
                            frame.stroke(egui::Stroke::new(1.0, Color32::from_rgb(236, 190, 82)))
                        } else {
                            frame
                        };
                        let entry = frame.show(ui, |ui| {
                            ui.label(RichText::new(speaker.clone()).strong().color(ACCENT));
                            if let Some(reasoning) = message
                                .get("reasoning")
                                .and_then(serde_json::Value::as_str)
                                .filter(|reasoning| !reasoning.trim().is_empty())
                                .filter(|_| self.reasoning_enabled)
                            {
                                let simple_mode =
                                    self.workspace.preferences.mode == InterfaceMode::Simple;
                                let streaming = message
                                    .get("streaming")
                                    .and_then(serde_json::Value::as_bool)
                                    == Some(true);
                                egui::CollapsingHeader::new("Thinking")
                                    .id_salt(("assistant-reasoning", session_id, index))
                                    .default_open(!simple_mode && streaming)
                                    .show(ui, |ui| {
                                        render_transcript_markdown(ui, markdown_cache, reasoning);
                                    });
                            }
                            if let Some((title, explanation)) = &structured_error {
                                ui.label(RichText::new(title).strong().color(Color32::LIGHT_RED));
                                ui.label(explanation);
                                if let Some(raw) = &error_detail {
                                    egui::CollapsingHeader::new("Details")
                                        .id_salt(("provider-error-details", session_id, index))
                                        .default_open(false)
                                        .show(ui, |ui| {
                                            render_transcript_markdown(ui, markdown_cache, raw);
                                        });
                                }
                                if let Some(partial) = &partial_content {
                                    ui.label(RichText::new("Partial response").strong());
                                    render_transcript_markdown(ui, markdown_cache, partial);
                                }
                            } else {
                                render_transcript_markdown(ui, markdown_cache, &body);
                            }
                            if let Some(artifact) = tool_image {
                                let remote = self
                                    .gateway_endpoint
                                    .as_ref()
                                    .is_some_and(|endpoint| endpoint.remote_auth.is_some());
                                ui.group(|ui| {
                                    if remote {
                                        self.file_previews.show_remote_image_thumbnail(
                                            ui,
                                            &artifact.id,
                                            self.artifact_image_previews.get(&artifact.id),
                                            egui::vec2(320.0, 220.0),
                                        );
                                        if ui.is_rect_visible(ui.min_rect()) {
                                            request_tool_image_previews.push(artifact.clone());
                                        }
                                    } else {
                                        self.file_previews.show_image_thumbnail(
                                            ui,
                                            &tool_image_local_path(&artifact.value),
                                            egui::vec2(320.0, 220.0),
                                        );
                                    }
                                    if ui
                                        .button("Open image")
                                        .accessible_name("Open tool image")
                                        .clicked()
                                    {
                                        open_tool_image = Some(artifact.clone());
                                    }
                                });
                            }
                            if technical_tool_payloads
                                && message.get("type").and_then(|value| value.as_str())
                                    == Some("tool_call")
                                && tool_payload_present(&message)
                            {
                                let tool_id = message
                                    .get("tool_call_id")
                                    .and_then(|value| value.as_str())
                                    .unwrap_or("tool");
                                let generation = message
                                    .get("execution_generation")
                                    .and_then(serde_json::Value::as_u64)
                                    .unwrap_or_default();
                                egui::CollapsingHeader::new("Tool payload")
                                    .id_salt((
                                        "tool-payload",
                                        session_id,
                                        index,
                                        tool_id,
                                        generation,
                                    ))
                                    .default_open(false)
                                    .show(ui, |ui| {
                                        if let Some(payload) = tool_payload_trace(&message) {
                                            egui::ScrollArea::vertical().max_height(180.0).show(
                                                ui,
                                                |ui| {
                                                    ui.add(
                                                        egui::Label::new(
                                                            RichText::new(payload)
                                                                .monospace()
                                                                .size(11.0),
                                                        )
                                                        .wrap(),
                                                    );
                                                },
                                            );
                                        }
                                    });
                            }
                            if let Some(submission_id) = message
                                .get("retry_submission_id")
                                .and_then(|value| value.as_str())
                                && message
                                    .get("error_surface")
                                    .and_then(|surface| surface.get("retryable"))
                                    .and_then(|value| value.as_bool())
                                    != Some(false)
                            {
                                let retry = ui
                                    .add_enabled(
                                        self.gateway_connected
                                            && !retry_pending
                                            && self.draft.trim().is_empty()
                                            && self.composer_attachments.is_empty(),
                                        egui::Button::new("Retry same message"),
                                    )
                                    .accessible_name(
                                        "Retry failed message with original submission ID",
                                    );
                                if retry.clicked() {
                                    retry_failed_submission = Some(submission_id.to_owned());
                                }
                            }
                            if timestamps_enabled
                                && let Some((started, completed)) = transcript_timestamp(&message)
                            {
                                let stamp = format_timeline_range(started, completed);
                                if !stamp.is_empty() {
                                    let tooltip = format_timeline_tooltip(started, completed);
                                    ui.horizontal(|ui| {
                                        ui.with_layout(
                                            egui::Layout::right_to_left(egui::Align::Center),
                                            |ui| {
                                                ui.label(
                                                    RichText::new(stamp)
                                                        .size(10.0)
                                                        .color(MUTED)
                                                        .monospace(),
                                                )
                                                .on_hover_text(tooltip);
                                            },
                                        );
                                    });
                                }
                            }
                        });
                        entry.response.widget_info(|| {
                            egui::WidgetInfo::labeled(
                                Role::Group,
                                true,
                                format!("{speaker}: {body}"),
                            )
                        });
                        if selected_match && scroll_target == Some(index) {
                            entry.response.scroll_to_me(Some(egui::Align::Center));
                        }
                        ui.add_space(8.0);
                    }
                });
            for artifact in request_tool_image_previews {
                self.request_remote_artifact_image_preview(&artifact);
            }
            if let Some(artifact) = open_tool_image {
                self.tool_image_lightbox = Some(ToolImageLightbox { artifact });
            }
            if let Some(lightbox) = self.tool_image_lightbox.clone() {
                let remote = self
                    .gateway_endpoint
                    .as_ref()
                    .is_some_and(|endpoint| endpoint.remote_auth.is_some());
                if remote {
                    self.request_remote_artifact_image_preview(&lightbox.artifact);
                }
                let mut visible = true;
                egui::Window::new(format!("Image · {}", lightbox.artifact.label))
                    .open(&mut visible)
                    .resizable(true)
                    .collapsible(false)
                    .default_size(egui::vec2(820.0, 620.0))
                    .show(ui.ctx(), |ui| {
                        if remote {
                            let max_size = ui.available_size();
                            self.file_previews.show_remote_image_thumbnail(
                                ui,
                                &lightbox.artifact.id,
                                self.artifact_image_previews.get(&lightbox.artifact.id),
                                max_size,
                            );
                        } else {
                            let max_size = ui.available_size();
                            self.file_previews.show_image_thumbnail(
                                ui,
                                &tool_image_local_path(&lightbox.artifact.value),
                                max_size,
                            );
                        }
                    });
                if !visible {
                    self.tool_image_lightbox = None;
                }
            }
            if let Some(submission_id) = retry_failed_submission {
                self.retry_failed_submission(&submission_id);
            }
        }
    }

    fn approval_cards(&mut self, ui: &mut Ui) {
        let Some(session_id) = self.active_runtime_session_id.as_deref() else {
            return;
        };
        let prompts = self
            .approval_prompts
            .values()
            .filter(|prompt| prompt.session_id == session_id)
            .cloned()
            .collect::<Vec<_>>();
        for prompt in prompts {
            ui.add_space(8.0);
            ui.group(|ui| {
                ui.label(RichText::new("Permission required").strong().color(ACCENT));
                if !prompt.command.is_empty() {
                    ui.label(RichText::new(&prompt.command).monospace().color(TEXT));
                }
                if !prompt.description.is_empty() {
                    ui.label(RichText::new(&prompt.description).color(MUTED));
                }
                ui.horizontal_wrapped(|ui| {
                    for choice in &prompt.choices {
                        let pending = prompt.response_pending.is_some();
                        let label = match choice.as_str() {
                            "once" => "Allow once",
                            "session" => "Allow this session",
                            "always" => "Always allow",
                            "deny" => "Deny",
                            _ => continue,
                        };
                        let response = ui
                            .add_enabled(
                                self.gateway_connected && !pending,
                                egui::Button::new(label),
                            )
                            .accessible_name(format!("{label} approval {}", prompt.prompt_id));
                        if response.clicked() {
                            self.execute_registered_action(RegisteredUiAction::RespondApproval {
                                prompt_id: prompt.prompt_id.clone(),
                                choice: choice.clone(),
                            })
                            .unwrap_or_else(|error| self.status = error);
                        }
                    }
                    if prompt.response_pending.is_some() {
                        ui.label(RichText::new("Sending decision…").color(MUTED));
                    }
                });
            });
        }
    }

    fn clarify_cards(&mut self, ui: &mut Ui) {
        let Some(session_id) = self.active_runtime_session_id.as_deref() else {
            return;
        };
        let prompts = self
            .clarify_prompts
            .values()
            .filter(|prompt| prompt.session_id == session_id)
            .cloned()
            .collect::<Vec<_>>();
        for prompt in prompts {
            ui.add_space(8.0);
            ui.group(|ui| {
                ui.label(RichText::new(&prompt.question).strong().color(ACCENT));
                if !prompt.choices.is_empty() {
                    ui.horizontal_wrapped(|ui| {
                        for choice in &prompt.choices {
                            let selected = prompt.selected.contains(choice);
                            let response = ui.add_enabled_ui(
                                self.gateway_connected && prompt.response_pending.is_none(),
                                |ui| {
                                    ui.selectable_label(selected, choice)
                                        .accessible_name(format!(
                                            "Clarify choice {} for {}",
                                            choice, prompt.prompt_id
                                        ))
                                },
                            );
                            if response.inner.clicked()
                                && let Some(current) =
                                    self.clarify_prompts.get_mut(&prompt.prompt_id)
                            {
                                if current.multi_select {
                                    if let Some(index) = current
                                        .selected
                                        .iter()
                                        .position(|selected| selected == choice)
                                    {
                                        current.selected.remove(index);
                                    } else {
                                        current.selected.push(choice.clone());
                                    }
                                } else {
                                    current.selected.clear();
                                    current.selected.push(choice.clone());
                                }
                            }
                        }
                    });
                }
                let draft = self
                    .clarify_prompts
                    .get_mut(&prompt.prompt_id)
                    .map(|current| &mut current.draft);
                if let Some(draft) = draft {
                    ui.add(
                        egui::TextEdit::singleline(draft)
                            .desired_width(ui.available_width())
                            .hint_text("Type your answer…"),
                    )
                    .accessible_name(format!("Clarify answer {}", prompt.prompt_id));
                }
                ui.horizontal(|ui| {
                    let answer = clarify_answer(&prompt);
                    let pending = prompt.response_pending.is_some();
                    let submit = ui
                        .add_enabled(
                            self.gateway_connected && !pending && !answer.is_empty(),
                            egui::Button::new("Continue"),
                        )
                        .accessible_name(format!("Submit clarify answer {}", prompt.prompt_id));
                    if submit.clicked() {
                        self.execute_registered_action(RegisteredUiAction::RespondClarify {
                            prompt_id: prompt.prompt_id.clone(),
                            answer,
                        })
                        .unwrap_or_else(|error| self.status = error);
                    }
                    let skip = ui
                        .add_enabled(
                            self.gateway_connected && !pending,
                            egui::Button::new("Skip"),
                        )
                        .accessible_name(format!("Skip clarify request {}", prompt.prompt_id));
                    if skip.clicked() {
                        self.execute_registered_action(RegisteredUiAction::RespondClarify {
                            prompt_id: prompt.prompt_id.clone(),
                            answer: String::new(),
                        })
                        .unwrap_or_else(|error| self.status = error);
                    }
                    if pending {
                        ui.label(RichText::new("Sending answer…").color(MUTED));
                    }
                });
            });
        }
    }

    fn batch_clarify_cards(&mut self, ui: &mut Ui) {
        let Some(session_id) = self.active_runtime_session_id.as_deref() else {
            return;
        };
        let prompts = self
            .batch_clarify_prompts
            .values()
            .filter(|prompt| prompt.session_id == session_id)
            .cloned()
            .collect::<Vec<_>>();
        for prompt in prompts {
            ui.add_space(8.0);
            ui.group(|ui| {
                let answered = prompt
                    .questions
                    .iter()
                    .filter(|question| batch_question_answer(question).is_some())
                    .count();
                ui.label(
                    RichText::new(if prompt.questions.len() == 1 {
                        "1 question".to_owned()
                    } else {
                        format!("{answered} of {} answered", prompt.questions.len())
                    })
                    .size(11.0)
                    .color(MUTED),
                );
                for question in &prompt.questions {
                    ui.add_space(6.0);
                    ui.horizontal(|ui| {
                        ui.label(RichText::new(&question.question).strong().color(TEXT))
                            .accessible_name(format!(
                                "Clarify question {}: {}",
                                question.qid, question.question
                            ));
                        if !question.choices.is_empty() {
                            ui.label(
                                RichText::new(if question.multi_select {
                                    "Select all that apply"
                                } else {
                                    "Pick one"
                                })
                                .size(10.0)
                                .color(MUTED),
                            );
                        }
                    });
                    if !question.choices.is_empty() {
                        ui.horizontal_wrapped(|ui| {
                            for choice in &question.choices {
                                let selected = question.selected.contains(choice);
                                let response = ui.add_enabled_ui(
                                    self.gateway_connected && !prompt.response_pending,
                                    |ui| {
                                        ui.selectable_label(selected, choice).accessible_name(
                                            format!("Clarify choice {choice} for {}", question.qid),
                                        )
                                    },
                                );
                                if response.inner.clicked()
                                    && let Some(current) = self
                                        .batch_clarify_prompts
                                        .get_mut(&prompt.server_request_id)
                                    && let Some(current_question) = current
                                        .questions
                                        .iter_mut()
                                        .find(|candidate| candidate.qid == question.qid)
                                {
                                    if current_question.multi_select {
                                        if let Some(index) = current_question
                                            .selected
                                            .iter()
                                            .position(|selected| selected == choice)
                                        {
                                            current_question.selected.remove(index);
                                        } else {
                                            current_question.selected.push(choice.clone());
                                        }
                                    } else {
                                        current_question.selected.clear();
                                        current_question.selected.push(choice.clone());
                                    }
                                }
                            }
                        });
                    }
                    let draft = self
                        .batch_clarify_prompts
                        .get_mut(&prompt.server_request_id)
                        .and_then(|current| {
                            current
                                .questions
                                .iter_mut()
                                .find(|candidate| candidate.qid == question.qid)
                        })
                        .map(|current| &mut current.draft);
                    if let Some(draft) = draft {
                        let changed = ui
                            .add(
                                egui::TextEdit::singleline(draft)
                                    .desired_width(ui.available_width())
                                    .hint_text("Type your answer…"),
                            )
                            .accessible_name(format!(
                                "Clarify answer {} for {}",
                                question.qid, prompt.server_request_id
                            ))
                            .changed();
                        if changed
                            && !question.multi_select
                            && let Some(current) = self
                                .batch_clarify_prompts
                                .get_mut(&prompt.server_request_id)
                            && let Some(current_question) = current
                                .questions
                                .iter_mut()
                                .find(|candidate| candidate.qid == question.qid)
                        {
                            current_question.selected.clear();
                        }
                    }
                }

                ui.horizontal(|ui| {
                    let answer = batch_clarify_answer(&prompt);
                    let submit = ui
                        .add_enabled(
                            self.gateway_connected && !prompt.response_pending && answer.is_some(),
                            egui::Button::new("Confirm and continue"),
                        )
                        .accessible_name(format!(
                            "Confirm and continue clarify answers {}",
                            prompt.server_request_id
                        ));
                    if submit.clicked()
                        && let Some(answer) = answer
                    {
                        self.execute_registered_action(RegisteredUiAction::RespondClarify {
                            prompt_id: prompt.server_request_id.clone(),
                            answer,
                        })
                        .unwrap_or_else(|error| self.status = error);
                    }
                    let skip = ui
                        .add_enabled(
                            self.gateway_connected && !prompt.response_pending,
                            egui::Button::new("Skip"),
                        )
                        .accessible_name(format!(
                            "Skip clarify request {}",
                            prompt.server_request_id
                        ));
                    if skip.clicked() {
                        self.execute_registered_action(RegisteredUiAction::RespondClarify {
                            prompt_id: prompt.server_request_id.clone(),
                            answer: String::new(),
                        })
                        .unwrap_or_else(|error| self.status = error);
                    }
                    if prompt.response_pending {
                        ui.label(RichText::new("Sending answers…").color(MUTED));
                    }
                });
            });
        }
    }

    fn load_artifacts(&mut self) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before indexing artifacts".into());
        }
        let request_id = operation_id("artifacts");
        let gateway = self
            .gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes gateway reader is unavailable".to_owned())?;
        gateway.load_artifacts(request_id.clone())?;
        self.artifacts_request_id = Some(request_id);
        self.artifacts_error = None;
        Ok(())
    }

    fn request_remote_artifact_image_preview(&mut self, artifact: &ArtifactRecord) {
        if self.artifact_image_previews.contains_key(&artifact.id)
            || self
                .pending_artifact_image_previews
                .values()
                .any(|id| id == &artifact.id)
        {
            return;
        }
        let Some(endpoint) = self
            .gateway_endpoint
            .as_ref()
            .filter(|endpoint| endpoint.remote_auth.is_some())
        else {
            return;
        };
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            return;
        };
        let request_id = operation_id("artifact-image-preview");
        let request = ArtifactImagePreviewRequest {
            request_id: request_id.clone(),
            artifact_id: artifact.id.clone(),
            path: artifact.value.clone(),
            session_id: artifact.session_id.clone(),
            profile: artifact
                .profile
                .as_deref()
                .unwrap_or(&endpoint.profile_id)
                .to_owned(),
        };
        match gateway.load_artifact_image_preview(request) {
            Ok(()) => {
                self.pending_artifact_image_previews
                    .insert(request_id, artifact.id.clone());
            }
            Err(error) => {
                self.artifact_image_previews
                    .insert(artifact.id.clone(), Err(error));
            }
        }
    }

    fn open_artifact(&mut self, artifact: &ArtifactRecord) {
        let remote = self
            .gateway_endpoint
            .as_ref()
            .is_some_and(|endpoint| endpoint.remote_auth.is_some());
        if remote && artifact.kind != ArtifactKind::Link {
            let Some(profile) = artifact.profile.clone().or_else(|| {
                self.gateway_endpoint
                    .as_ref()
                    .map(|endpoint| endpoint.profile_id.clone())
            }) else {
                self.status = "The remote artifact has no originating profile".into();
                return;
            };
            let request_id = operation_id("artifact-download");
            let request = ArtifactFileDownloadRequest {
                request_id: request_id.clone(),
                path: artifact.value.clone(),
                session_id: artifact.session_id.clone(),
                profile,
            };
            let Some(gateway) = self.gateway_discovery.as_ref() else {
                self.status = "Remote Hermes gateway is unavailable for file download".into();
                return;
            };
            match gateway.download_artifact_file(request) {
                Ok(()) => {
                    self.pending_artifact_downloads
                        .insert(request_id, artifact.label.clone());
                    self.status = format!("Preparing {} for download…", artifact.label);
                }
                Err(error) => {
                    self.status = format!("Could not start {} download: {error}", artifact.label)
                }
            }
            return;
        }
        let target = if artifact.kind == ArtifactKind::Link {
            &artifact.href
        } else {
            &artifact.value
        };
        match open::that(target) {
            Ok(()) => self.status = format!("Opened {}", artifact.label),
            Err(error) => self.status = format!("Could not open {}: {error}", artifact.label),
        }
    }

    fn open_artifact_session(&mut self, artifact: &ArtifactRecord) {
        if let Err(error) = self.execute_registered_action(RegisteredUiAction::OpenSession {
            session_id: artifact.session_id.clone(),
            profile: artifact.profile.clone(),
        }) {
            self.status = error;
        }
    }

    fn artifacts_content(&mut self, ui: &mut egui::Ui) {
        if !self.gateway_connected {
            self.route_unavailable(ui, "Connect to Hermes to index recent session artifacts.");
            return;
        }
        if self.artifacts.is_none()
            && self.artifacts_error.is_none()
            && self.artifacts_request_id.is_none()
        {
            if let Err(error) = self.load_artifacts() {
                self.artifacts_error = Some(error);
            }
        }
        ui.horizontal(|ui| {
            ui.vertical(|ui| {
                ui.heading("Artifacts");
                ui.label(
                    RichText::new("Files, images, and links from your recent Hermes sessions")
                        .color(MUTED),
                );
            });
            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                let loading = self.artifacts_request_id.is_some();
                if ui
                    .add_enabled(
                        !loading,
                        egui::Button::new(if loading { "Indexing…" } else { "Refresh" }),
                    )
                    .on_hover_text("Index the 30 most recent sessions")
                    .clicked()
                {
                    if let Err(error) = self.load_artifacts() {
                        self.artifacts_error = Some(error);
                    }
                }
            });
        });
        ui.add_space(10.0);

        let snapshot = self.artifacts.as_ref();
        let counts = snapshot
            .map(|snapshot| {
                let images = snapshot
                    .artifacts
                    .iter()
                    .filter(|item| item.kind == ArtifactKind::Image)
                    .count();
                let files = snapshot
                    .artifacts
                    .iter()
                    .filter(|item| item.kind == ArtifactKind::File)
                    .count();
                let links = snapshot
                    .artifacts
                    .iter()
                    .filter(|item| item.kind == ArtifactKind::Link)
                    .count();
                [snapshot.artifacts.len(), images, files, links]
            })
            .unwrap_or([0; 4]);
        ui.horizontal_wrapped(|ui| {
            for (index, filter) in ArtifactFilter::ALL.into_iter().enumerate() {
                let selected = self.artifacts_filter == filter;
                let label = format!(
                    "{}  {}",
                    match filter {
                        ArtifactFilter::All => "All",
                        ArtifactFilter::Image => "Images",
                        ArtifactFilter::File => "Files",
                        ArtifactFilter::Link => "Links",
                    },
                    counts[index]
                );
                if ui.selectable_label(selected, label).clicked() {
                    self.artifacts_filter = filter;
                    self.artifacts_image_page = 1;
                    self.artifacts_file_page = 1;
                }
            }
        });
        if counts[0] > 0 {
            let response = ui.add(
                egui::TextEdit::singleline(&mut self.artifacts_query)
                    .hint_text("Search files, links, and sessions…")
                    .desired_width(ui.available_width()),
            );
            response.widget_info(|| {
                egui::WidgetInfo::text_edit(
                    true,
                    &self.artifacts_query,
                    &self.artifacts_query,
                    "Search artifacts",
                )
            });
            if response.changed() {
                self.artifacts_image_page = 1;
                self.artifacts_file_page = 1;
            }
        }
        if let Some(error) = &self.artifacts_error {
            ui.colored_label(
                Color32::from_rgb(239, 131, 126),
                format!("Artifacts could not be loaded: {error}"),
            );
        }
        if let Some(snapshot) = snapshot {
            if !snapshot.failures.is_empty() {
                ui.colored_label(
                    MUTED,
                    format!(
                        "Skipped {} of {} recent sessions while indexing artifacts",
                        snapshot.failures.len(),
                        snapshot.session_count
                    ),
                );
            }
        }
        let Some(snapshot) = snapshot else {
            if self.artifacts_request_id.is_some() {
                ui.spinner();
                ui.label("Indexing recent sessions…");
            }
            return;
        };
        let query = self.artifacts_query.trim().to_lowercase();
        let matching = snapshot
            .artifacts
            .iter()
            .filter(|item| {
                self.artifacts_filter.matches(item.kind)
                    && (query.is_empty()
                        || item.label.to_lowercase().contains(&query)
                        || item.value.to_lowercase().contains(&query)
                        || item.session_title.to_lowercase().contains(&query))
            })
            .cloned()
            .collect::<Vec<_>>();
        if matching.is_empty() {
            ui.vertical_centered(|ui| {
                ui.add_space((ui.available_height() * 0.28).max(12.0));
                ui.label(RichText::new(if snapshot.artifacts.is_empty() { "No artifacts found" } else { "No artifacts match this search" }).strong());
                ui.label(RichText::new("Artifacts are collected from assistant and tool messages in recent sessions.").color(MUTED));
            });
            return;
        }
        let image_items = matching
            .iter()
            .filter(|item| item.kind == ArtifactKind::Image)
            .cloned()
            .collect::<Vec<_>>();
        let other_items = matching
            .iter()
            .filter(|item| item.kind != ArtifactKind::Image)
            .cloned()
            .collect::<Vec<_>>();
        let image_page_count = image_items.len().div_ceil(24).max(1);
        let file_page_count = other_items.len().div_ceil(100).max(1);
        self.artifacts_image_page = self.artifacts_image_page.clamp(1, image_page_count);
        self.artifacts_file_page = self.artifacts_file_page.clamp(1, file_page_count);
        egui::ScrollArea::vertical()
            .auto_shrink([false, false])
            .show(ui, |ui| {
                if !image_items.is_empty() {
                    let start = (self.artifacts_image_page - 1) * 24;
                    let end = (start + 24).min(image_items.len());
                    ui.horizontal(|ui| {
                        ui.label(
                            RichText::new(format!("{} images", image_items.len())).color(MUTED),
                        );
                        ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                            if ui
                                .add_enabled(
                                    self.artifacts_image_page < image_page_count,
                                    egui::Button::new("Next →"),
                                )
                                .clicked()
                            {
                                self.artifacts_image_page += 1;
                            }
                            if ui
                                .add_enabled(
                                    self.artifacts_image_page > 1,
                                    egui::Button::new("← Previous"),
                                )
                                .clicked()
                            {
                                self.artifacts_image_page -= 1;
                            }
                            ui.label(format!(
                                "Page {} of {}",
                                self.artifacts_image_page, image_page_count
                            ));
                        });
                    });
                    let card_columns = (ui.available_width() / 218.0).floor().max(1.0) as usize;
                    for row in image_items[start..end].chunks(card_columns) {
                        ui.horizontal(|ui| {
                            for artifact in row {
                                ui.push_id(&artifact.id, |ui| {
                                    egui::Frame::group(ui.style()).show(ui, |ui| {
                                        ui.set_width(210.0);
                                        ui.set_min_height(138.0);
                                        ui.vertical(|ui| {
                                            let image_path = std::path::Path::new(&artifact.value);
                                            ui.allocate_ui_with_layout(
                                                Vec2::new(198.0, 94.0),
                                                Layout::centered_and_justified(
                                                    egui::Direction::LeftToRight,
                                                ),
                                                |ui| {
                                                    let remote_gateway = self
                                                        .gateway_endpoint
                                                        .as_ref()
                                                        .is_some_and(|endpoint| {
                                                            endpoint.remote_auth.is_some()
                                                        });
                                                    if remote_gateway
                                                        && is_remote_artifact_image_source(
                                                            &artifact.value,
                                                        )
                                                    {
                                                        self.request_remote_artifact_image_preview(
                                                            artifact,
                                                        );
                                                        self.file_previews
                                                            .show_remote_image_thumbnail(
                                                                ui,
                                                                &artifact.id,
                                                                self.artifact_image_previews
                                                                    .get(&artifact.id),
                                                                Vec2::new(194.0, 90.0),
                                                            );
                                                    } else if image_path.is_absolute()
                                                        && !remote_gateway
                                                    {
                                                        self.file_previews.show_image_thumbnail(
                                                            ui,
                                                            image_path,
                                                            Vec2::new(194.0, 90.0),
                                                        );
                                                    } else {
                                                        ui.label(
                                                            RichText::new("▧")
                                                                .size(34.0)
                                                                .color(ACCENT),
                                                        );
                                                    }
                                                },
                                            );
                                            ui.label(RichText::new(&artifact.label).strong());
                                            ui.label(
                                                RichText::new(&artifact.value).color(MUTED).small(),
                                            );
                                            ui.label(
                                                RichText::new(format!(
                                                    "{} · {}",
                                                    artifact.session_title,
                                                    format_artifact_timestamp(
                                                        artifact.timestamp_ms
                                                    )
                                                ))
                                                .color(MUTED)
                                                .small(),
                                            );
                                            ui.horizontal(|ui| {
                                                if ui.button("Open").clicked() {
                                                    self.open_artifact(artifact);
                                                }
                                                if ui.button("Open chat").clicked() {
                                                    self.open_artifact_session(artifact);
                                                }
                                            });
                                        });
                                    });
                                });
                            }
                        });
                    }
                }
                if !other_items.is_empty() {
                    let start = (self.artifacts_file_page - 1) * 100;
                    let end = (start + 100).min(other_items.len());
                    ui.add_space(12.0);
                    ui.horizontal(|ui| {
                        ui.label(
                            RichText::new(format!(
                                "{} {}",
                                other_items.len(),
                                if self.artifacts_filter == ArtifactFilter::Link {
                                    "links"
                                } else {
                                    "files and links"
                                }
                            ))
                            .color(MUTED),
                        );
                        ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                            if ui
                                .add_enabled(
                                    self.artifacts_file_page < file_page_count,
                                    egui::Button::new("Next →"),
                                )
                                .clicked()
                            {
                                self.artifacts_file_page += 1;
                            }
                            if ui
                                .add_enabled(
                                    self.artifacts_file_page > 1,
                                    egui::Button::new("← Previous"),
                                )
                                .clicked()
                            {
                                self.artifacts_file_page -= 1;
                            }
                            ui.label(format!(
                                "Page {} of {}",
                                self.artifacts_file_page, file_page_count
                            ));
                        });
                    });
                    egui::Grid::new("artifacts-table")
                        .striped(true)
                        .num_columns(4)
                        .min_col_width(140.0)
                        .show(ui, |ui| {
                            ui.strong("Artifact");
                            ui.strong("Location");
                            ui.strong("Session");
                            ui.strong("Actions");
                            ui.end_row();
                            for artifact in &other_items[start..end] {
                                ui.label(RichText::new(&artifact.label).strong());
                                ui.label(RichText::new(&artifact.value).monospace().color(MUTED));
                                ui.label(format!(
                                    "{}
{}",
                                    artifact.session_title,
                                    format_artifact_timestamp(artifact.timestamp_ms)
                                ));
                                ui.horizontal(|ui| {
                                    if artifact.kind == ArtifactKind::Link {
                                        if ui.button("Open link").clicked() {
                                            self.open_artifact(artifact);
                                        }
                                    } else if ui.button("Open file").clicked() {
                                        self.open_artifact(artifact);
                                    }
                                    if ui.button("Chat").clicked() {
                                        self.open_artifact_session(artifact);
                                    }
                                });
                                ui.end_row();
                            }
                        });
                }
            });
    }

    fn request_cron_jobs(&mut self) {
        if self.cron_jobs_request.is_some() || !self.gateway_connected {
            return;
        }
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            self.cron_jobs_error = Some("Hermes gateway reader is unavailable".into());
            return;
        };
        let profile = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone());
        let request_id = operation_id("cron-jobs");
        match gateway.load_cron_jobs(request_id.clone(), profile.clone()) {
            Ok(()) => {
                self.cron_jobs_request = Some((request_id, profile.clone()));
                self.cron_jobs_profile = profile;
                self.cron_jobs_error = None;
            }
            Err(error) => self.cron_jobs_error = Some(error),
        }
    }

