    fn load_mcp_catalog(&mut self) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before loading the MCP catalog".into());
        }
        if self.mcp_catalog_pending {
            return Ok(());
        }
        let endpoint = self
            .gateway_endpoint
            .as_ref()
            .ok_or_else(|| "Hermes Gateway profile is unavailable".to_owned())?;
        if self.mcp_catalog_profile_id.as_deref() != Some(endpoint.profile_id.as_str()) {
            self.mcp_catalog = None;
            self.mcp_catalog_loaded_at = None;
        }
        let request_id = operation_id("mcp-catalog");
        let gateway = self
            .gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes MCP catalog reader is unavailable".to_owned())?;
        gateway.load_mcp_catalog(
            request_id.clone(),
            endpoint.profile_id.clone(),
            endpoint.instance_id.clone(),
            endpoint.authority_epoch,
        )?;
        self.mcp_catalog_request_id = Some(request_id);
        self.mcp_catalog_pending = true;
        self.mcp_catalog_error = None;
        Ok(())
    }

    fn request_mcp_catalog_install(&mut self, name: String) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before installing an MCP integration".into());
        }
        if self.pending_mcp_catalog_install.is_some()
            || self.pending_mcp_catalog_install_status.is_some()
        {
            return Err("An MCP catalog installation is already in progress".into());
        }
        if name.is_empty() || name.len() > 512 || name.chars().any(char::is_control) {
            return Err("MCP catalog entry name is invalid".into());
        }
        let endpoint = self
            .gateway_endpoint
            .as_ref()
            .ok_or_else(|| "Hermes Gateway endpoint is unavailable".to_owned())?;
        if self.mcp_catalog_profile_id.as_deref() != Some(endpoint.profile_id.as_str()) {
            return Err("Refresh the MCP catalog for the active profile before installing".into());
        }
        let entry = self
            .mcp_catalog
            .as_ref()
            .and_then(|catalog| catalog.servers.iter().find(|entry| entry.name == name))
            .cloned()
            .ok_or_else(|| "MCP catalog entry is not in the loaded catalog".to_owned())?;
        if entry.installed {
            return Err("MCP catalog integration is already installed".into());
        }
        if self
            .mcp_catalog_install_draft
            .as_ref()
            .is_some_and(|draft| draft.entry.name == name)
        {
            return Ok(());
        }
        self.mcp_catalog_install_draft = Some(McpCatalogInstallDraft {
            entry,
            profile_id: endpoint.profile_id.clone(),
            instance_id: endpoint.instance_id.clone(),
            authority_epoch: endpoint.authority_epoch,
            env: BTreeMap::new(),
            error: None,
        });
        Ok(())
    }

    fn confirm_mcp_catalog_install(&mut self, name: &str) -> Result<(), String> {
        if self.pending_mcp_catalog_install.is_some()
            || self.pending_mcp_catalog_install_status.is_some()
        {
            return Err("An MCP catalog installation is already in progress".into());
        }
        let endpoint = self
            .gateway_endpoint
            .as_ref()
            .ok_or_else(|| "Hermes Gateway endpoint is unavailable".to_owned())?;
        let draft = self
            .mcp_catalog_install_draft
            .as_mut()
            .filter(|draft| draft.entry.name == name)
            .ok_or_else(|| "Open the MCP catalog install form first".to_owned())?;
        if draft.profile_id != endpoint.profile_id
            || draft.instance_id != endpoint.instance_id
            || draft.authority_epoch != endpoint.authority_epoch
            || !self.gateway_connected
        {
            return Err("MCP catalog install form belongs to a stale Gateway connection".into());
        }
        if draft.entry.required_env.iter().any(|spec| {
            spec.required
                && draft
                    .env
                    .get(&spec.name)
                    .is_none_or(|value| value.trim().is_empty())
        }) {
            return Err("Enter a value for each required environment field".into());
        }
        let request_id = operation_id("mcp-catalog-install");
        let profile_id = draft.profile_id.clone();
        let instance_id = draft.instance_id.clone();
        let authority_epoch = draft.authority_epoch;
        let mut env = std::mem::take(&mut draft.env);
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            for value in env.values_mut() {
                value.zeroize();
            }
            return Err("Hermes MCP catalog installer is unavailable".into());
        };
        gateway.install_mcp_catalog_entry(
            request_id.clone(),
            name.to_owned(),
            env,
            profile_id.clone(),
            instance_id.clone(),
            authority_epoch,
        )?;
        self.pending_mcp_catalog_install = Some(PendingMcpCatalogInstall {
            request_id,
            name: name.to_owned(),
            profile_id,
            instance_id,
            authority_epoch,
        });
        self.mcp_catalog_error = None;
        self.status = format!("Installing MCP integration {name}…");
        Ok(())
    }

    fn poll_mcp_catalog_install_status(&mut self, ctx: &egui::Context) {
        let Some(pending) = self.pending_mcp_catalog_install_status.as_mut() else {
            return;
        };
        if !pending.request_id.is_empty()
            || pending
                .next_poll
                .is_some_and(|deadline| deadline > std::time::Instant::now())
        {
            return;
        }
        let Some(endpoint) = self.gateway_endpoint.as_ref() else {
            pending.next_poll =
                Some(std::time::Instant::now() + std::time::Duration::from_millis(1500));
            ctx.request_repaint_after(std::time::Duration::from_millis(1500));
            return;
        };
        if !self.gateway_connected
            || endpoint.profile_id != pending.profile_id
            || endpoint.instance_id != pending.instance_id
            || endpoint.authority_epoch != pending.authority_epoch
        {
            if self.gateway_connected {
                let name = pending.name.clone();
                self.pending_mcp_catalog_install_status = None;
                self.set_mcp_catalog_install_error(
                    &name,
                    "MCP install action belongs to a different Gateway connection; refresh the profile inventory before retrying".into(),
                );
                return;
            }
            pending.next_poll =
                Some(std::time::Instant::now() + std::time::Duration::from_millis(1500));
            ctx.request_repaint_after(std::time::Duration::from_millis(1500));
            return;
        }
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            pending.next_poll =
                Some(std::time::Instant::now() + std::time::Duration::from_millis(1500));
            ctx.request_repaint_after(std::time::Duration::from_millis(1500));
            return;
        };
        let request_id = operation_id("mcp-catalog-install-status");
        match gateway.load_mcp_catalog_install_status(
            request_id.clone(),
            pending.action_name.clone(),
            pending.profile_id.clone(),
            pending.instance_id.clone(),
            pending.authority_epoch,
        ) {
            Ok(()) => {
                pending.request_id = request_id;
                pending.next_poll = None;
                ctx.request_repaint_after(std::time::Duration::from_millis(1500));
            }
            Err(_) if pending.attempts < 400 => {
                pending.attempts = pending.attempts.saturating_add(1);
                pending.next_poll =
                    Some(std::time::Instant::now() + std::time::Duration::from_millis(1500));
                ctx.request_repaint_after(std::time::Duration::from_millis(1500));
            }
            Err(_) => {
                let name = pending.name.clone();
                self.pending_mcp_catalog_install_status = None;
                self.set_mcp_catalog_install_error(
                    &name,
                    "Timed out waiting for the MCP catalog install action".into(),
                );
            }
        }
    }

    fn finish_mcp_catalog_install(&mut self, name: &str, ctx: &egui::Context) {
        self.pending_mcp_catalog_install = None;
        self.pending_mcp_catalog_install_status = None;
        self.mcp_catalog_install_draft = None;
        if let Some(entry) = self
            .mcp_catalog
            .as_mut()
            .and_then(|catalog| catalog.servers.iter_mut().find(|entry| entry.name == name))
        {
            entry.installed = true;
            entry.enabled = true;
        }
        self.status = format!("Installed and enabled MCP integration {name}");
        self.mcp_catalog_loaded_at = None;
        self.mcp_catalog = None;
        self.load_mcp_catalog()
            .unwrap_or_else(|error| self.mcp_catalog_error = Some(error));
        self.load_mcp_servers()
            .unwrap_or_else(|error| self.mcp_servers_error = Some(error));
        ctx.request_repaint();
    }

    fn set_mcp_catalog_install_error(&mut self, name: &str, error: String) {
        let error = if error.len() > 2048 || error.chars().any(char::is_control) {
            "Hermes MCP catalog installation failed".to_owned()
        } else {
            error
        };
        if let Some(draft) = self
            .mcp_catalog_install_draft
            .as_mut()
            .filter(|draft| draft.entry.name == name)
        {
            draft.error = Some(error);
        } else {
            self.mcp_catalog_error = Some(error);
        }
        self.status = format!("Could not install MCP integration {name}");
    }

    fn load_agent_plugins(&mut self) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before loading installed plugins".into());
        }
        if self.agent_plugins_pending {
            return Ok(());
        }
        let request_id = operation_id("agent-plugins");
        let profile = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone());
        let gateway = self
            .gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes gateway reader is unavailable".to_owned())?;
        gateway.load_agent_plugins(request_id.clone(), profile)?;
        self.agent_plugins_request_id = Some(request_id);
        self.agent_plugins_pending = true;
        self.agent_plugins_error = None;
        self.load_agent_plugin_auto_update()
            .unwrap_or_else(|error| self.status = error);
        Ok(())
    }

    fn load_agent_plugin_auto_update(&mut self) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before loading automatic plugin updates".into());
        }
        let profile = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone());
        if self
            .pending_agent_plugin_auto_update
            .as_ref()
            .is_some_and(|pending| pending.profile == profile && pending.enabled.is_none())
        {
            return Ok(());
        }
        let request_id = operation_id("agent-plugin-auto-update-read");
        self.gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes gateway reader is unavailable".to_owned())?
            .load_agent_plugin_auto_update(request_id.clone(), profile.clone())?;
        self.pending_agent_plugin_auto_update = Some(PendingAgentPluginAutoUpdate {
            request_id,
            profile,
            enabled: None,
        });
        Ok(())
    }

    fn set_agent_plugin_auto_update(&mut self, enabled: bool) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before changing automatic plugin updates".into());
        }
        if self.pending_agent_plugin_auto_update.is_some() {
            return Err("Automatic plugin update setting is already changing".into());
        }
        let profile = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone());
        let Some((loaded_profile, _)) = self.agent_plugin_auto_update.as_ref() else {
            return Err("Automatic plugin updates are unavailable for this Hermes profile".into());
        };
        if *loaded_profile != profile || self.agent_plugins_profile != profile {
            return Err(
                "Plugin settings belong to a different profile; refresh the inventory".into(),
            );
        }
        let request_id = operation_id("agent-plugin-auto-update-set");
        self.gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes gateway writer is unavailable".to_owned())?
            .set_agent_plugin_auto_update(request_id.clone(), profile.clone(), enabled)?;
        self.pending_agent_plugin_auto_update = Some(PendingAgentPluginAutoUpdate {
            request_id,
            profile,
            enabled: Some(enabled),
        });
        Ok(())
    }

    fn request_agent_plugin_update_all(&mut self) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before updating plugins".into());
        }
        if self.pending_agent_plugin_update_all.is_some() {
            return Err("Plugin update-all is already running".into());
        }
        if self.agent_plugin_update_all_uncertain {
            return Err(
                "Refresh the selected profile inventory before retrying the uncertain update-all"
                    .into(),
            );
        }
        let profile = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone());
        if self.agent_plugins.is_none()
            || self.agent_plugins_pending
            || self.agent_plugins_profile != profile
        {
            return Err(
                "Load the installed plugins for the selected profile before updating all".into(),
            );
        }
        if !self.pending_agent_plugin_updates.is_empty()
            || !self.pending_agent_plugin_catalog_updates.is_empty()
            || !self.pending_agent_plugin_removals.is_empty()
        {
            return Err("Finish the current plugin operation before starting update-all".into());
        }
        let request_id = operation_id("agent-plugin-update-all");
        self.gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes gateway writer is unavailable".to_owned())?
            .update_all_agent_plugins(request_id.clone(), profile.clone())?;
        self.pending_agent_plugin_update_all = Some(PendingAgentPluginUpdateAll {
            request_id,
            profile,
        });
        self.agent_plugin_update_all_report = None;
        self.status =
            "Updating all Agent Plugins; items requiring review will remain unchanged".into();
        Ok(())
    }

    fn set_agent_plugin_enabled(&mut self, key: String, enabled: bool) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before changing an installed plugin".into());
        }
        if key.is_empty() || key.len() > 512 || key.chars().any(char::is_control) {
            return Err("Plugin key is invalid".into());
        }
        if self.pending_agent_plugin_updates.contains_key(&key) {
            return Ok(());
        }
        let plugin = self
            .agent_plugins
            .as_ref()
            .and_then(|snapshot| snapshot.plugins.iter().find(|plugin| plugin.key == key))
            .ok_or_else(|| "Plugin is not in the loaded profile inventory".to_owned())?;
        let profile = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone());
        if self.agent_plugins_profile != profile {
            return Err(
                "Installed plugins belong to a different profile; refresh the inventory".into(),
            );
        }
        if !agent_plugin_is_manageable(plugin) {
            return Err("This Hermes plugin cannot be toggled from the Plugins page".into());
        }
        if plugin.key.is_empty() {
            return Err("This plugin has no canonical key and is read-only".into());
        }
        let request_id = operation_id("agent-plugin-toggle");
        let gateway = self
            .gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes gateway writer is unavailable".to_owned())?;
        gateway.set_agent_plugin_enabled(
            request_id.clone(),
            key.clone(),
            enabled,
            profile.clone(),
        )?;
        self.pending_agent_plugin_updates.insert(
            key,
            PendingAgentPluginUpdate {
                request_id,
                enabled,
                profile,
            },
        );
        Ok(())
    }

    fn request_agent_plugin_update(&mut self, name: String) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before updating a plugin".into());
        }
        if name.is_empty() || name.len() > 512 || name.chars().any(char::is_control) {
            return Err("Plugin name is invalid".into());
        }
        let profile = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone());
        if self.agent_plugins_profile != profile {
            return Err(
                "Installed plugins belong to a different profile; refresh the inventory".into(),
            );
        }
        let plugin = self
            .agent_plugins
            .as_ref()
            .and_then(|snapshot| snapshot.plugins.iter().find(|plugin| plugin.name == name))
            .ok_or_else(|| "Plugin is not in the loaded profile inventory".to_owned())?;
        if !agent_plugin_is_manageable(plugin) || plugin.update_available != Some(true) {
            return Err("This plugin does not have a manageable update available".into());
        }
        if self
            .pending_agent_plugin_catalog_updates
            .contains_key(&name)
        {
            return Ok(());
        }
        self.send_agent_plugin_update(name, false, false)
    }

    fn send_agent_plugin_update(
        &mut self,
        name: String,
        accept_capabilities: bool,
        force: bool,
    ) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Reconnect to Hermes before continuing the plugin update".into());
        }
        let profile = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone());
        if self.agent_plugins_profile != profile {
            return Err(
                "Installed plugins belong to a different profile; refresh the inventory".into(),
            );
        }
        let eligible = self
            .agent_plugins
            .as_ref()
            .and_then(|snapshot| snapshot.plugins.iter().find(|plugin| plugin.name == name))
            .is_some_and(|plugin| {
                agent_plugin_is_manageable(plugin) && plugin.update_available == Some(true)
            });
        if !eligible {
            return Err(
                "Plugin update is no longer available in the loaded profile inventory".into(),
            );
        }
        if self
            .pending_agent_plugin_catalog_updates
            .contains_key(&name)
        {
            return Err("This plugin already has an update in progress".into());
        }
        let request_id = operation_id("agent-plugin-update");
        self.gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes gateway writer is unavailable".to_owned())?
            .update_agent_plugin(
                request_id.clone(),
                name.clone(),
                profile.clone(),
                accept_capabilities,
                force,
            )?;
        self.pending_agent_plugin_catalog_updates.insert(
            name,
            PendingAgentPluginCatalogUpdate {
                request_id,
                profile,
                accept_capabilities,
                force,
            },
        );
        Ok(())
    }

    fn request_agent_plugin_removal(&mut self, name: String) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before uninstalling a plugin".into());
        }
        if name.is_empty() || name.len() > 512 || name.chars().any(char::is_control) {
            return Err("Plugin name is invalid".into());
        }
        let profile = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone());
        if self.agent_plugins_profile != profile {
            return Err(
                "Installed plugins belong to a different profile; refresh the inventory".into(),
            );
        }
        let plugin = self
            .agent_plugins
            .as_ref()
            .and_then(|snapshot| snapshot.plugins.iter().find(|plugin| plugin.name == name))
            .ok_or_else(|| "Plugin is not in the loaded profile inventory".to_owned())?;
        if !agent_plugin_is_manageable(plugin) || !matches!(plugin.source.as_str(), "user" | "git")
        {
            return Err("Only user or git installed plugins can be uninstalled here".into());
        }
        if self.pending_agent_plugin_removals.contains_key(&name) {
            return Err("This plugin already has an uninstall in progress".into());
        }
        self.agent_plugin_removal_confirmation = Some(name);
        Ok(())
    }

    fn confirm_agent_plugin_removal(&mut self, name: String) -> Result<(), String> {
        if self.agent_plugin_removal_confirmation.as_deref() != Some(name.as_str()) {
            return Err("Plugin removal confirmation is stale".into());
        }
        if !self.gateway_connected {
            return Err("Connect to Hermes before uninstalling a plugin".into());
        }
        let profile = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone());
        if self.agent_plugins_profile != profile {
            self.agent_plugin_removal_confirmation = None;
            return Err(
                "Installed plugins belong to a different profile; refresh the inventory".into(),
            );
        }
        let eligible = self
            .agent_plugins
            .as_ref()
            .and_then(|snapshot| snapshot.plugins.iter().find(|plugin| plugin.name == name))
            .is_some_and(|plugin| {
                agent_plugin_is_manageable(plugin)
                    && matches!(plugin.source.as_str(), "user" | "git")
            });
        if !eligible {
            self.agent_plugin_removal_confirmation = None;
            return Err("Plugin is no longer eligible for uninstall".into());
        }
        let request_id = operation_id("agent-plugin-remove");
        let gateway = self
            .gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes gateway writer is unavailable".to_owned())?;
        gateway.remove_agent_plugin(request_id.clone(), name.clone(), profile.clone())?;
        self.pending_agent_plugin_removals.insert(
            name,
            PendingAgentPluginRemoval {
                request_id,
                profile,
            },
        );
        self.agent_plugin_removal_confirmation = None;
        Ok(())
    }

    fn open_agent_plugin_settings(&mut self, plugin: AgentPluginInfo) {
        let Some(profile) = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone())
        else {
            return;
        };
        let drafts = plugin
            .settings_schema
            .iter()
            .filter(|field| field.field_type != "secret")
            .map(|field| (field.key.clone(), plugin_setting_initial_draft(field)))
            .collect();
        let secrets = plugin
            .settings_schema
            .iter()
            .filter(|field| field.field_type == "secret")
            .map(|field| (field.key.clone(), Zeroizing::new(String::new())))
            .collect();
        self.agent_plugin_settings_dialog = Some(AgentPluginSettingsDialog {
            plugin,
            profile,
            drafts,
            secrets,
            error: None,
        });
    }

    fn show_agent_plugin_settings_dialog(&mut self, ctx: &egui::Context) {
        let Some(dialog) = self.agent_plugin_settings_dialog.as_mut() else {
            return;
        };
        let profile_matches = self.gateway_endpoint.as_ref().is_some_and(|endpoint| {
            self.gateway_connected && endpoint.profile_id == dialog.profile
        });
        if !profile_matches {
            self.agent_plugin_settings_dialog = None;
            return;
        }
        let busy = self.pending_agent_plugin_settings_save.is_some();
        let dirty = dialog.plugin.settings_schema.iter().any(|field| {
            if field.field_type == "secret" {
                dialog
                    .secrets
                    .get(&field.key)
                    .is_some_and(|value| !value.is_empty())
            } else {
                dialog
                    .drafts
                    .get(&field.key)
                    .is_some_and(|value| value != &plugin_setting_initial_draft(field))
            }
        });
        let mut close = false;
        let mut save = false;
        let plugin_name = dialog.plugin.name.clone();
        egui::Window::new(format!("Plugin settings · {plugin_name}"))
            .id(Id::NULL.with(("agent-plugin-settings", &dialog.plugin.key)))
            .collapsible(false)
            .resizable(true)
            .default_width(520.0)
            .show(ctx, |ui| {
                ui.label(RichText::new(format!("Profile: {}", dialog.profile)).color(MUTED));
                ui.label(RichText::new("Secret values are written directly to the selected profile and are never read back.").color(MUTED));
                ui.separator();
                egui::ScrollArea::vertical().max_height(520.0).show(ui, |ui| {
                    for field in &dialog.plugin.settings_schema {
                        ui.add_space(4.0);
                        let required = if field.required { " · required" } else { "" };
                        ui.label(RichText::new(format!("{}{required}", field.label)).strong());
                        if !field.description.is_empty() {
                            ui.label(RichText::new(&field.description).size(11.0).color(MUTED));
                        }
                        match field.field_type.as_str() {
                            "boolean" => {
                                if let Some(value) = dialog.drafts.get_mut(&field.key) {
                                    let mut checked = value == "true";
                                    if ui.add_enabled(!busy, egui::Checkbox::new(&mut checked, "Enabled")).accessible_name(format!("Plugin setting {}", field.key)).changed() {
                                        *value = checked.to_string();
                                    }
                                }
                            }
                            "enum" => {
                                if let Some(value) = dialog.drafts.get_mut(&field.key) {
                                    let selected_text = if value.is_empty() {
                                        "Choose an option".to_owned()
                                    } else {
                                        value.clone()
                                    };
                                    egui::ComboBox::from_id_salt(("plugin-setting", &field.key))
                                        .selected_text(selected_text)
                                        .show_ui(ui, |ui| {
                                            for choice in &field.choices {
                                                ui.add_enabled_ui(!busy, |ui| {
                                                    ui.selectable_value(&mut *value, choice.clone(), choice);
                                                });
                                            }
                                        })
                                        .response
                                        .accessible_name(format!("Plugin setting {}", field.key));
                                }
                            }
                            "json" => {
                                if let Some(value) = dialog.drafts.get_mut(&field.key) {
                                    ui.add_enabled(!busy, egui::TextEdit::multiline(value).desired_rows(4).hint_text("JSON object or array")).accessible_name(format!("Plugin setting {}", field.key));
                                }
                            }
                            "number" => {
                                if let Some(value) = dialog.drafts.get_mut(&field.key) {
                                    ui.add_enabled(!busy, egui::TextEdit::singleline(value).hint_text("Number")).accessible_name(format!("Plugin setting {}", field.key));
                                }
                            }
                            "string" => {
                                if let Some(value) = dialog.drafts.get_mut(&field.key) {
                                    ui.add_enabled(!busy, egui::TextEdit::singleline(value)).accessible_name(format!("Plugin setting {}", field.key));
                                }
                            }
                            "secret" => {
                                let env_name = field.env.as_deref().unwrap_or("environment variable");
                                ui.label(RichText::new(if field.has_value { format!("{env_name} is set · enter a replacement to change it") } else { format!("Set {env_name}") }).size(11.0).color(MUTED));
                                if let Some(value) = dialog.secrets.get_mut(&field.key) {
                                    ui.add_enabled(!busy, egui::TextEdit::singleline(&mut **value).password(true).hint_text("Secret value (never displayed again)")).accessible_name(format!("Plugin setting {}", field.key));
                                }
                            }
                            _ => {
                                ui.label(RichText::new(format!("Unsupported setting type: {}", field.field_type)).color(Color32::LIGHT_RED));
                            }
                        }
                    }
                });
                if let Some(error) = dialog.error.as_deref() {
                    ui.colored_label(Color32::LIGHT_RED, error);
                }
                ui.separator();
                ui.horizontal(|ui| {
                    if ui.add_enabled(!busy && dirty, egui::Button::new("Save settings")).clicked() { save = true; }
                    if ui.add_enabled(!busy, egui::Button::new("Close")).clicked() { close = true; }
                    if busy { ui.label(RichText::new("Saving…").color(MUTED)); }
                });
            });
        if close {
            self.agent_plugin_settings_dialog = None;
            return;
        }
        if save {
            self.begin_agent_plugin_settings_save();
        }
    }

    fn begin_agent_plugin_settings_save(&mut self) {
        let Some(dialog) = self.agent_plugin_settings_dialog.as_mut() else {
            return;
        };
        if self.pending_agent_plugin_settings_save.is_some()
            || self
                .gateway_endpoint
                .as_ref()
                .map(|endpoint| endpoint.profile_id.as_str())
                != Some(dialog.profile.as_str())
        {
            return;
        }
        let mut values = serde_json::Map::new();
        let mut secrets = VecDeque::new();
        for field in &dialog.plugin.settings_schema {
            if field.field_type == "secret" {
                let Some(secret) = dialog.secrets.get_mut(&field.key) else {
                    continue;
                };
                if secret.is_empty() {
                    continue;
                }
                let Some(env) = field.env.clone() else {
                    dialog.error = Some(format!(
                        "{} has no secure environment variable mapping",
                        field.label
                    ));
                    return;
                };
                secrets.push_back((env, secret.clone()));
                continue;
            }
            let Some(draft) = dialog.drafts.get(&field.key) else {
                continue;
            };
            let original = plugin_setting_initial_draft(field);
            if draft == &original {
                continue;
            }
            let parsed = match field.field_type.as_str() {
                "string" => Ok(serde_json::Value::String(draft.clone())),
                "boolean" if draft == "true" || draft == "false" => {
                    Ok(serde_json::Value::Bool(draft == "true"))
                }
                "number" => draft
                    .parse::<serde_json::Number>()
                    .map(serde_json::Value::Number)
                    .map_err(|_| "must be a valid number"),
                "enum" if field.choices.iter().any(|choice| choice == draft) => {
                    Ok(serde_json::Value::String(draft.clone()))
                }
                "json" => serde_json::from_str::<serde_json::Value>(draft)
                    .ok()
                    .filter(|value| value.is_object() || value.is_array())
                    .ok_or("must be a JSON object or array"),
                "enum" => Err("must match one of the listed choices"),
                "boolean" => Err("must be true or false"),
                _ => continue,
            };
            match parsed {
                Ok(value) => {
                    values.insert(field.key.clone(), value);
                }
                Err(error) => {
                    dialog.error = Some(format!("{} {error}", field.label));
                    return;
                }
            }
        }
        if values.is_empty() && secrets.is_empty() {
            dialog.error = None;
            return;
        }
        let request_id = operation_id("agent-plugin-settings-save");
        self.pending_agent_plugin_settings_save = Some(PendingAgentPluginSettingsSave {
            request_id,
            key: dialog.plugin.key.clone(),
            profile: Some(dialog.profile.clone()),
            values: serde_json::Value::Object(values),
            secrets,
            active_secret_request: None,
            secret_saved: false,
        });
        dialog.error = None;
        self.advance_agent_plugin_settings_save();
    }

    fn advance_agent_plugin_settings_save(&mut self) {
        let Some(pending) = self.pending_agent_plugin_settings_save.as_mut() else {
            return;
        };
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            self.pending_agent_plugin_settings_save = None;
            return;
        };
        if let Some((env, secret)) = pending.secrets.pop_front() {
            let request_id = operation_id("agent-plugin-secret-save");
            match gateway.save_agent_plugin_setting_secret(
                request_id.clone(),
                pending.profile.clone(),
                env,
                secret,
            ) {
                Ok(()) => pending.active_secret_request = Some(request_id),
                Err(error) => {
                    if let Some(dialog) = self.agent_plugin_settings_dialog.as_mut() {
                        dialog.error = Some(error);
                    }
                    self.pending_agent_plugin_settings_save = None;
                }
            }
            return;
        }
        match gateway.save_agent_plugin_settings(
            pending.request_id.clone(),
            pending.key.clone(),
            pending.values.clone(),
            pending.profile.clone(),
        ) {
            Ok(()) => {}
            Err(error) => {
                if let Some(dialog) = self.agent_plugin_settings_dialog.as_mut() {
                    dialog.error = Some(error);
                }
                self.pending_agent_plugin_settings_save = None;
            }
        }
    }

    fn show_agent_plugin_removal_dialog(&mut self, ctx: &egui::Context) {
        let Some(name) = self.agent_plugin_removal_confirmation.clone() else {
            return;
        };
        let mut confirm = false;
        let mut cancel = false;
        egui::Window::new("Uninstall agent plugin?")
            .id(Id::NULL.with(("agent-plugin-remove", &name)))
            .collapsible(false)
            .resizable(false)
            .show(ctx, |ui| {
                ui.label(format!(
                    "Uninstall {name} from the selected Hermes profile?"
                ));
                ui.label("Its files and install metadata will be removed. This cannot be undone.");
                ui.horizontal(|ui| {
                    confirm = ui
                        .button("Uninstall")
                        .accessible_name(format!("Confirm uninstall agent plugin: {name}"))
                        .clicked();
                    cancel = ui
                        .button("Cancel")
                        .accessible_name("Cancel agent plugin uninstall")
                        .clicked();
                });
            });
        if confirm {
            self.confirm_agent_plugin_removal(name)
                .unwrap_or_else(|error| self.status = error);
        } else if cancel {
            self.agent_plugin_removal_confirmation = None;
        }
    }

    fn show_agent_plugin_update_dialog(&mut self, ctx: &egui::Context) {
        let Some(dialog) = self.agent_plugin_update_dialog.clone() else {
            return;
        };
        let mut confirm = false;
        let mut cancel = false;
        let (title, confirm_label, can_confirm) = match &dialog.review {
            AgentPluginUpdateReview::Consent { sha, .. } => (
                format!("Review plugin capability changes · {}", dialog.name),
                format!("Accept changes and update to {sha}"),
                true,
            ),
            AgentPluginUpdateReview::Scan { verdict, .. } => (
                format!("Security scan · {}", dialog.name),
                "Update anyway".to_owned(),
                verdict.eq_ignore_ascii_case("caution"),
            ),
        };
        egui::Window::new(title.clone())
            .id(Id::NULL.with(("agent-plugin-update-review", &dialog.name)))
            .collapsible(false)
            .resizable(true)
            .default_width(520.0)
            .show(ctx, |ui| {
                ui.label(format!("Profile · {}", dialog.profile.as_deref().unwrap_or("Default")));
                match &dialog.review {
                    AgentPluginUpdateReview::Consent { sha, delta_lines } => {
                        ui.label(format!("The catalog pin changed to {sha} and requests new capabilities."));
                        ui.label("Hermes has not applied the update. Review each change before accepting.");
                        for line in delta_lines.iter().take(20) {
                            ui.label(RichText::new(line).size(11.0).color(MUTED));
                        }
                        if delta_lines.len() > 20 {
                            ui.label(format!("{} more changes omitted", delta_lines.len() - 20));
                        }
                    }
                    AgentPluginUpdateReview::Scan { verdict, findings } => {
                        ui.colored_label(if can_confirm { Color32::YELLOW } else { Color32::LIGHT_RED },
                            format!("Hermes security scan verdict · {verdict}"));
                        ui.label(if can_confirm {
                            "A caution scan blocked the update. Hermes changed nothing; continuing is an explicit override."
                        } else {
                            "This verdict cannot be overridden from the Desktop. Hermes changed nothing."
                        });
                        let mut sorted = findings.clone();
                        sorted.sort_by_key(|finding| match finding.severity.to_ascii_lowercase().as_str() {
                            "critical" => 0, "high" => 1, "medium" => 2, "low" => 3, _ => 4,
                        });
                        for finding in sorted.iter().take(8) {
                            ui.colored_label(Color32::YELLOW, format!("{} · {}:{} · {}",
                                finding.severity.to_uppercase(), finding.file, finding.line,
                                if finding.description.is_empty() { &finding.category } else { &finding.description }));
                        }
                        if sorted.len() > 8 {
                            ui.label(format!("{} additional findings", sorted.len() - 8));
                        }
                    }
                }
                ui.separator();
                ui.horizontal(|ui| {
                    confirm = ui.add_enabled(can_confirm, egui::Button::new(confirm_label))
                        .accessible_name(format!("Confirm plugin update: {}", dialog.name)).clicked();
                    cancel = ui.button("Cancel").accessible_name("Cancel plugin update review").clicked();
                });
            });
        if confirm {
            let (accept_capabilities, force) = match dialog.review {
                AgentPluginUpdateReview::Consent { .. } => (true, dialog.force),
                AgentPluginUpdateReview::Scan { .. } => (dialog.accept_capabilities, true),
            };
            match self.send_agent_plugin_update(dialog.name.clone(), accept_capabilities, force) {
                Ok(()) => self.agent_plugin_update_dialog = None,
                Err(error) => self.status = error,
            }
        } else if cancel {
            self.agent_plugin_update_dialog = None;
        }
    }

    fn request_catalog_plugin_install(&mut self, name: String) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before installing a catalog plugin".into());
        }
        if self.uncertain_catalog_plugin_installs.contains(&name) {
            return Err("A prior install for this catalog entry has an unknown outcome; refresh the installed inventory before opening another install request".into());
        }
        let entry = self
            .plugin_catalog
            .as_ref()
            .and_then(|entries| entries.iter().find(|entry| entry.name == name))
            .cloned()
            .ok_or_else(|| "Plugin is not in the loaded Hermes catalog".to_owned())?;
        if entry.installed_key.is_some() {
            return Err(
                "This catalog plugin is already installed; refresh its profile inventory".into(),
            );
        }
        if entry.repo.is_empty() || entry.name.is_empty() {
            return Err("Catalog entry is missing its repository or canonical name".into());
        }
        let profile = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone());
        let request_id = operation_id("catalog-plugin-inspect");
        let identifier = if entry.subdir.is_empty() {
            entry.repo.clone()
        } else {
            format!("{}#{}", entry.repo, entry.subdir)
        };
        self.gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes gateway reader is unavailable".to_owned())?
            .inspect_catalog_plugin(
                request_id.clone(),
                entry.name.clone(),
                identifier,
                profile.clone(),
            )?;
        self.catalog_plugin_install_dialog = Some(CatalogPluginInstallDialog {
            entry,
            profile,
            request_id,
            inspecting: true,
            installing: false,
            uncertain: false,
            inspection: None,
            error: None,
        });
        Ok(())
    }

    fn install_reviewed_catalog_plugin(&mut self) -> Result<(), String> {
        let dialog = self
            .catalog_plugin_install_dialog
            .as_ref()
            .ok_or_else(|| "Plugin review dialog is no longer open".to_owned())?;
        if !self.gateway_connected {
            return Err("Reconnect to Hermes before installing this plugin".into());
        }
        if dialog.uncertain {
            return Err("This install outcome is unknown; do not submit it again".into());
        }
        if dialog.profile
            != self
                .gateway_endpoint
                .as_ref()
                .map(|endpoint| endpoint.profile_id.clone())
        {
            return Err(
                "Hermes profile changed during plugin review; inspect the plugin again".into(),
            );
        }
        let inspection = dialog
            .inspection
            .as_ref()
            .ok_or_else(|| "Inspect the repository before installing".to_owned())?;
        if !inspection.agent || inspection.insecure {
            return Err("This native install path requires an Agent Plugin without an insecure-source finding".into());
        }
        let inspected_sha = inspection.sha.clone().ok_or_else(|| {
            "Hermes did not return a full reviewed commit; installation is disabled".to_owned()
        })?;
        if !dialog.entry.sha.is_empty() && !dialog.entry.sha.eq_ignore_ascii_case(&inspected_sha) {
            return Err("The inspected commit does not match the pinned catalog revision; refresh the catalog and inspect again".into());
        }
        if dialog.installing {
            return Ok(());
        }
        let request_id = operation_id("catalog-plugin-install");
        let identifier = if dialog.entry.subdir.is_empty() {
            dialog.entry.repo.clone()
        } else {
            format!("{}#{}", dialog.entry.repo, dialog.entry.subdir)
        };
        self.gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes gateway writer is unavailable".to_owned())?
            .install_catalog_plugin(
                request_id.clone(),
                dialog.entry.name.clone(),
                identifier,
                inspected_sha,
                dialog.profile.clone(),
            )?;
        let profile = dialog.profile.clone();
        let dialog = self
            .catalog_plugin_install_dialog
            .as_mut()
            .expect("dialog checked");
        dialog.installing = true;
        dialog.error = None;
        self.pending_catalog_plugin_install = Some(PendingCatalogPluginInstall {
            request_id,
            catalog_name: dialog.entry.name.clone(),
            profile,
        });
        Ok(())
    }

    fn show_catalog_plugin_install_dialog(&mut self, ctx: &egui::Context) {
        let Some(snapshot) = self.catalog_plugin_install_dialog.clone() else {
            return;
        };
        let mut cancel = false;
        let mut install = false;
        egui::Window::new(format!("Review plugin · {}", snapshot.entry.name))
            .id(Id::NULL.with(("catalog-plugin-install", &snapshot.entry.name)))
            .collapsible(false)
            .resizable(true)
            .default_width(520.0)
            .show(ctx, |ui| {
                ui.label(RichText::new(&snapshot.entry.description).color(MUTED));
                ui.label(format!(
                    "Repository · {}{}",
                    snapshot.entry.repo,
                    if snapshot.entry.subdir.is_empty() {
                        String::new()
                    } else {
                        format!(" · {}", snapshot.entry.subdir)
                    }
                ));
                ui.label(format!(
                    "Profile · {}",
                    snapshot.profile.as_deref().unwrap_or("Default")
                ));
                ui.separator();
                if snapshot.inspecting {
                    ui.spinner();
                    ui.label("Hermes is inspecting the repository. Nothing has been installed.");
                } else if let Some(review) = &snapshot.inspection {
                    ui.label(format!(
                        "Reviewed commit · {}",
                        review.sha.as_deref().unwrap_or("unavailable")
                    ));
                    ui.label(format!(
                        "Components · {}",
                        match (review.agent, review.desktop) {
                            (true, true) =>
                                "Agent Plugin and Desktop Plugin (native installs the Agent half)",
                            (true, false) => "Agent Plugin",
                            (false, true) =>
                                "Desktop Plugin only (not installable from this native flow)",
                            (false, false) => "No installable plugin components",
                        }
                    ));
                    if review.insecure {
                        ui.colored_label(
                            Color32::LIGHT_RED,
                            "Hermes marked this source insecure. Installation is blocked here.",
                        );
                    }
                    for warning in &review.warnings {
                        ui.colored_label(Color32::YELLOW, format!("Review warning · {warning}"));
                    }
                    if !review.agent {
                        ui.label("This entry does not contain an Agent Plugin.");
                    }
                }
                if let Some(error) = &snapshot.error {
                    ui.colored_label(Color32::LIGHT_RED, error);
                }
                ui.separator();
                ui.horizontal(|ui| {
                    cancel = ui
                        .add_enabled(!snapshot.installing, egui::Button::new("Cancel"))
                        .accessible_name("Cancel catalog plugin install")
                        .clicked();
                    if snapshot.installing {
                        ui.spinner();
                        ui.label("Installing reviewed plugin…");
                    } else {
                        let can_install = self.gateway_connected
                            && !snapshot.uncertain
                            && snapshot.inspection.as_ref().is_some_and(|review| {
                                review.agent
                                    && !review.insecure
                                    && review.sha.is_some()
                                    && (snapshot.entry.sha.is_empty()
                                        || review.sha.as_deref().is_some_and(|sha| {
                                            snapshot.entry.sha.eq_ignore_ascii_case(sha)
                                        }))
                            });
                        install = ui
                            .add_enabled(
                                can_install,
                                egui::Button::new("Install reviewed Agent Plugin"),
                            )
                            .accessible_name(format!(
                                "Install reviewed Agent Plugin: {}",
                                snapshot.entry.name
                            ))
                            .clicked();
                    }
                });
            });
        if install {
            if let Err(error) = self.install_reviewed_catalog_plugin() {
                if let Some(dialog) = self.catalog_plugin_install_dialog.as_mut() {
                    dialog.error = Some(error);
                }
            }
        } else if cancel {
            self.catalog_plugin_install_dialog = None;
        }
    }

    fn load_plugin_catalog(&mut self) -> Result<(), String> {
        if self.plugin_catalog_pending {
            return Ok(());
        }
        let request_id = operation_id("plugin-catalog");
        self.plugin_catalog_worker.fetch(request_id.clone())?;
        self.plugin_catalog_request_id = Some(request_id);
        self.plugin_catalog_pending = true;
        self.plugin_catalog_error = None;
        Ok(())
    }

    fn poll_plugin_catalog(&mut self) {
        while let Some(result) = self.plugin_catalog_worker.poll() {
            if self.plugin_catalog_request_id.as_deref() != Some(&result.request_id) {
                continue;
            }
            self.plugin_catalog_request_id = None;
            self.plugin_catalog_pending = false;
            match result.result {
                Ok(entries) => {
                    self.plugin_catalog = Some(entries);
                    self.plugin_catalog_error = None;
                }
                Err(error) => self.plugin_catalog_error = Some(error),
            }
        }
    }

    fn load_skill_catalog(&mut self) -> Result<(), String> {
        if self.skill_catalog_pending || self.skill_catalog.is_some() {
            return Ok(());
        }
        let request_id = operation_id("skill-catalog");
        self.skill_catalog_worker.fetch(request_id.clone())?;
        self.skill_catalog_request_id = Some(request_id);
        self.skill_catalog_pending = true;
        self.skill_catalog_error = None;
        Ok(())
    }

    fn poll_skill_catalog(&mut self) {
        while let Some(result) = self.skill_catalog_worker.poll() {
            if self.skill_catalog_request_id.as_deref() != Some(&result.request_id) {
                continue;
            }
            self.skill_catalog_request_id = None;
            self.skill_catalog_pending = false;
            match result.result {
                Ok(entries) => {
                    self.skill_catalog = Some(entries);
                    self.skill_catalog_error = None;
                    self.skill_catalog_visible_limit = SKILL_CATALOG_PAGE_SIZE;
                    self.skill_catalog_filter_query = "\0".into();
                }
                Err(error) => self.skill_catalog_error = Some(error),
            }
        }
    }

    fn request_skill_hub_install(
        &mut self,
        identifier: String,
        name: String,
    ) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before installing a skill".into());
        }
        if identifier.is_empty()
            || identifier.len() > 2048
            || identifier.chars().any(char::is_control)
            || name.is_empty()
            || name.len() > 512
            || name.chars().any(char::is_control)
        {
            return Err("Skill catalog install target is invalid".into());
        }
        if self
            .pending_skill_hub_installs
            .get(&identifier)
            .is_some_and(|install| install.completed.is_none())
        {
            return Ok(());
        }
        if self
            .pending_skill_hub_installs
            .get(&identifier)
            .is_some_and(|install| install.completed == Some(true))
        {
            return Err(
                "Skill installation already completed; refresh the installed Skills list.".into(),
            );
        }
        let entry = self
            .skill_catalog
            .as_ref()
            .and_then(|entries| {
                entries.iter().find(|entry| {
                    entry.name == name && entry.install_identifier.as_deref() == Some(&identifier)
                })
            })
            .ok_or_else(|| "Skill is not an installable entry in the loaded catalog".to_owned())?;
        if self.skills.as_ref().is_some_and(|skills| {
            skills
                .iter()
                .any(|skill| skill.name == entry.name || skill.name == identifier)
        }) {
            return Err("Skill is already installed".into());
        }
        let endpoint = self
            .gateway_endpoint
            .as_ref()
            .ok_or_else(|| "Hermes Gateway endpoint is unavailable".to_owned())?;
        let request_id = operation_id("skill-hub-install");
        let gateway = self
            .gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes Skills hub installer is unavailable".to_owned())?;
        if self.pending_skill_hub_installs.len() >= 32 {
            self.pending_skill_hub_installs
                .retain(|_, install| install.completed.is_none());
        }
        if self.pending_skill_hub_installs.len() >= 32 {
            return Err("Too many skill installs are active".into());
        }
        gateway.install_skill_hub(
            request_id.clone(),
            identifier.clone(),
            endpoint.profile_id.clone(),
            endpoint.instance_id.clone(),
            endpoint.authority_epoch,
        )?;
        self.pending_skill_hub_installs.insert(
            identifier.clone(),
            PendingSkillHubInstall {
                request_id,
                identifier,
                name: name.clone(),
                profile_id: endpoint.profile_id.clone(),
                instance_id: endpoint.instance_id.clone(),
                authority_epoch: endpoint.authority_epoch,
                action_name: None,
                status_request_id: None,
                attempts: 0,
                next_poll: None,
                lines: vec!["Starting Hermes skill installation…".into()],
                error: None,
                completed: None,
                scan_request_id: None,
                scan_result: None,
                scan_error: None,
            },
        );
        self.status = format!("Installing skill {name}");
        Ok(())
    }

    fn start_skill_hub_update(&mut self) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before updating installed Skills".into());
        }
        let endpoint = self
            .gateway_endpoint
            .as_ref()
            .ok_or_else(|| "Hermes Gateway endpoint is unavailable".to_owned())?;
        if endpoint.profile_id.eq_ignore_ascii_case("all") {
            return Err("Skill updates require one explicit Hermes profile".into());
        }
        if self
            .pending_skill_hub_update
            .as_ref()
            .is_some_and(|update| {
                !update.completed
                    && update.profile_id == endpoint.profile_id
                    && update.instance_id == endpoint.instance_id
                    && update.authority_epoch == endpoint.authority_epoch
            })
        {
            return Ok(());
        }
        let gateway = self
            .gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes Skills updater is unavailable".to_owned())?;
        let request_id = operation_id("skill-hub-update");
        let profile_id = endpoint.profile_id.clone();
        let instance_id = endpoint.instance_id.clone();
        let authority_epoch = endpoint.authority_epoch;
        gateway.update_skill_hub_skills(
            request_id.clone(),
            profile_id.clone(),
            instance_id.clone(),
            authority_epoch,
        )?;
        self.pending_skill_hub_update = Some(PendingSkillHubUpdate {
            request_id,
            profile_id,
            instance_id,
            authority_epoch,
            action_name: None,
            action_pid: None,
            status_request_id: None,
            attempts: 0,
            next_poll: None,
            lines: vec!["Starting Hermes installed Skills update…".into()],
            error: None,
            completed: false,
        });
        self.status = "Updating installed Skills".into();
        Ok(())
    }

    fn poll_skill_hub_update_action(&mut self, ctx: &egui::Context) {
        let now = std::time::Instant::now();
        let Some(update) = self.pending_skill_hub_update.as_ref() else {
            return;
        };
        if update.completed
            || update.action_name.is_none()
            || update.status_request_id.is_some()
            || update.next_poll.is_some_and(|deadline| deadline > now)
        {
            return;
        }
        let Some(endpoint) = self.gateway_endpoint.as_ref() else {
            return;
        };
        if !self.gateway_connected
            || endpoint.profile_id != update.profile_id
            || endpoint.instance_id != update.instance_id
            || endpoint.authority_epoch != update.authority_epoch
        {
            return;
        }
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            return;
        };
        let request_id = operation_id("skill-hub-update-status");
        let action_name = update.action_name.clone().unwrap_or_default();
        let profile_id = update.profile_id.clone();
        match gateway.load_gateway_action_status(request_id.clone(), action_name, Some(profile_id))
        {
            Ok(()) => {
                if let Some(update) = self.pending_skill_hub_update.as_mut() {
                    update.status_request_id = Some(request_id);
                    update.next_poll = None;
                }
                ctx.request_repaint_after(std::time::Duration::from_millis(1200));
            }
            Err(error) => {
                if let Some(update) = self.pending_skill_hub_update.as_mut() {
                    update.attempts = update.attempts.saturating_add(1);
                    if update.attempts >= 400 {
                        update.error = Some(format!(
                            "Could not poll Skill update action: {}",
                            bounded_status_text(&error, 1024)
                        ));
                        update.completed = true;
                    } else {
                        update.next_poll = Some(now + std::time::Duration::from_millis(1200));
                    }
                }
                ctx.request_repaint_after(std::time::Duration::from_millis(1200));
            }
        }
    }

    fn settle_skill_hub_update_status(
        &mut self,
        request_id: &str,
        profile: &Option<String>,
        action_name: &str,
        result: Result<GatewayActionStatus, String>,
        ctx: &egui::Context,
    ) -> bool {
        let Some(update) = self.pending_skill_hub_update.as_mut() else {
            return false;
        };
        if update.status_request_id.as_deref() != Some(request_id) {
            return false;
        }
        let current_owner = self.gateway_connected
            && self.gateway_endpoint.as_ref().is_some_and(|endpoint| {
                endpoint.profile_id == update.profile_id
                    && endpoint.instance_id == update.instance_id
                    && endpoint.authority_epoch == update.authority_epoch
            });
        if update.action_name.as_deref() != Some(action_name)
            || profile.as_deref() != Some(update.profile_id.as_str())
            || !current_owner
        {
            update.status_request_id = None;
            update.error = Some("Skill update status belonged to a stale Gateway owner.".into());
            update.completed = true;
            return true;
        }
        update.status_request_id = None;
        update.attempts = update.attempts.saturating_add(1);
        let mut refresh = false;
        match result {
            Ok(status)
                if status.name == action_name
                    && update.action_pid.is_none_or(|pid| status.pid == Some(pid))
                    && status.lines.len() <= 200
                    && status
                        .lines
                        .iter()
                        .all(|line| line.len() <= 8192 && !line.contains('\0')) =>
            {
                update.lines = status
                    .lines
                    .into_iter()
                    .take(200)
                    .map(|line| bounded_status_text(&line, 2048))
                    .collect();
                if status.running || status.exit_code.is_none() {
                    if update.attempts >= 400 {
                        update.error =
                            Some("Timed out waiting for the Skill update action.".into());
                        update.completed = true;
                    } else {
                        update.next_poll = Some(
                            std::time::Instant::now() + std::time::Duration::from_millis(1200),
                        );
                    }
                } else {
                    update.completed = true;
                    if status.exit_code == Some(0) {
                        update.error = None;
                        self.status = "Installed Skills updated".into();
                        refresh = true;
                    } else {
                        let detail = update
                            .lines
                            .iter()
                            .rev()
                            .take(3)
                            .cloned()
                            .collect::<Vec<_>>()
                            .into_iter()
                            .rev()
                            .collect::<Vec<_>>()
                            .join("\n");
                        update.error = Some(if detail.is_empty() {
                            format!(
                                "Skill update failed with exit code {}.",
                                status.exit_code.unwrap_or_default()
                            )
                        } else {
                            detail
                        });
                    }
                }
            }
            Ok(_) => {
                update.error =
                    Some("Hermes returned mismatched or invalid Skill update status.".into());
                update.completed = true;
            }
            Err(error) => {
                update.error = Some(bounded_status_text(&error, 1024));
                update.completed = true;
            }
        }
        if refresh {
            if let Err(error) = self.load_capabilities() {
                self.capabilities_error = Some(error);
            }
            ctx.request_repaint();
        }
        true
    }

    fn request_skill_hub_scan(&mut self, identifier: &str) -> Result<(), String> {
        let blocked_install =
            self.pending_skill_hub_installs
                .get(identifier)
                .is_some_and(|install| {
                    install.completed == Some(false)
                        && parse_skill_hub_install_block(&install.lines, install.error.as_deref())
                            .is_some()
                });
        if !blocked_install {
            return Err(
                "A security scan is available only after Hermes blocks a skill install".into(),
            );
        }
        let endpoint = self
            .gateway_endpoint
            .as_ref()
            .ok_or_else(|| "Hermes Gateway endpoint is unavailable".to_owned())?;
        if !self.gateway_connected {
            return Err("Connect to Hermes before viewing the skill security scan".into());
        }
        let gateway = self
            .gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes Skills hub scanner is unavailable".to_owned())?;
        if self
            .pending_skill_hub_installs
            .get(identifier)
            .is_some_and(|install| install.scan_request_id.is_some())
        {
            return Ok(());
        }
        let request_id = operation_id("skill-hub-scan");
        gateway.load_skill_hub_scan(
            request_id.clone(),
            identifier.to_owned(),
            endpoint.profile_id.clone(),
            endpoint.instance_id.clone(),
            endpoint.authority_epoch,
        )?;
        if let Some(install) = self.pending_skill_hub_installs.get_mut(identifier) {
            install.scan_request_id = Some(request_id);
            install.scan_result = None;
            install.scan_error = None;
        }
        Ok(())
    }

    fn poll_skill_hub_install_actions(&mut self, ctx: &egui::Context) {
        let now = std::time::Instant::now();
        let due = self
            .pending_skill_hub_installs
            .iter()
            .filter_map(|(identifier, install)| {
                (install.completed.is_none()
                    && install.action_name.is_some()
                    && install.status_request_id.is_none()
                    && install.next_poll.is_none_or(|deadline| deadline <= now))
                .then(|| {
                    (
                        identifier.clone(),
                        install.action_name.clone().unwrap_or_default(),
                        install.profile_id.clone(),
                        install.instance_id.clone(),
                        install.authority_epoch,
                    )
                })
            })
            .collect::<Vec<_>>();
        for (identifier, action_name, profile_id, instance_id, authority_epoch) in due {
            let Some(endpoint) = self.gateway_endpoint.as_ref() else {
                continue;
            };
            if !self.gateway_connected
                || endpoint.profile_id != profile_id
                || endpoint.instance_id != instance_id
                || endpoint.authority_epoch != authority_epoch
            {
                if let Some(install) = self.pending_skill_hub_installs.get_mut(&identifier) {
                    install.error = Some(
                        "Skill install belongs to a different Gateway connection; refresh Skills before retrying."
                            .into(),
                    );
                    install.completed = Some(false);
                }
                continue;
            }
            let Some(gateway) = self.gateway_discovery.as_ref() else {
                continue;
            };
            let request_id = operation_id("skill-hub-install-status");
            match gateway.load_gateway_action_status(
                request_id.clone(),
                action_name,
                Some(profile_id),
            ) {
                Ok(()) => {
                    if let Some(install) = self.pending_skill_hub_installs.get_mut(&identifier) {
                        install.status_request_id = Some(request_id);
                        install.next_poll = None;
                    }
                    ctx.request_repaint_after(std::time::Duration::from_millis(1200));
                }
                Err(error) => {
                    if let Some(install) = self.pending_skill_hub_installs.get_mut(&identifier) {
                        install.attempts = install.attempts.saturating_add(1);
                        if install.attempts >= 400 {
                            install.error = Some(format!(
                                "Could not poll skill install action: {}",
                                bounded_status_text(&error, 1024)
                            ));
                            install.completed = Some(false);
                        } else {
                            install.next_poll = Some(now + std::time::Duration::from_millis(1200));
                        }
                    }
                    ctx.request_repaint_after(std::time::Duration::from_millis(1200));
                }
            }
        }
    }

    fn settle_skill_hub_action_status(
        &mut self,
        request_id: &str,
        profile: &Option<String>,
        action_name: &str,
        result: Result<GatewayActionStatus, String>,
        ctx: &egui::Context,
    ) -> bool {
        let Some(identifier) =
            self.pending_skill_hub_installs
                .iter()
                .find_map(|(identifier, install)| {
                    (install.status_request_id.as_deref() == Some(request_id))
                        .then(|| identifier.clone())
                })
        else {
            return false;
        };
        let Some(install) = self.pending_skill_hub_installs.get_mut(&identifier) else {
            return true;
        };
        if install.action_name.as_deref() != Some(action_name)
            || profile.as_deref() != Some(install.profile_id.as_str())
            || !self.gateway_connected
            || self.gateway_endpoint.as_ref().is_none_or(|endpoint| {
                endpoint.profile_id != install.profile_id
                    || endpoint.instance_id != install.instance_id
                    || endpoint.authority_epoch != install.authority_epoch
            })
        {
            install.status_request_id = None;
            install.error = Some("Skill install status belonged to a stale Gateway owner.".into());
            install.completed = Some(false);
            return true;
        }
        install.status_request_id = None;
        install.attempts = install.attempts.saturating_add(1);
        match result {
            Ok(status) if status.name == action_name => {
                install.lines = status
                    .lines
                    .into_iter()
                    .take(200)
                    .map(|line| bounded_status_text(&line, 2048))
                    .collect();
                if status.running || status.exit_code.is_none() {
                    if install.attempts >= 400 {
                        install.error =
                            Some("Timed out waiting for the skill install action.".into());
                        install.completed = Some(false);
                    } else {
                        install.next_poll = Some(
                            std::time::Instant::now() + std::time::Duration::from_millis(1200),
                        );
                    }
                } else if status.exit_code == Some(0) {
                    install.completed = Some(true);
                    install.error = None;
                    let name = install.name.clone();
                    self.status = format!("Installed skill {name}");
                    if let Err(error) = self.load_capabilities() {
                        self.capabilities_error = Some(error);
                    }
                    ctx.request_repaint();
                } else {
                    let detail = install
                        .lines
                        .iter()
                        .rev()
                        .take(3)
                        .cloned()
                        .collect::<Vec<_>>()
                        .into_iter()
                        .rev()
                        .collect::<Vec<_>>()
                        .join("\n");
                    install.error = Some(if detail.is_empty() {
                        format!(
                            "Skill installation failed with exit code {}.",
                            status.exit_code.unwrap_or_default()
                        )
                    } else {
                        detail
                    });
                    install.completed = Some(false);
                }
            }
            Ok(_) => {
                install.error =
                    Some("Hermes returned mismatched skill install action status.".into());
                install.completed = Some(false);
            }
            Err(error) => {
                install.error = Some(bounded_status_text(&error, 1024));
                install.completed = Some(false);
            }
        }
        true
    }

    fn set_toolset_enabled(&mut self, name: String, enabled: bool) -> Result<(), String> {
        if self.pending_toolset_bulk_update.is_some() {
            return Err("Wait for the current Toolsets update to finish".into());
        }
        self.set_toolset_enabled_inner(name, enabled)
    }

    fn set_toolset_enabled_inner(&mut self, name: String, enabled: bool) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before changing a Toolset".into());
        }
        if name.is_empty() || name.len() > 128 || name.chars().any(char::is_control) {
            return Err("Toolset name is invalid".into());
        }
        let Some(toolsets) = &self.toolsets else {
            return Err("Load Toolsets before changing one".into());
        };
        let Some(toolset) = toolsets.iter().find(|toolset| toolset.name == name) else {
            return Err(format!("Toolset {name:?} is not in the loaded inventory"));
        };
        if self.pending_toolset_updates.contains_key(&name) {
            return Err(format!(
                "Toolset {name:?} already has an update in progress"
            ));
        }
        if toolset.enabled == enabled {
            return Ok(());
        }
        let previous_enabled = toolset.enabled;
        let label = if toolset.label.is_empty() {
            toolset.name.clone()
        } else {
            toolset.label.clone()
        };
        let request_id = operation_id("toolset-enabled");
        let gateway = self
            .gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes gateway writer is unavailable".to_owned())?;
        gateway.set_toolset_enabled(request_id.clone(), name.clone(), enabled)?;
        if let Some(toolset) = self
            .toolsets
            .as_mut()
            .and_then(|toolsets| toolsets.iter_mut().find(|toolset| toolset.name == name))
        {
            toolset.enabled = enabled;
        }
        self.pending_toolset_updates.insert(
            name.clone(),
            PendingToolsetUpdate {
                request_id,
                previous_enabled,
            },
        );
        self.status = format!(
            "{} {label}…",
            if enabled { "Enabling" } else { "Disabling" }
        );
        Ok(())
    }

    fn set_toolsets_enabled_bulk(&mut self, enabled: bool) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before changing Toolsets".into());
        }
        if !self.pending_toolset_updates.is_empty() || self.pending_toolset_bulk_update.is_some() {
            return Err("Wait for the current Toolsets update to finish".into());
        }
        let toolsets = self
            .toolsets
            .as_ref()
            .ok_or_else(|| "Load Toolsets before changing them".to_owned())?;
        let remaining = toolsets
            .iter()
            .filter(|toolset| desktop_toolset_visible(&toolset.name) && toolset.enabled != enabled)
            .map(|toolset| toolset.name.clone())
            .collect::<VecDeque<_>>();
        if remaining.is_empty() {
            return Ok(());
        }
        self.pending_toolset_bulk_update = Some(PendingToolsetBulkUpdate {
            enabled,
            completed: 0,
            remaining,
        });
        if let Err(error) = self.advance_toolset_bulk_update() {
            self.pending_toolset_bulk_update = None;
            return Err(error);
        }
        Ok(())
    }

    fn advance_toolset_bulk_update(&mut self) -> Result<(), String> {
        let Some(bulk) = self.pending_toolset_bulk_update.as_ref() else {
            return Ok(());
        };
        let Some(name) = bulk.remaining.front().cloned() else {
            let finished = self
                .pending_toolset_bulk_update
                .take()
                .expect("completed Toolsets bulk update exists");
            self.status = format!(
                "{} {} Toolsets",
                if finished.enabled {
                    "Enabled"
                } else {
                    "Disabled"
                },
                finished.completed
            );
            return Ok(());
        };
        let enabled = bulk.enabled;
        self.set_toolset_enabled_inner(name, enabled)
    }

    fn open_skill_detail(&mut self, name: String) -> Result<(), String> {
        if name.trim().is_empty() || name.len() > 128 || name.chars().any(char::is_control) {
            return Err("Skill name is invalid".into());
        }
        if !self
            .skills
            .as_ref()
            .is_some_and(|skills| skills.iter().any(|skill| skill.name == name))
        {
            return Err(format!("Skill {name:?} is not in the loaded inventory"));
        }
        let endpoint = self
            .gateway_endpoint
            .as_ref()
            .ok_or_else(|| "Hermes Gateway endpoint is unavailable".to_owned())?;
        if !self.gateway_connected {
            return Err("Connect to Hermes before opening Skill details".into());
        }
        if self.pending_skill_content.as_ref().is_some_and(|pending| {
            pending.name == name
                && pending.profile_id == endpoint.profile_id
                && pending.instance_id == endpoint.instance_id
                && pending.authority_epoch == endpoint.authority_epoch
        }) {
            self.selected_skill = Some(name);
            return Ok(());
        }
        let request_id = operation_id("skill-content");
        let profile_id = endpoint.profile_id.clone();
        let instance_id = endpoint.instance_id.clone();
        let authority_epoch = endpoint.authority_epoch;
        let gateway = self
            .gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes capability reader is unavailable".to_owned())?;
        gateway.load_skill_content(
            request_id.clone(),
            name.clone(),
            profile_id.clone(),
            instance_id.clone(),
            authority_epoch,
        )?;
        self.selected_skill = Some(name.clone());
        self.skill_content = None;
        self.skill_content_owner = None;
        self.skill_content_error = None;
        self.pending_skill_content = Some(PendingSkillContent {
            request_id,
            name,
            profile_id,
            instance_id,
            authority_epoch,
        });
        Ok(())
    }

    fn set_skill_enabled(&mut self, name: String, enabled: bool) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before changing a Skill".into());
        }
        if name.is_empty() || name.len() > 128 || name.chars().any(char::is_control) {
            return Err("Skill name is invalid".into());
        }
        let Some(skills) = &self.skills else {
            return Err("Load Skills before changing one".into());
        };
        let Some(skill) = skills.iter().find(|skill| skill.name == name) else {
            return Err(format!("Skill {name:?} is not in the loaded inventory"));
        };
        if self.pending_skill_updates.contains_key(&name) {
            return Err(format!("Skill {name:?} already has an update in progress"));
        }
        if skill.enabled == enabled {
            return Ok(());
        }
        let previous_enabled = skill.enabled;
        let endpoint = self
            .gateway_endpoint
            .as_ref()
            .ok_or_else(|| "Hermes Gateway endpoint is unavailable".to_owned())?;
        let profile_id = endpoint.profile_id.clone();
        let instance_id = endpoint.instance_id.clone();
        let authority_epoch = endpoint.authority_epoch;
        let request_id = operation_id("skill-enabled");
        let gateway = self
            .gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes capability writer is unavailable".to_owned())?;
        gateway.set_skill_enabled(request_id.clone(), name.clone(), enabled)?;
        if let Some(skill) = self
            .skills
            .as_mut()
            .and_then(|skills| skills.iter_mut().find(|skill| skill.name == name))
        {
            skill.enabled = enabled;
        }
        self.pending_skill_updates.insert(
            name.clone(),
            PendingSkillUpdate {
                request_id,
                previous_enabled,
                profile_id,
                instance_id,
                authority_epoch,
            },
        );
        self.status = format!(
            "{} Skill {name}…",
            if enabled { "Enabling" } else { "Disabling" }
        );
        Ok(())
    }

    fn set_mcp_server_enabled(&mut self, name: String, enabled: bool) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before changing an MCP server".into());
        }
        if name.is_empty() || name.len() > 512 || name.chars().any(char::is_control) {
            return Err("MCP server name is invalid".into());
        }
        let Some(servers) = self.mcp_servers.as_mut() else {
            return Err("Load the MCP server inventory before changing a server".into());
        };
        let Some(server) = servers
            .servers
            .iter_mut()
            .find(|server| server.name == name)
        else {
            return Err("MCP server is not in the loaded inventory".into());
        };
        if self.pending_mcp_server_updates.contains_key(&name) {
            return Err("MCP server update is already pending".into());
        }
        if server.enabled == enabled {
            return Ok(());
        }
        let previous_enabled = server.enabled;
        server.enabled = enabled;
        let Some(endpoint) = self.gateway_endpoint.as_ref() else {
            server.enabled = previous_enabled;
            return Err("Hermes Gateway endpoint is unavailable".into());
        };
        let profile_id = endpoint.profile_id.clone();
        let instance_id = endpoint.instance_id.clone();
        let authority_epoch = endpoint.authority_epoch;
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            server.enabled = previous_enabled;
            return Err("Hermes Gateway reader is unavailable".into());
        };
        let request_id = operation_id("mcp-server-enabled");
        if let Err(error) =
            gateway.set_mcp_server_enabled(request_id.clone(), name.clone(), enabled)
        {
            server.enabled = previous_enabled;
            return Err(error);
        }
        self.pending_mcp_server_updates.insert(
            name,
            PendingMcpServerUpdate {
                request_id,
                previous_enabled,
                profile_id,
                instance_id,
                authority_epoch,
            },
        );
        self.mcp_servers_error = None;
        Ok(())
    }

    fn test_mcp_server(&mut self, name: String) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before testing an MCP server".into());
        }
        if name.is_empty() || name.len() > 512 || name.chars().any(char::is_control) {
            return Err("MCP server name is invalid".into());
        }
        if self.pending_mcp_server_tests.contains_key(&name) {
            return Err("MCP server test is already running".into());
        }
        if self.pending_mcp_server_tests.len() >= 4 {
            return Err("Four MCP server tests are already running".into());
        }
        let Some(servers) = &self.mcp_servers else {
            return Err("Load the MCP server inventory before testing a server".into());
        };
        if !servers.servers.iter().any(|server| server.name == name) {
            return Err("MCP server is not in the loaded inventory".into());
        }
        let Some(endpoint) = self.gateway_endpoint.as_ref() else {
            return Err("Hermes Gateway endpoint is unavailable".into());
        };
        let profile_id = endpoint.profile_id.clone();
        let instance_id = endpoint.instance_id.clone();
        let authority_epoch = endpoint.authority_epoch;
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            return Err("Hermes Gateway reader is unavailable".into());
        };
        let request_id = operation_id("mcp-server-test");
        gateway.test_mcp_server(request_id.clone(), name.clone())?;
        self.mcp_server_test_results.remove(&name);
        self.pending_mcp_server_tests.insert(
            name,
            PendingMcpServerTest {
                request_id,
                profile_id,
                instance_id,
                authority_epoch,
            },
        );
        Ok(())
    }

    fn add_mcp_server(
        &mut self,
        name: String,
        config: serde_json::Value,
        bearer_token: Option<String>,
    ) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before adding an MCP server".into());
        }
        let name = name.trim().to_owned();
        if name.is_empty() || name.len() > 512 || name.chars().any(char::is_control) {
            return Err(
                "MCP server name must be 1–512 characters without control characters".into(),
            );
        }
        if !config.is_object()
            || !serde_json::to_vec(&config).is_ok_and(|bytes| bytes.len() <= 512 * 1024)
            || bearer_token
                .as_ref()
                .is_some_and(|token| token.len() > 16_384 || token.chars().any(char::is_control))
        {
            return Err("MCP server configuration or bearer token is invalid or too large".into());
        }
        if self.pending_mcp_server_add.is_some() {
            return Err("An MCP server add is already pending".into());
        }
        if self
            .mcp_servers
            .as_ref()
            .is_some_and(|snapshot| snapshot.servers.iter().any(|server| server.name == name))
        {
            return Err("An MCP server with that name already exists".into());
        }
        let Some(endpoint) = self.gateway_endpoint.as_ref() else {
            return Err("Hermes Gateway endpoint is unavailable".into());
        };
        let request_id = operation_id("mcp-server-add");
        let pending = PendingMcpServerAdd {
            request_id: request_id.clone(),
            name: name.clone(),
            profile_id: endpoint.profile_id.clone(),
            instance_id: endpoint.instance_id.clone(),
            authority_epoch: endpoint.authority_epoch,
        };
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            return Err("Hermes Gateway connection is unavailable".into());
        };
        gateway.add_mcp_server(
            request_id,
            name,
            config,
            bearer_token.filter(|token| !token.trim().is_empty()),
            pending.profile_id.clone(),
            pending.instance_id.clone(),
            pending.authority_epoch,
        )?;
        self.pending_mcp_server_add = Some(pending);
        self.mcp_server_add_error = None;
        self.status = "Adding MCP server…".into();
        Ok(())
    }

    fn request_mcp_server_removal(&mut self, name: String) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before removing an MCP server".into());
        }
        if name.is_empty() || name.len() > 512 || name.chars().any(char::is_control) {
            return Err("MCP server name is invalid".into());
        }
        let Some(server) = self
            .mcp_servers
            .as_ref()
            .and_then(|snapshot| snapshot.servers.iter().find(|server| server.name == name))
        else {
            return Err("MCP server is not in the loaded profile inventory".into());
        };
        if self.pending_mcp_server_removals.contains_key(&name) {
            return Err("MCP server removal is already in progress".into());
        }
        let Some(endpoint) = self.gateway_endpoint.as_ref() else {
            return Err("Hermes Gateway endpoint is unavailable".into());
        };
        let _ = server;
        self.mcp_server_removal_confirmation = Some(McpServerRemovalConfirmation {
            name,
            profile_id: endpoint.profile_id.clone(),
            instance_id: endpoint.instance_id.clone(),
            authority_epoch: endpoint.authority_epoch,
        });
        Ok(())
    }

    fn confirm_mcp_server_removal(&mut self, name: String) -> Result<(), String> {
        let Some(confirmation) = self.mcp_server_removal_confirmation.clone() else {
            return Err("MCP server removal confirmation is not open".into());
        };
        if confirmation.name != name {
            return Err("MCP server removal confirmation is stale".into());
        }
        if !self.gateway_connected {
            self.mcp_server_removal_confirmation = None;
            return Err("Connect to Hermes before removing an MCP server".into());
        }
        if self.gateway_endpoint.as_ref().is_none_or(|endpoint| {
            endpoint.profile_id != confirmation.profile_id
                || endpoint.instance_id != confirmation.instance_id
                || endpoint.authority_epoch != confirmation.authority_epoch
        }) {
            self.mcp_server_removal_confirmation = None;
            return Err("Hermes profile changed; reopen the MCP removal confirmation".into());
        }
        if !self
            .mcp_servers
            .as_ref()
            .is_some_and(|snapshot| snapshot.servers.iter().any(|server| server.name == name))
        {
            self.mcp_server_removal_confirmation = None;
            return Err("MCP server is no longer in the loaded profile inventory".into());
        }
        if self.pending_mcp_server_removals.contains_key(&name) {
            return Err("MCP server removal is already in progress".into());
        }
        let request_id = operation_id("mcp-server-remove");
        let gateway = self
            .gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes Gateway writer is unavailable".to_owned())?;
        gateway.remove_mcp_server(
            request_id.clone(),
            name.clone(),
            confirmation.profile_id.clone(),
            confirmation.instance_id.clone(),
            confirmation.authority_epoch,
        )?;
        self.pending_mcp_server_removals.insert(
            name,
            PendingMcpServerRemoval {
                request_id,
                profile_id: confirmation.profile_id,
                instance_id: confirmation.instance_id,
                authority_epoch: confirmation.authority_epoch,
            },
        );
        self.mcp_server_removal_confirmation = None;
        self.status = "Removing MCP server…".into();
        Ok(())
    }

    fn show_mcp_server_removal_dialog(&mut self, ctx: &egui::Context) {
        let Some(confirmation) = self.mcp_server_removal_confirmation.clone() else {
            return;
        };
        let name = confirmation.name;
        let mut confirm = false;
        let mut cancel = false;
        egui::Window::new("Remove MCP server?")
            .id(Id::NULL.with(("mcp-server-remove", &name)))
            .collapsible(false)
            .resizable(false)
            .show(ctx, |ui| {
                ui.label(format!("Remove {name} from the selected Hermes profile?"));
                ui.label("Hermes will remove this server configuration and its stored credential.");
                ui.horizontal(|ui| {
                    confirm = ui
                        .button("Remove")
                        .accessible_name(format!("Confirm MCP server removal: {name}"))
                        .clicked();
                    cancel = ui
                        .button("Cancel")
                        .accessible_name("Cancel MCP server removal")
                        .clicked();
                });
            });
        if confirm {
            self.confirm_mcp_server_removal(name)
                .unwrap_or_else(|error| self.status = error);
        } else if cancel {
            self.mcp_server_removal_confirmation = None;
        }
    }

    fn stop_generation(&mut self) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before stopping a response".into());
        }
        let session_id = self
            .active_runtime_session_id
            .clone()
            .ok_or_else(|| "There is no active Hermes session to stop".to_owned())?;
        let pending_key =
            self.session_identity_key(&session_id, self.active_session_profile.as_deref());
        let Some(pending) = self.pending_submissions.get(&pending_key) else {
            return Err("There is no active response to stop".into());
        };
        if pending.uncertain {
            return Err("Confirm the pending message admission before stopping a response".into());
        }
        if self
            .pending_interrupt
            .as_ref()
            .is_some_and(|(_, pending_session)| pending_session == &session_id)
        {
            return Err("A stop request is already in progress".into());
        }
        let request_id = operation_id("interrupt");
        self.gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes gateway writer is unavailable".to_owned())?
            .interrupt_session(
                request_id.clone(),
                session_id.clone(),
                self.active_session_profile.clone(),
            )?;
        self.pending_interrupt = Some((request_id, session_id));
        self.status = "Stopping Hermes response…".into();
        Ok(())
    }

    fn respond_to_approval(&mut self, prompt_id: String, choice: String) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before responding to an approval".into());
        }
        let Some(prompt) = self.approval_prompts.get(&prompt_id) else {
            return Err("This approval is no longer pending".into());
        };
        if !self.session_runtime_is_known(&prompt.session_id, prompt.profile.as_deref()) {
            return Err("This approval no longer maps to a unique open session pane".into());
        }
        if !matches!(choice.as_str(), "once" | "session" | "always" | "deny")
            || !prompt.choices.iter().any(|allowed| allowed == &choice)
        {
            return Err("That decision is not available for this approval".into());
        }
        if prompt.response_pending.is_some() {
            return Err("A decision is already being sent for this approval".into());
        }
        let session_id = prompt.session_id.clone();
        let generation = prompt.execution_generation;
        let profile = prompt.profile.clone();
        let server_request_id = prompt.server_request_id.clone();
        let gateway = self
            .gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes gateway writer is unavailable".to_owned())?;
        if let Some(server_request_id) = server_request_id {
            gateway.respond_server_request(
                server_request_id.clone(),
                Ok(serde_json::json!({"choice":choice})),
            )?;
            if let Some(prompt) = self.approval_prompts.get_mut(&prompt_id) {
                prompt.response_pending = Some((server_request_id, choice));
            }
            self.status = "Sending approval decision to Hermes…".into();
            return Ok(());
        }
        let request_id = operation_id("approval");
        gateway.respond_approval(
            request_id.clone(),
            session_id,
            profile,
            generation,
            prompt_id.clone(),
            choice.clone(),
        )?;
        if let Some(prompt) = self.approval_prompts.get_mut(&prompt_id) {
            prompt.response_pending = Some((request_id, choice));
        }
        self.status = "Sending approval decision to Hermes…".into();
        Ok(())
    }

    fn respond_to_clarify(&mut self, prompt_id: String, answer: String) -> Result<(), String> {
        if !self.gateway_connected {
            return Err("Connect to Hermes before answering a question".into());
        }
        if let Some(prompt) = self.batch_clarify_prompts.get(&prompt_id) {
            if !self.session_runtime_is_known(&prompt.session_id, prompt.profile.as_deref()) {
                return Err("These questions no longer map to a unique open session pane".into());
            }
            if prompt.response_pending {
                return Err("Answers are already being sent for these questions".into());
            }
            let server_request_id = prompt.server_request_id.clone();
            if answer.is_empty() {
                self.gateway_discovery
                    .as_ref()
                    .ok_or_else(|| "Hermes gateway writer is unavailable".to_owned())?
                    .respond_server_request(server_request_id, Ok(serde_json::json!({})))?;
                if let Some(prompt) = self.batch_clarify_prompts.get_mut(&prompt_id) {
                    prompt.response_pending = true;
                }
                self.status = "Skipping Hermes questions…".into();
                return Ok(());
            }

            let value: serde_json::Value = serde_json::from_str(&answer)
                .map_err(|_| "Clarify answers are not valid JSON".to_owned())?;
            let answers = value
                .get("answers")
                .and_then(serde_json::Value::as_object)
                .ok_or_else(|| "Clarify answers must contain an answers object".to_owned())?;
            let expected = prompt
                .questions
                .iter()
                .map(|question| question.qid.as_str())
                .collect::<BTreeSet<_>>();
            if answers.keys().any(|qid| !expected.contains(qid.as_str()))
                || expected.iter().any(|qid| !answers.contains_key(*qid))
                || answers.values().any(|value| match value {
                    serde_json::Value::Null => false,
                    serde_json::Value::String(value) => {
                        value.len() > 16_384 || value.chars().any(|character| character == '\0')
                    }
                    _ => true,
                })
                || answers.values().all(serde_json::Value::is_null)
            {
                return Err("Clarify answers do not match the pending questions".into());
            }
            let pending_locks = prompt
                .questions
                .iter()
                .map(|question| PendingClarifyLock {
                    question_id: question.qid.clone(),
                    answer: answers
                        .get(&question.qid)
                        .and_then(serde_json::Value::as_str)
                        .map(str::to_owned),
                })
                .collect();
            if let Some(prompt) = self.batch_clarify_prompts.get_mut(&prompt_id) {
                prompt.response_pending = true;
                prompt.pending_locks = pending_locks;
            }
            if let Err(error) = self.send_next_batch_clarify_lock(&prompt_id) {
                if let Some(prompt) = self.batch_clarify_prompts.get_mut(&prompt_id) {
                    prompt.response_pending = false;
                    prompt.pending_locks.clear();
                    prompt.lock_in_flight = None;
                }
                return Err(error);
            }
            self.status = "Sending answers to Hermes…".into();
            return Ok(());
        }
        if answer.len() > 16_384 || answer.chars().any(|character| character == '\0') {
            return Err("Clarify answer must be at most 16384 bytes and contain no NUL".into());
        }
        let Some(prompt) = self.clarify_prompts.get(&prompt_id) else {
            return Err("This question is no longer pending".into());
        };
        if !self.session_runtime_is_known(&prompt.session_id, prompt.profile.as_deref()) {
            return Err("This question no longer maps to a unique open session pane".into());
        }
        if prompt.response_pending.is_some() {
            return Err("An answer is already being sent for this question".into());
        }
        let session_id = prompt.session_id.clone();
        let generation = prompt.execution_generation;
        let profile = prompt.profile.clone();
        let request_id = operation_id("clarify");
        self.gateway_discovery
            .as_ref()
            .ok_or_else(|| "Hermes gateway writer is unavailable".to_owned())?
            .respond_clarify(
                request_id.clone(),
                session_id,
                profile,
                generation,
                prompt_id.clone(),
                answer.clone(),
            )?;
        if let Some(prompt) = self.clarify_prompts.get_mut(&prompt_id) {
            prompt.response_pending = Some((request_id, answer));
        }
        self.status = if self.clarify_prompts.get(&prompt_id).is_some_and(|prompt| {
            prompt
                .response_pending
                .as_ref()
                .is_some_and(|(_, value)| value.is_empty())
        }) {
            "Skipping Hermes question…".into()
        } else {
            "Sending answer to Hermes…".into()
        };
        Ok(())
    }

    fn handle_clarify_responded(
        &mut self,
        request_id: String,
        session_id: String,
        prompt_id: String,
        answer: String,
        result: Result<(), String>,
    ) {
        let Some(prompt) = self.clarify_prompts.get(&prompt_id) else {
            return;
        };
        if prompt.session_id != session_id
            || prompt.response_pending.as_ref() != Some(&(request_id.clone(), answer.clone()))
        {
            return;
        }
        match result {
            Ok(()) => {
                self.clarify_prompts.remove(&prompt_id);
                self.status = if answer.is_empty() {
                    "Hermes question skipped".into()
                } else {
                    "Hermes received your answer".into()
                };
            }
            Err(error) => {
                if let Some(prompt) = self.clarify_prompts.get_mut(&prompt_id) {
                    prompt.response_pending = None;
                }
                self.status = error;
            }
        }
    }

    fn handle_approval_responded(
        &mut self,
        request_id: String,
        session_id: String,
        prompt_id: String,
        choice: String,
        result: Result<(), String>,
    ) {
        let Some(prompt) = self.approval_prompts.get(&prompt_id) else {
            return;
        };
        if prompt.session_id != session_id
            || prompt.response_pending.as_ref() != Some(&(request_id.clone(), choice.clone()))
        {
            return;
        }
        match result {
            Ok(()) => {
                self.approval_prompts.remove(&prompt_id);
                self.status = "Hermes received the approval decision".into();
            }
            Err(error) => {
                if let Some(prompt) = self.approval_prompts.get_mut(&prompt_id) {
                    prompt.response_pending = None;
                }
                self.status = error;
            }
        }
    }

    fn handle_session_interrupted(
        &mut self,
        request_id: String,
        session_id: String,
        result: Result<bool, String>,
    ) {
        if !self
            .pending_interrupt
            .as_ref()
            .is_some_and(|(pending_request, pending_session)| {
                pending_request == &request_id && pending_session == &session_id
            })
        {
            return;
        }
        self.pending_interrupt = None;
        match result {
            Ok(true) => {
                if let Some(message) = self.transcript.iter_mut().rev().find(|message| {
                    message.get("role").and_then(|value| value.as_str()) == Some("assistant")
                        && message.get("streaming").and_then(|value| value.as_bool()) == Some(true)
                }) {
                    message["streaming"] = serde_json::Value::Bool(false);
                    message["interrupted"] = serde_json::Value::Bool(true);
                }
                self.pending_submissions
                    .retain(|_, pending| pending.session_id != session_id);
                self.status = "Hermes response stopped".into();
            }
            Ok(false) => {
                self.pending_submissions
                    .retain(|_, pending| pending.session_id != session_id);
                self.status = "Hermes reported no active response".into();
            }
            Err(error) => self.status = error,
        }
    }

    #[cfg(feature = "agent-automation")]
    fn current_route_path(&self) -> String {
        if self.route == AppRoute::Artifacts {
            format!("/artifacts?tab={}", self.artifacts_filter.as_str())
        } else if self.route == AppRoute::Capabilities {
            format!("/capabilities?tab={}", self.capabilities_tab.as_str())
        } else if self.route == AppRoute::CommandCenter
            && self.command_center_section != CommandCenterSection::Sessions
        {
            format!(
                "/command-center?section={}",
                self.command_center_section.as_str()
            )
        } else {
            self.route.path()
        }
    }

    fn ensure_repo_scan_config_loaded(&mut self) {
        let Some(profile) = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone())
        else {
            return;
        };
        if profile.eq_ignore_ascii_case("all") {
            return;
        }
        if self
            .repo_scan_config_request
            .as_ref()
            .is_some_and(|(_, pending)| pending != &profile)
        {
            self.repo_scan_config_request = None;
        }
        if self
            .repo_scan_config_save_request
            .as_ref()
            .is_some_and(|(_, pending, _)| pending != &profile)
        {
            self.repo_scan_config_save_request = None;
            self.repo_scan_config = None;
            self.repo_scan_config_profile = None;
            self.repo_scan_config_error = None;
            self.status = "A workspace settings save may still be settling for the previous profile; reopening Settings there will confirm its stored value.".into();
        }
        if self.repo_scan_config_request.is_some()
            || self.repo_scan_config_profile.as_deref() == Some(profile.as_str())
            || (self.repo_scan_config_profile.is_none() && self.repo_scan_config_error.is_some())
        {
            return;
        }
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            return;
        };
        let request_id = operation_id("repo-scan-config-load");
        match gateway.load_repo_scan_config(request_id.clone(), Some(profile.clone())) {
            Ok(()) => {
                self.repo_scan_config_request = Some((request_id, profile));
                self.repo_scan_config_error = None;
            }
            Err(error) => self.repo_scan_config_error = Some(error),
        }
    }

    fn repo_scan_project_context_active(&self) -> bool {
        matches!(self.route, AppRoute::NewChat | AppRoute::Session(_))
            && self
                .gateway_endpoint
                .as_ref()
                .is_some_and(|endpoint| !endpoint.profile_id.eq_ignore_ascii_case("all"))
    }

    fn start_repo_discovery_for_profile(
        &mut self,
        profile: String,
        policy: RepoScanPolicy,
        force: bool,
    ) {
        let Some(endpoint) = self.gateway_endpoint.as_ref().cloned() else {
            return;
        };
        if !self.gateway_connected
            || endpoint.profile_id != profile
            || profile.eq_ignore_ascii_case("all")
        {
            return;
        }
        if self.repo_scan_discovery_request.as_ref().is_some_and(
            |(_, pending_profile, pending_policy)| {
                pending_profile == &profile && pending_policy == &policy
            },
        ) {
            return;
        }
        if !force
            && self.repo_scan_completed_policy.as_ref() == Some(&(profile.clone(), policy.clone()))
        {
            return;
        }
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            return;
        };
        let request_id = operation_id("repo-discovery");
        let generation = self
            .repo_scan_generation
            .fetch_add(1, Ordering::AcqRel)
            .wrapping_add(1);
        let remote = endpoint.remote_auth.is_some();
        let result = if remote {
            gateway.discover_remote_repos(request_id.clone(), profile.clone())
        } else {
            let home_dir = std::env::var_os("USERPROFILE")
                .or_else(|| std::env::var_os("HOME"))
                .map(std::path::PathBuf::from)
                .filter(|path| path.is_absolute());
            match home_dir {
                Some(home_dir) => gateway.scan_and_record_repos(
                    request_id.clone(),
                    profile.clone(),
                    policy.clone(),
                    home_dir,
                    Arc::clone(&self.repo_scan_generation),
                    generation,
                ),
                None => Err(
                    "Could not resolve the system home path for configured repository paths".into(),
                ),
            }
        };
        match result {
            Ok(()) => {
                self.repo_scan_discovery_request = Some((request_id, profile, policy));
                self.repo_scan_last_started_at = Some(std::time::Instant::now());
                self.repo_scan_config_error = None;
            }
            Err(error) => self.repo_scan_config_error = Some(error),
        }
    }

    fn settle_repo_discovery(
        &mut self,
        request_id: &str,
        profile: &str,
        result: Result<(), String>,
    ) {
        let Some((expected_id, expected_profile, expected_policy)) =
            self.repo_scan_discovery_request.clone()
        else {
            return;
        };
        if expected_id != request_id {
            return;
        }
        if profile != expected_profile
            || self
                .gateway_endpoint
                .as_ref()
                .is_none_or(|endpoint| endpoint.profile_id != expected_profile)
            || self.repo_scan_config_profile.as_deref() != Some(expected_profile.as_str())
            || self.repo_scan_config.as_ref() != Some(&expected_policy)
        {
            self.repo_scan_discovery_request = None;
            return;
        }
        self.repo_scan_discovery_request = None;
        match result {
            Ok(()) => {
                self.repo_scan_completed_policy = Some((expected_profile.clone(), expected_policy));
                self.repo_scan_config_error = None;
                if self.repo_scan_project_context_active() {
                    // A successful scan changes the host's project tree. Invalidate the loaded
                    // marker and any older in-flight read, while retaining the last good tree
                    // until the replacement response settles.
                    self.project_session_color_profiles_loaded
                        .remove(&expected_profile);
                    self.project_session_color_requests
                        .remove(&expected_profile);
                    self.project_tree_refreshes.remove(&expected_profile);
                    self.load_project_session_colors();
                }
            }
            Err(error) => {
                self.status = format!("Repository discovery failed: {error}");
                self.repo_scan_config_error = Some(error);
            }
        }
    }

    fn save_repo_scan_config(&mut self) {
        let Some(profile) = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone())
        else {
            self.repo_scan_config_error = Some("Hermes gateway is unavailable".into());
            return;
        };
        if profile.eq_ignore_ascii_case("all") {
            self.repo_scan_config_error =
                Some("Workspace discovery settings require a single Hermes profile".into());
            return;
        }
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            self.repo_scan_config_error = Some("Hermes gateway is unavailable".into());
            return;
        };
        let policy = RepoScanPolicy {
            enabled: self.repo_scan_enabled_draft,
            roots: parse_config_path_lines(&self.repo_scan_roots_draft),
            exclude_paths: parse_config_path_lines(&self.repo_scan_excludes_draft),
        };
        let request_id = operation_id("repo-scan-config-save");
        match gateway.save_repo_scan_config(
            request_id.clone(),
            Some(profile.clone()),
            policy.clone(),
        ) {
            Ok(()) => {
                self.repo_scan_config_save_request = Some((request_id, profile, policy));
                self.repo_scan_config_error = None;
            }
            Err(error) => self.repo_scan_config_error = Some(error),
        }
    }

    fn show_repo_scan_settings(&mut self, ui: &mut Ui) {
        self.ensure_repo_scan_config_loaded();
        if !self.gateway_connected {
            ui.label(RichText::new("Connect to Hermes to load workspace settings.").color(MUTED));
            return;
        }
        if self
            .gateway_endpoint
            .as_ref()
            .is_some_and(|endpoint| endpoint.profile_id.eq_ignore_ascii_case("all"))
        {
            ui.label(
                RichText::new("Choose a single Hermes profile to edit workspace settings.")
                    .color(MUTED),
            );
            return;
        }
        if self.repo_scan_config_profile.is_none() {
            if let Some(error) = self.repo_scan_config_error.as_deref() {
                ui.colored_label(Color32::LIGHT_RED, error);
                if ui.button("Retry").clicked() {
                    self.repo_scan_config_request = None;
                    self.repo_scan_config_profile = None;
                    self.repo_scan_config_error = None;
                    self.ensure_repo_scan_config_loaded();
                }
            } else {
                ui.label(RichText::new("Loading workspace settings…").color(MUTED));
            }
            return;
        }
        let saving = self.repo_scan_config_save_request.is_some();
        ui.heading("Workspace repository discovery");
        ui.label(
            RichText::new("Git repositories are discovered only under the roots listed below.")
                .color(MUTED),
        );
        ui.add_enabled_ui(!saving, |ui| {
            ui.checkbox(
                &mut self.repo_scan_enabled_draft,
                "Enable repository discovery",
            )
            .accessible_name("Enable repository discovery");
            ui.label("Scan roots (one path per line)");
            ui.add(
                egui::TextEdit::multiline(&mut self.repo_scan_roots_draft)
                    .desired_rows(4)
                    .desired_width(f32::INFINITY),
            )
            .accessible_name("Repository scan roots");
            ui.label("Excluded paths (one path per line)");
            ui.add(
                egui::TextEdit::multiline(&mut self.repo_scan_excludes_draft)
                    .desired_rows(3)
                    .desired_width(f32::INFINITY),
            )
            .accessible_name("Repository scan exclusions");
            ui.label(
                RichText::new(
                    "An empty root list scans no directories; Hermes home is never inferred here.",
                )
                .size(11.0)
                .color(MUTED),
            );
        });
        let draft = RepoScanPolicy {
            enabled: self.repo_scan_enabled_draft,
            roots: parse_config_path_lines(&self.repo_scan_roots_draft),
            exclude_paths: parse_config_path_lines(&self.repo_scan_excludes_draft),
        };
        let changed = self
            .repo_scan_config
            .as_ref()
            .is_some_and(|saved| saved != &draft);
        if ui
            .add_enabled(
                !saving && changed,
                egui::Button::new(if saving {
                    "Saving…"
                } else {
                    "Save workspace settings"
                }),
            )
            .accessible_name("Save workspace repository discovery settings")
            .clicked()
        {
            self.save_repo_scan_config();
        }
        if let Some(error) = self.repo_scan_config_error.as_deref() {
            ui.colored_label(Color32::LIGHT_RED, error);
        }
    }

    fn show_settings(&mut self, ui: &mut Ui) {
        ui.horizontal(|ui| {
            if ui
                .selectable_label(
                    !self.settings_keybindings_active && !self.settings_fallbacks_active,
                    "Workspace",
                )
                .accessible_name("Workspace settings")
                .clicked()
            {
                self.settings_keybindings_active = false;
                self.settings_fallbacks_active = false;
                self.keybindings_panel.cancel_capture();
            }
            if ui
                .selectable_label(self.settings_fallbacks_active, "Model fallbacks")
                .accessible_name("Model fallback settings")
                .clicked()
            {
                self.settings_keybindings_active = false;
                self.settings_fallbacks_active = true;
                self.keybindings_panel.cancel_capture();
            }
            if ui
                .selectable_label(self.settings_keybindings_active, "Keybindings")
                .accessible_name("Keybindings settings")
                .clicked()
            {
                self.settings_keybindings_active = true;
                self.settings_fallbacks_active = false;
            }
        });
        ui.separator();
        if self.settings_keybindings_active {
            if let Some(error) = self.keybindings_error.as_deref() {
                ui.colored_label(Color32::LIGHT_RED, error);
                if ui.button("Retry keybindings").clicked() {
                    match KeybindingStore::load(
                        self.workspace.data_directory().join("keybindings.json"),
                        current_key_platform(),
                    ) {
                        Ok(store) => {
                            self.keybindings = Some(store);
                            self.keybindings_error = None;
                        }
                        Err(error) => self.keybindings_error = Some(error),
                    }
                }
                return;
            }
            if let Some(store) = self.keybindings.as_mut() {
                self.keybindings_panel
                    .show(ui, store, current_key_platform());
            }
        } else if self.settings_fallbacks_active {
            self.show_fallback_routes_settings(ui);
        } else {
            self.show_repo_scan_settings(ui);
        }
    }

    fn ensure_fallback_model_options_loaded(&mut self, profile: &str) {
        if self
            .fallback_model_options_profile
            .as_deref()
            .is_some_and(|loaded| loaded != profile)
        {
            self.fallback_model_options = None;
            self.fallback_model_options_profile = None;
            self.fallback_model_options_error = None;
        }
        if self
            .fallback_model_options_request
            .as_ref()
            .is_some_and(|(_, requested)| requested != profile)
        {
            self.fallback_model_options_request = None;
        }
        if self.fallback_model_options_request.is_some()
            || self.fallback_model_options_profile.as_deref() == Some(profile)
        {
            return;
        }
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            self.fallback_model_options_profile = Some(profile.to_owned());
            self.fallback_model_options_error = Some("Hermes gateway reader is unavailable".into());
            return;
        };
        let request_id = operation_id("fallback-model-options-load");
        match gateway.load_model_options(request_id.clone(), Some(profile.to_owned())) {
            Ok(()) => {
                self.fallback_model_options_request = Some((request_id, profile.to_owned()));
                self.fallback_model_options_error = None;
            }
            Err(error) => {
                self.fallback_model_options_profile = Some(profile.to_owned());
                self.fallback_model_options_error = Some(error);
            }
        }
    }

    fn ensure_fallback_routes_loaded(&mut self) {
        let Some(profile) = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone())
        else {
            return;
        };
        if profile.eq_ignore_ascii_case("all") {
            return;
        }
        self.ensure_fallback_model_options_loaded(&profile);
        if self
            .fallback_routes_profile
            .as_deref()
            .is_some_and(|loaded| loaded != profile)
        {
            self.fallback_routes = None;
            self.fallback_routes_profile = None;
            self.fallback_routes_error = None;
        }
        if self
            .fallback_routes_request
            .as_ref()
            .is_some_and(|(_, pending)| pending != &profile)
        {
            self.fallback_routes_request = None;
        }
        if self
            .fallback_routes_save_request
            .as_ref()
            .is_some_and(|(_, pending, _)| pending != &profile)
        {
            self.fallback_routes_save_request = None;
            self.fallback_routes = None;
            self.fallback_routes_profile = None;
            self.fallback_routes_error = None;
            self.status = "A fallback settings save may still be settling for the previous profile; reopening Model fallbacks there will confirm its stored value.".into();
        }
        if self.fallback_routes_request.is_some()
            || self.fallback_routes_profile.as_deref() == Some(profile.as_str())
            || (self.fallback_routes_profile.is_none() && self.fallback_routes_error.is_some())
        {
            return;
        }
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            return;
        };
        let request_id = operation_id("fallback-providers-config-load");
        match gateway.load_fallback_providers_config(request_id.clone(), Some(profile.clone())) {
            Ok(()) => {
                self.fallback_routes_request = Some((request_id, profile));
                self.fallback_routes_error = None;
            }
            Err(error) => self.fallback_routes_error = Some(error),
        }
    }

    fn save_fallback_routes(&mut self) {
        let Some(profile) = self
            .gateway_endpoint
            .as_ref()
            .map(|endpoint| endpoint.profile_id.clone())
        else {
            self.fallback_routes_error = Some("Hermes gateway is unavailable".into());
            return;
        };
        if profile.eq_ignore_ascii_case("all") {
            self.fallback_routes_error =
                Some("Model fallback settings require a single Hermes profile".into());
            return;
        }
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            self.fallback_routes_error = Some("Hermes gateway is unavailable".into());
            return;
        };
        let routes = self
            .fallback_routes
            .as_deref()
            .map(complete_fallback_route_values)
            .unwrap_or_default();
        let request_id = operation_id("fallback-providers-config-save");
        match gateway.save_fallback_providers_config(
            request_id.clone(),
            Some(profile.clone()),
            routes.clone(),
        ) {
            Ok(()) => {
                self.fallback_routes_save_request = Some((request_id, profile, routes));
                self.fallback_routes_error = None;
            }
            Err(error) => self.fallback_routes_error = Some(error),
        }
    }

    fn show_fallback_routes_settings(&mut self, ui: &mut Ui) {
        self.ensure_fallback_routes_loaded();
        ui.heading("Model fallback routes");
        ui.label(RichText::new(
            "Hermes tries these provider and model pairs in order when the default model fails.",
        ).color(MUTED));
        if !self.gateway_connected {
            ui.label(
                RichText::new("Connect to Hermes to load model fallback settings.").color(MUTED),
            );
            return;
        }
        if self
            .gateway_endpoint
            .as_ref()
            .is_some_and(|endpoint| endpoint.profile_id.eq_ignore_ascii_case("all"))
        {
            ui.label(
                RichText::new("Choose a single Hermes profile to edit model fallback settings.")
                    .color(MUTED),
            );
            return;
        }
        if self.fallback_routes_profile.is_none() {
            if let Some(error) = self.fallback_routes_error.as_deref() {
                ui.colored_label(Color32::LIGHT_RED, error);
                if ui.button("Retry model fallback settings").clicked() {
                    self.fallback_routes_request = None;
                    self.fallback_routes_error = None;
                    self.ensure_fallback_routes_loaded();
                }
            } else {
                ui.label(RichText::new("Loading model fallback settings…").color(MUTED));
            }
            return;
        }
        let saving = self.fallback_routes_save_request.is_some();
        let model_options_loading = self.fallback_model_options_request.is_some();
        let providers = self
            .fallback_model_options
            .as_ref()
            .map(|snapshot| snapshot.providers.clone())
            .unwrap_or_default();
        let mut remove_index = None;
        let mut retry_model_options = false;
        ui.add_enabled_ui(!saving, |ui| {
            let routes = self.fallback_routes.get_or_insert_with(Vec::new);
            if routes.is_empty() {
                ui.label(RichText::new("No fallback routes are configured.").color(MUTED));
            }
            if model_options_loading {
                ui.label(RichText::new("Loading configured providers and models…").color(MUTED));
            }
            if let Some(error) = self.fallback_model_options_error.as_deref() {
                ui.horizontal_wrapped(|ui| {
                    ui.colored_label(Color32::LIGHT_RED, format!("Model catalog: {error}"));
                    if ui.button("Retry model catalog").clicked() {
                        retry_model_options = true;
                    }
                });
            }
            ui.label(RichText::new(
                "Choose configured provider/model values or enter custom IDs below. Existing route-specific settings are preserved.",
            ).color(MUTED));
            for (index, route) in routes.iter_mut().enumerate() {
                let row = index + 1;
                let selected_provider_name = providers
                    .iter()
                    .find(|provider| provider.slug == route.provider)
                    .map(|provider| provider.name.clone())
                    .unwrap_or_else(|| {
                        if route.provider.trim().is_empty() {
                            "Choose configured provider".to_owned()
                        } else {
                            format!("Custom · {}", route.provider)
                        }
                    });
                let provider_models = providers
                    .iter()
                    .find(|provider| provider.slug == route.provider)
                    .map(|provider| provider.models.clone())
                    .unwrap_or_default();
                let selected_model_label = if route.model.trim().is_empty() {
                    "Choose configured model".to_owned()
                } else if provider_models.iter().any(|model| model == &route.model) {
                    route.model.clone()
                } else {
                    format!("Custom · {}", route.model)
                };
                let mut selected_provider = None;
                let mut selected_model = None;
                ui.horizontal(|ui| {
                    ui.label(format!("{row}."));
                    egui::ComboBox::new(("fallback-provider", row), "Configured provider")
                        .selected_text(selected_provider_name)
                        .show_ui(ui, |ui| {
                            for provider in &providers {
                                if ui
                                    .selectable_label(route.provider == provider.slug, &provider.name)
                                    .clicked()
                                {
                                    selected_provider = Some(provider.slug.clone());
                                }
                            }
                        })
                        .response
                        .accessible_name(format!("Select configured fallback provider {row}"));
                    egui::ComboBox::new(("fallback-model", row), "Configured model")
                        .selected_text(selected_model_label)
                        .show_ui(ui, |ui| {
                            for model in &provider_models {
                                if ui
                                    .selectable_label(route.model == *model, model)
                                    .clicked()
                                {
                                    selected_model = Some(model.clone());
                                }
                            }
                            if provider_models.is_empty() {
                                ui.label("No catalog models for this provider");
                            }
                        })
                        .response
                        .accessible_name(format!("Select configured fallback model {row}"));
                    if ui.button(format!("Remove fallback {row}")).clicked() {
                        remove_index = Some(index);
                    }
                });
                if let Some(provider) = selected_provider {
                    route.provider = provider;
                    route.model.clear();
                }
                if let Some(model) = selected_model {
                    route.model = model;
                }
                ui.horizontal(|ui| {
                    ui.label("Custom IDs:");
                    ui.add(
                        egui::TextEdit::singleline(&mut route.provider)
                            .hint_text("provider ID")
                            .desired_width(170.0),
                    )
                    .accessible_name(format!("Fallback provider {row}"));
                    ui.add(
                        egui::TextEdit::singleline(&mut route.model)
                            .hint_text("model ID")
                            .desired_width(240.0),
                    )
                    .accessible_name(format!("Fallback model {row}"));
                });
            }
            if let Some(index) = remove_index {
                routes.remove(index);
            }
            if ui.button("Add fallback route").clicked() {
                routes.push(FallbackRouteDraft::from_value(serde_json::json!({
                    "provider": "",
                    "model": ""
                })));
            }
        });
        if retry_model_options {
            self.fallback_model_options = None;
            self.fallback_model_options_profile = None;
            self.fallback_model_options_error = None;
            self.ensure_fallback_routes_loaded();
        }
        let save_enabled = !saving
            && self.fallback_routes.as_ref().is_some_and(|routes| {
                routes.iter().all(|route| {
                    route.is_complete()
                        || (route.provider.trim().is_empty() && route.model.trim().is_empty())
                })
            });
        if ui
            .add_enabled(
                save_enabled,
                egui::Button::new("Save model fallback routes"),
            )
            .clicked()
        {
            self.save_fallback_routes();
        }
        if saving {
            ui.label(RichText::new("Saving fallback routes…").color(MUTED));
        }
        if let Some(error) = self.fallback_routes_error.as_deref() {
            ui.colored_label(Color32::LIGHT_RED, error);
        }
    }

    fn request_command_center_maintenance(&mut self, operation: CommandCenterMaintenanceOperation) {
        if !self.gateway_connected {
            self.command_center_maintenance_error = Some("Hermes gateway is unavailable".into());
            return;
        }
        let Some(endpoint) = self.gateway_endpoint.as_ref() else {
            self.command_center_maintenance_error =
                Some("Hermes gateway profile is unavailable".into());
            return;
        };
        if endpoint.profile_id.eq_ignore_ascii_case("all") {
            self.command_center_maintenance_error =
                Some("Maintenance controls require one Hermes profile".into());
            return;
        }
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            self.command_center_maintenance_error =
                Some("Hermes gateway HTTP worker is unavailable".into());
            return;
        };
        self.command_center_maintenance_generation =
            self.command_center_maintenance_generation.saturating_add(1);
        let request_id = operation_id("command-center-maintenance");
        let profile = endpoint.profile_id.clone();
        let endpoint_instance_id = endpoint.instance_id.clone();
        let authority_epoch = endpoint.authority_epoch;
        match gateway.command_center_maintenance(
            request_id.clone(),
            profile.clone(),
            operation.clone(),
        ) {
            Ok(()) => {
                self.command_center_maintenance_pending = Some(PendingCommandCenterMaintenance {
                    request_id,
                    profile,
                    endpoint_instance_id,
                    authority_epoch,
                    operation,
                });
                self.command_center_maintenance_error = None;
            }
            Err(error) => {
                self.command_center_maintenance_pending = None;
                self.command_center_maintenance_error = Some(error);
            }
        }
    }

    fn request_command_center_maintenance_snapshot(&mut self) {
        self.request_command_center_maintenance(CommandCenterMaintenanceOperation::LoadSnapshot);
    }

    fn queue_command_center_maintenance_confirmation(
        &mut self,
        operation: CommandCenterMaintenanceOperation,
    ) {
        let Some(endpoint) = self.gateway_endpoint.as_ref() else {
            self.command_center_maintenance_error = Some("Hermes profile is unavailable".into());
            return;
        };
        if endpoint.profile_id.eq_ignore_ascii_case("all") {
            self.command_center_maintenance_error =
                Some("This action requires one Hermes profile".into());
            return;
        }
        if !matches!(
            &operation,
            CommandCenterMaintenanceOperation::ResetMemory { .. }
                | CommandCenterMaintenanceOperation::DebugShare
        ) {
            self.command_center_maintenance_error =
                Some("This Maintenance action does not use confirmation".into());
            return;
        }
        self.command_center_maintenance_confirmation = Some(CommandCenterMaintenanceConfirmation {
            profile: endpoint.profile_id.clone(),
            endpoint_instance_id: endpoint.instance_id.clone(),
            authority_epoch: endpoint.authority_epoch,
            operation,
        });
    }

    fn confirm_command_center_maintenance(&mut self) {
        let Some(confirmation) = self.command_center_maintenance_confirmation.take() else {
            return;
        };
        let current_owner = self.gateway_endpoint.as_ref().is_some_and(|endpoint| {
            endpoint.profile_id == confirmation.profile
                && endpoint.instance_id == confirmation.endpoint_instance_id
                && endpoint.authority_epoch == confirmation.authority_epoch
        });
        if !current_owner || !self.gateway_connected {
            self.command_center_maintenance_error = Some(
                "Hermes profile changed while the confirmation was open. Review the action again."
                    .into(),
            );
            return;
        }
        self.command_center_maintenance_share = None;
        self.command_center_maintenance_notice = None;
        self.request_command_center_maintenance(confirmation.operation);
    }

    fn poll_command_center_maintenance(&mut self, now: std::time::Instant) {
        let Some(name) = self.command_center_maintenance_action_name.clone() else {
            return;
        };
        let Some(next_poll) = self.command_center_maintenance_next_poll else {
            return;
        };
        if now < next_poll || self.command_center_maintenance_pending.is_some() {
            return;
        }
        let owner_matches = self.gateway_endpoint.as_ref().is_some_and(|endpoint| {
            self.command_center_maintenance_action_owner
                .as_ref()
                .is_some_and(|(profile, instance, epoch)| {
                    profile == &endpoint.profile_id
                        && instance == &endpoint.instance_id
                        && *epoch == endpoint.authority_epoch
                })
        });
        if !owner_matches || !self.gateway_connected {
            self.command_center_maintenance_next_poll = None;
            return;
        }
        if self.command_center_maintenance_action_polls >= 240 {
            self.command_center_maintenance_next_poll = None;
            self.command_center_maintenance_error =
                Some("Stopped polling after five minutes; the action may still be running.".into());
            return;
        }
        self.command_center_maintenance_action_polls += 1;
        self.request_command_center_maintenance_action_status(name);
    }

    fn show_command_center_maintenance_confirmation(&mut self, ctx: &egui::Context) {
        let Some(confirmation) = self.command_center_maintenance_confirmation.clone() else {
            return;
        };
        let mut cancel = false;
        let mut confirm = false;
        let (title, detail, button) = match confirmation.operation {
            CommandCenterMaintenanceOperation::DebugShare => (
                "Share diagnostic bundle?",
                "Hermes will upload a redacted diagnostic summary for the profile shown here. Continue only if you consent to that upload.",
                "Share diagnostics",
            ),
            CommandCenterMaintenanceOperation::ResetMemory { target } => {
                let file = match target {
                    CommandCenterMemoryResetTarget::Memory => "MEMORY.md",
                    CommandCenterMemoryResetTarget::User => "USER.md",
                };
                (
                    "Reset memory file?",
                    if target == CommandCenterMemoryResetTarget::Memory {
                        "This permanently deletes the selected profile's MEMORY.md file."
                    } else {
                        "This permanently deletes the selected profile's USER.md file."
                    },
                    file,
                )
            }
            _ => return,
        };
        egui::Window::new(title)
            .id(Id::NULL.with("command-center-maintenance-confirmation"))
            .order(egui::Order::Foreground)
            .collapsible(false)
            .resizable(false)
            .show(ctx, |ui| {
                ui.label(detail);
                ui.label(RichText::new(format!("Profile: {}", confirmation.profile)).strong());
                ui.horizontal(|ui| {
                    if ui.button("Cancel").clicked() {
                        cancel = true;
                    }
                    if ui.button(button).clicked() {
                        confirm = true;
                    }
                });
            });
        if cancel {
            self.command_center_maintenance_confirmation = None;
        } else if confirm {
            self.confirm_command_center_maintenance();
        }
    }

    fn queue_command_center_session_delete_confirmation(&mut self, session: SessionSummary) {
        let Some(endpoint) = self.gateway_endpoint.as_ref() else {
            self.status = "Hermes profile is unavailable".into();
            return;
        };
        let profile = session
            .profile
            .clone()
            .unwrap_or_else(|| endpoint.profile_id.clone());
        if profile.eq_ignore_ascii_case("all") {
            self.status = "Deleting a session requires a concrete Hermes profile".into();
            return;
        }
        self.command_center_delete_confirmation = Some(CommandCenterSessionDeleteConfirmation {
            session,
            profile,
            endpoint_instance_id: endpoint.instance_id.clone(),
            authority_epoch: endpoint.authority_epoch,
        });
    }

    fn confirm_command_center_session_delete(&mut self) {
        let Some(confirmation) = self.command_center_delete_confirmation.take() else {
            return;
        };
        let owner_matches = self.gateway_endpoint.as_ref().is_some_and(|endpoint| {
            endpoint.instance_id == confirmation.endpoint_instance_id
                && endpoint.authority_epoch == confirmation.authority_epoch
                && (confirmation.session.profile.is_some()
                    || endpoint.profile_id == confirmation.profile)
        });
        if !owner_matches || !self.gateway_connected {
            self.status =
                "Hermes profile changed while the delete confirmation was open. Review the session again."
                    .into();
            return;
        }
        self.start_session_delete(confirmation.session);
    }

    fn show_command_center_session_delete_confirmation(&mut self, ctx: &egui::Context) {
        let Some(confirmation) = self.command_center_delete_confirmation.clone() else {
            return;
        };
        let title = if confirmation.session.title.trim().is_empty() {
            "Untitled session"
        } else {
            confirmation.session.title.trim()
        };
        let mut cancel = false;
        let mut confirm = false;
        egui::Window::new("Delete session?")
            .id(Id::NULL.with("command-center-session-delete-confirmation"))
            .order(egui::Order::Foreground)
            .collapsible(false)
            .resizable(false)
            .show(ctx, |ui| {
                ui.label(format!(
                    "Permanently delete \"{title}\" ({})?",
                    confirmation.session.id
                ));
                ui.label(RichText::new(format!("Profile: {}", confirmation.profile)).strong());
                ui.horizontal(|ui| {
                    if ui
                        .button("Cancel")
                        .accessible_name("Cancel Command Center session delete")
                        .clicked()
                    {
                        cancel = true;
                    }
                    if ui
                        .button("Delete")
                        .accessible_name("Confirm Command Center session delete")
                        .clicked()
                    {
                        confirm = true;
                    }
                });
            });
        if cancel {
            self.command_center_delete_confirmation = None;
        } else if confirm {
            self.confirm_command_center_session_delete();
        }
    }

    fn apply_session_deleted_receipt(
        &mut self,
        request_id: String,
        session_id: String,
        profile: Option<String>,
        result: Result<(), String>,
    ) {
        let action_key = self.session_identity_key(&session_id, profile.as_deref());
        if self.pending_session_deletes.get(&action_key) != Some(&request_id) {
            return;
        }
        self.pending_session_deletes.remove(&action_key);
        match result {
            Ok(()) => {
                let lifecycle_profile = profile
                    .clone()
                    .or_else(|| {
                        self.gateway_endpoint
                            .as_ref()
                            .map(|endpoint| endpoint.profile_id.clone())
                    })
                    .unwrap_or_else(|| "default".into());
                self.record_project_session_lifecycle(&lifecycle_profile, &session_id, true);
                self.sessions
                    .retain(|session| session.id != session_id || session.profile != profile);
                self.archived_sessions
                    .retain(|session| session.id != session_id || session.profile != profile);
                self.command_palette_sessions
                    .retain(|session| session.id != session_id || session.profile != profile);
                self.session_search_results
                    .retain(|result| result.session_id != session_id || result.profile != profile);
                self.session_chat_views.remove(&action_key);
                self.session_chat_view_order
                    .retain(|candidate| candidate != &action_key);
                let pin_order_result = self
                    .gateway_endpoint
                    .as_ref()
                    .map(|endpoint| {
                        self.workspace.set_pinned_session_state(
                            &gateway_pin_order_scope(endpoint),
                            &session_id,
                            false,
                        )
                    })
                    .unwrap_or(Ok(()));
                self.broadcast_local_sessions_changed();
                self.status = match pin_order_result {
                    Ok(()) => "Session deleted".into(),
                    Err(error) => {
                        format!("Session deleted, but local pin order could not be saved: {error}")
                    }
                };
            }
            Err(error) => self.status = error,
        }
    }
    fn apply_session_export_loaded(
        &mut self,
        request_id: String,
        session_id: String,
        profile: Option<String>,
        result: Result<SessionExportTranscript, String>,
    ) {
        let action_key = self.session_identity_key(&session_id, profile.as_deref());
        if self.pending_session_exports.get(&action_key) != Some(&request_id) {
            return;
        }
        self.pending_session_exports.remove(&action_key);
        match result {
            Ok(transcript) => {
                let session = self
                    .sessions
                    .iter()
                    .chain(self.archived_sessions.iter())
                    .find(|row| row.id == session_id && row.profile == profile)
                    .cloned();
                let title = session
                    .as_ref()
                    .map(|row| row.title.trim())
                    .filter(|title| !title.is_empty());
                let filename = session_export_filename(&session_id, title);
                let export_dir = self.workspace.data_directory().join("exports");
                if let Err(error) = std::fs::create_dir_all(&export_dir) {
                    self.status = format!("Could not create session export directory: {error}");
                    return;
                }
                let payload = serde_json::json!({
                    "exported_at": "2026-11-18T00:00:00Z",
                    "session_id": transcript.resolved_session_id,
                    "title": title,
                    "session": session.as_ref().map(|row| serde_json::json!({
                        "id": row.id,
                        "profile": row.profile,
                        "title": row.title,
                        "preview": row.preview,
                        "message_count": row.message_count,
                        "source": row.source,
                        "started_at": row.started_at,
                        "last_active": row.last_active,
                        "pinned": row.pinned,
                        "unread": row.unread,
                        "archived": row.archived,
                    })),
                    "message_count": transcript.messages.len(),
                    "messages": transcript.messages,
                });
                let serialized = match serde_json::to_string_pretty(&payload) {
                    Ok(serialized) => serialized,
                    Err(error) => {
                        self.status = format!("Could not serialize session export: {error}");
                        return;
                    }
                };
                let target_path = export_dir.join(&filename);
                let temp_path = export_dir.join(format!(".{filename}.tmp"));
                if let Err(error) = std::fs::write(&temp_path, serialized)
                    .and_then(|()| std::fs::rename(&temp_path, &target_path))
                {
                    let _ = std::fs::remove_file(&temp_path);
                    self.status = format!("Could not write session export: {error}");
                    return;
                }
                self.last_exported_session_path = Some(target_path);
                self.status = format!("Session exported: {filename}");
            }
            Err(error) => self.status = error,
        }
    }

    fn request_command_center_system_action(&mut self, operation: CommandCenterSystemOperation) {
        if !self.gateway_connected {
            self.command_center_system_error = Some("Hermes gateway is unavailable".into());
            return;
        }
        let Some(endpoint) = self.gateway_endpoint.as_ref() else {
            self.command_center_system_error = Some("Hermes gateway profile is unavailable".into());
            return;
        };
        if endpoint.profile_id.eq_ignore_ascii_case("all") {
            self.command_center_system_error =
                Some("System actions require a concrete Hermes profile".into());
            return;
        }
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            self.command_center_system_error =
                Some("Hermes gateway HTTP worker is unavailable".into());
            return;
        };
        let request_id = operation_id("command-center-system-action");
        let profile = endpoint.profile_id.clone();
        let endpoint_instance_id = endpoint.instance_id.clone();
        let authority_epoch = endpoint.authority_epoch;
        match gateway.command_center_system_action(
            request_id.clone(),
            profile.clone(),
            operation.clone(),
        ) {
            Ok(()) => {
                self.command_center_system_action_pending =
                    Some(PendingCommandCenterSystemAction {
                        request_id,
                        profile,
                        endpoint_instance_id,
                        authority_epoch,
                        operation,
                    });
                self.command_center_system_error = None;
            }
            Err(error) => {
                self.command_center_system_action_pending = None;
                self.command_center_system_error = Some(error);
            }
        }
    }

    fn poll_command_center_system_action(&mut self, now: std::time::Instant) {
        let Some(name) = self.command_center_system_action_name.clone() else {
            return;
        };
        let Some(next_poll) = self.command_center_system_next_poll else {
            return;
        };
        if now < next_poll || self.command_center_system_action_pending.is_some() {
            return;
        }
        let owner_matches = self.gateway_endpoint.as_ref().is_some_and(|endpoint| {
            self.command_center_system_action_owner
                .as_ref()
                .is_some_and(|(profile, instance, epoch)| {
                    profile == &endpoint.profile_id
                        && instance == &endpoint.instance_id
                        && *epoch == endpoint.authority_epoch
                })
        });
        if !owner_matches || !self.gateway_connected {
            self.command_center_system_next_poll = None;
            return;
        }
        if self.command_center_system_action_polls >= 18 {
            self.command_center_system_next_poll = None;
            self.request_command_center_system();
            return;
        }
        self.command_center_system_action_polls += 1;
        self.request_command_center_system_action(CommandCenterSystemOperation::LoadActionStatus {
            name,
        });
    }

    fn request_command_center_maintenance_action_status(&mut self, name: String) {
        if self.command_center_maintenance_pending.is_some() {
            return;
        }
        self.request_command_center_maintenance(
            CommandCenterMaintenanceOperation::LoadActionStatus { name },
        );
    }

    fn request_command_center_system(&mut self) {
        if !self.gateway_connected {
            self.command_center_system_error = Some("Hermes gateway is unavailable".into());
            return;
        }
        let Some(endpoint) = self.gateway_endpoint.as_ref() else {
            self.command_center_system_error = Some("Hermes gateway profile is unavailable".into());
            return;
        };
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            self.command_center_system_error =
                Some("Hermes gateway HTTP worker is unavailable".into());
            return;
        };
        self.command_center_system_generation =
            self.command_center_system_generation.saturating_add(1);
        let request_id = operation_id("command-center-system");
        let profile = endpoint.profile_id.clone();
        let endpoint_instance_id = endpoint.instance_id.clone();
        let authority_epoch = endpoint.authority_epoch;
        let generation = self.command_center_system_generation;
        let log_file = self.command_center_system_log_file.clone();
        let log_level = self.command_center_system_log_level.clone();
        let result = gateway.load_command_center_system(
            request_id.clone(),
            Some(profile.clone()),
            log_file.clone(),
            log_level.clone(),
        );
        match result {
            Ok(()) => {
                self.command_center_system_pending = Some(PendingCommandCenterSystem {
                    request_id,
                    profile,
                    endpoint_instance_id,
                    authority_epoch,
                    generation,
                    log_file,
                    log_level,
                });
                self.command_center_system_error = None;
            }
            Err(error) => {
                self.command_center_system_pending = None;
                self.command_center_system_error = Some(error);
            }
        }
    }

    fn request_command_center_usage(&mut self) {
        if !self.gateway_connected {
            self.command_center_usage_error = Some("Hermes gateway is unavailable".into());
            return;
        }
        let Some(endpoint) = self.gateway_endpoint.as_ref() else {
            self.command_center_usage_error = Some("Hermes gateway profile is unavailable".into());
            return;
        };
        let Some(gateway) = self.gateway_discovery.as_ref() else {
            self.command_center_usage_error =
                Some("Hermes gateway HTTP worker is unavailable".into());
            return;
        };
        self.command_center_usage_generation =
            self.command_center_usage_generation.saturating_add(1);
        let request_id = operation_id("command-center-usage");
        let profile = endpoint.profile_id.clone();
        let endpoint_instance_id = endpoint.instance_id.clone();
        let authority_epoch = endpoint.authority_epoch;
        let generation = self.command_center_usage_generation;
        let period_days = self.command_center_usage_period_days;
        match gateway.load_command_center_usage(
            request_id.clone(),
            Some(profile.clone()),
            period_days,
        ) {
            Ok(()) => {
                self.command_center_usage_pending = Some(PendingCommandCenterUsage {
                    request_id,
                    profile,
                    endpoint_instance_id,
                    authority_epoch,
                    generation,
                    period_days,
                });
                self.command_center_usage_error = None;
            }
            Err(error) => {
                self.command_center_usage_pending = None;
                self.command_center_usage_error = Some(error);
            }
        }
    }

    fn command_center_maintenance_content(&mut self, ui: &mut Ui) {
        let owner_matches = self.gateway_endpoint.as_ref().is_some_and(|endpoint| {
            self.command_center_maintenance
                .as_ref()
                .is_some_and(|cached| {
                    cached.profile == endpoint.profile_id
                        && cached.endpoint_instance_id == endpoint.instance_id
                        && cached.authority_epoch == endpoint.authority_epoch
                })
        });
        let cached = owner_matches
            .then(|| self.command_center_maintenance.clone())
            .flatten();
        let connected = self.gateway_connected
            && self
                .gateway_endpoint
                .as_ref()
                .is_some_and(|endpoint| !endpoint.profile_id.eq_ignore_ascii_case("all"));
        let busy = self.command_center_maintenance_pending.is_some();
        let action_running = self
            .command_center_maintenance_action_status
            .as_ref()
            .is_some_and(|status| status.running);
        let mut requested_action = None;
        let mut pause_curator = None;
        let mut confirmation = None;
        ui.horizontal(|ui| {
            if ui
                .add_enabled(connected && !busy, egui::Button::new("Refresh"))
                .clicked()
            {
                requested_action = Some(CommandCenterMaintenanceOperation::LoadSnapshot);
            }
            if busy {
                ui.label(RichText::new("Working…").color(MUTED));
            }
        });
        if !connected {
            ui.label(
                RichText::new("Connect to one Hermes profile to use Maintenance.").color(MUTED),
            );
        }
        if let Some(notice) = self.command_center_maintenance_notice.as_deref() {
            ui.label(RichText::new(notice).color(Color32::LIGHT_GREEN));
        }
        if let Some(error) = self.command_center_maintenance_error.as_deref() {
            ui.colored_label(Color32::LIGHT_RED, error);
        }
        ui.separator();
        ui.label(RichText::new("Operations").small().strong().color(MUTED));
        ui.horizontal_wrapped(|ui| {
            for (label, action) in [
                ("Doctor", CommandCenterMaintenanceAction::Doctor),
                (
                    "Security audit",
                    CommandCenterMaintenanceAction::SecurityAudit,
                ),
                ("Backup", CommandCenterMaintenanceAction::Backup),
            ] {
                if ui
                    .add_enabled(
                        connected && !busy && !action_running,
                        egui::Button::new(format!("Run {label}")),
                    )
                    .clicked()
                {
                    requested_action =
                        Some(CommandCenterMaintenanceOperation::StartAction { action });
                }
            }
            if ui
                .add_enabled(connected && !busy, egui::Button::new("Share debug bundle…"))
                .clicked()
            {
                confirmation = Some(CommandCenterMaintenanceOperation::DebugShare);
            }
        });
        if let Some(status) = self.command_center_maintenance_action_status.as_ref() {
            ui.horizontal(|ui| {
                ui.label(RichText::new(format!("{} log", status.name)).strong());
                ui.label(if status.running {
                    "Running"
                } else {
                    "Finished"
                });
                if let Some(code) = status.exit_code {
                    ui.label(format!("Exit code {code}"));
                }
            });
            egui::ScrollArea::vertical()
                .id_salt("command-center-maintenance-action-log")
                .max_height(180.0)
                .show(ui, |ui| {
                    if status.lines.is_empty() {
                        ui.label(RichText::new("No output yet.").color(MUTED));
                    } else {
                        for line in &status.lines {
                            ui.add(
                                egui::Label::new(RichText::new(line).monospace()).selectable(true),
                            );
                        }
                    }
                });
        }
        if let Some(share) = self.command_center_maintenance_share.as_ref() {
            if !share.urls.is_empty() {
                ui.label(
                    RichText::new("Debug share links")
                        .small()
                        .strong()
                        .color(MUTED),
                );
                for (name, url) in &share.urls {
                    ui.horizontal(|ui| {
                        ui.add(egui::Label::new(format!("{name}: {url}")).truncate());
                        if ui.button("Copy").clicked() {
                            ui.ctx().copy_text(url.clone());
                            self.command_center_maintenance_notice = Some("Link copied".into());
                        }
                    });
                }
            }
            for (name, error) in &share.failures {
                ui.colored_label(Color32::LIGHT_RED, format!("{name}: {error}"));
            }
        }

        ui.separator();
        ui.label(RichText::new("Curator").small().strong().color(MUTED));
        match cached
            .as_ref()
            .and_then(|snapshot| snapshot.snapshot.curator.as_ref().ok())
        {
            Some(curator) => {
                ui.horizontal_wrapped(|ui| {
                    let state = if !curator.enabled {
                        "Disabled"
                    } else if curator.paused {
                        "Paused"
                    } else {
                        "Active"
                    };
                    ui.strong(state);
                    ui.label(format!(
                        "Last run: {}",
                        curator.last_run_at.as_deref().unwrap_or("Never")
                    ));
                    if let Some(hours) = curator.interval_hours {
                        ui.label(format!("Interval: {hours:.1} hours"));
                    }
                    if curator.enabled
                        && ui
                            .add_enabled(
                                !busy,
                                egui::Button::new(if curator.paused { "Resume" } else { "Pause" }),
                            )
                            .clicked()
                    {
                        pause_curator = Some(!curator.paused);
                    }
                    if ui
                        .add_enabled(
                            connected && !busy && !action_running,
                            egui::Button::new("Run now"),
                        )
                        .clicked()
                    {
                        requested_action = Some(CommandCenterMaintenanceOperation::StartAction {
                            action: CommandCenterMaintenanceAction::Curator,
                        });
                    }
                });
            }
            None if busy => {
                ui.label(RichText::new("Loading curator status…").color(MUTED));
            }
            None => {
                let error = cached
                    .as_ref()
                    .and_then(|snapshot| snapshot.snapshot.curator.as_ref().err())
                    .map(String::as_str)
                    .unwrap_or("Curator status has not been loaded.");
                ui.colored_label(Color32::LIGHT_RED, error);
                if ui
                    .add_enabled(connected && !busy, egui::Button::new("Retry curator"))
                    .clicked()
                {
                    requested_action = Some(CommandCenterMaintenanceOperation::LoadSnapshot);
                }
            }
        }

        ui.separator();
        ui.label(
            RichText::new("Memory providers and files")
                .small()
                .strong()
                .color(MUTED),
        );
        match cached
            .as_ref()
            .and_then(|snapshot| snapshot.snapshot.memory.as_ref().ok())
        {
            Some(memory) => {
                ui.label(format!("Active provider: {}", memory.active));
                if memory.providers.is_empty() {
                    ui.label(RichText::new("No providers reported.").color(MUTED));
                }
                for provider in &memory.providers {
                    ui.horizontal_wrapped(|ui| {
                        ui.strong(&provider.name);
                        ui.label(format!(
                            "{} · {}",
                            provider.status,
                            if provider.available {
                                "available"
                            } else {
                                "unavailable"
                            }
                        ));
                        if !provider.description.is_empty() {
                            ui.label(RichText::new(&provider.description).color(MUTED));
                        }
                    });
                }
                for (label, bytes, target) in [
                    (
                        "MEMORY.md",
                        memory.builtin_files.memory,
                        CommandCenterMemoryResetTarget::Memory,
                    ),
                    (
                        "USER.md",
                        memory.builtin_files.user,
                        CommandCenterMemoryResetTarget::User,
                    ),
                ] {
                    ui.horizontal(|ui| {
                        ui.label(format!("{label} · {} bytes", bytes));
                        if ui
                            .add_enabled(
                                connected && !busy && bytes > 0,
                                egui::Button::new(format!("Reset {label}")),
                            )
                            .clicked()
                        {
                            confirmation =
                                Some(CommandCenterMaintenanceOperation::ResetMemory { target });
                        }
                    });
                }
            }
            None if busy => {
                ui.label(RichText::new("Loading memory status…").color(MUTED));
            }
            None => {
                let error = cached
                    .as_ref()
                    .and_then(|snapshot| snapshot.snapshot.memory.as_ref().err())
                    .map(String::as_str)
                    .unwrap_or("Memory status has not been loaded.");
                ui.colored_label(Color32::LIGHT_RED, error);
                if ui
                    .add_enabled(connected && !busy, egui::Button::new("Retry memory status"))
                    .clicked()
                {
                    requested_action = Some(CommandCenterMaintenanceOperation::LoadSnapshot);
                }
            }
        }
        if let Some(operation) = requested_action {
            if let CommandCenterMaintenanceOperation::StartAction { .. } = operation {
                self.command_center_maintenance_action_status = None;
                self.command_center_maintenance_action_name = None;
                self.command_center_maintenance_next_poll = None;
            }
            self.request_command_center_maintenance(operation);
        }
        if let Some(paused) = pause_curator {
            self.request_command_center_maintenance(
                CommandCenterMaintenanceOperation::SetCuratorPaused { paused },
            );
        }
        if let Some(operation) = confirmation {
            self.queue_command_center_maintenance_confirmation(operation);
        }
    }

    fn update_command_center_search_debounce(
        &mut self,
        now: std::time::Instant,
    ) -> Option<std::time::Duration> {
        const DEBOUNCE: std::time::Duration = std::time::Duration::from_millis(180);
        let query = self.command_center_query.trim();
        if query == self.command_center_debounced_query {
            self.command_center_query_changed_at = None;
            return None;
        }
        let changed_at = *self.command_center_query_changed_at.get_or_insert(now);
        let elapsed = now.saturating_duration_since(changed_at);
        if elapsed >= DEBOUNCE {
            self.command_center_debounced_query = query.to_owned();
            self.command_center_query_changed_at = None;
            None
        } else {
            Some(DEBOUNCE - elapsed)
        }
    }

    fn command_center_content(&mut self, ui: &mut Ui) {
        let refresh_hotkey =
            ui.input(|input| input.key_pressed(egui::Key::R) && !input.modifiers.any());
        if refresh_hotkey && !ui.ctx().egui_wants_keyboard_input() {
            match self.command_center_section {
                CommandCenterSection::System => self.request_command_center_system(),
                CommandCenterSection::Usage => self.request_command_center_usage(),
                CommandCenterSection::Maintenance => {
                    self.request_command_center_maintenance_snapshot()
                }
                _ => {}
            }
        }
        let mut load_system = false;
        let mut load_usage = false;
        let mut load_maintenance = false;
        let content_rect = ui.available_rect_before_wrap().intersect(ui.clip_rect());
        let wide_viewport = ui.ctx().viewport_rect().width() >= 760.0;
        let rail_width = if wide_viewport {
            208.0
        } else {
            content_rect.width()
        };
        let rail_height = if wide_viewport {
            content_rect.height()
        } else {
            34.0
        };
        let rail_rect = Rect::from_min_size(content_rect.min, egui::vec2(rail_width, rail_height));
        let main_rect = if wide_viewport {
            Rect::from_min_max(
                egui::pos2(rail_rect.max.x, content_rect.min.y),
                content_rect.max,
            )
        } else {
            Rect::from_min_max(
                egui::pos2(content_rect.min.x, rail_rect.max.y),
                content_rect.max,
            )
        };
        let main_rect = Rect::from_min_max(
            egui::pos2(main_rect.min.x + 40.0, main_rect.min.y),
            egui::pos2(main_rect.max.x - 40.0, main_rect.max.y),
        );
        let mut rail_ui = ui.new_child(
            egui::UiBuilder::new()
                .max_rect(rail_rect)
                .layout(Layout::top_down(Align::Min)),
        );
        rail_ui.set_clip_rect(rail_rect);
        rail_ui.painter().rect_filled(rail_rect, 0.0, PANEL_ALT);
        let mut main_ui = ui.new_child(
            egui::UiBuilder::new()
                .max_rect(main_rect)
                .layout(Layout::top_down(Align::Min)),
        );
        main_ui.set_clip_rect(main_rect);

        if wide_viewport {
            rail_ui.add_space(8.0);
            for (section, label) in CommandCenterSection::ALL {
                let selected = self.command_center_section == section;
                let response = rail_ui
                    .add_sized(
                        [rail_ui.available_width(), 28.0],
                        egui::Button::new(" ")
                            .left_text(RichText::new(format!("   {label}")))
                            .selected(selected)
                            .frame(selected),
                    )
                    .accessible_name(format!("Command Center section: {label}"));
                paint_command_center_section_icon(
                    &rail_ui,
                    response.rect,
                    section,
                    if selected { TEXT } else { MUTED },
                );
                if response.clicked() {
                    self.command_center_section = section;
                    load_system |= section == CommandCenterSection::System;
                    load_usage |= section == CommandCenterSection::Usage;
                    load_maintenance |= section == CommandCenterSection::Maintenance;
                }
            }
            let divider = Rect::from_min_max(
                egui::pos2(rail_rect.max.x - 1.0, rail_rect.min.y),
                rail_rect.max,
            );
            ui.painter().rect_filled(divider, 0.0, BORDER);
        } else {
            let selected_label = CommandCenterSection::ALL
                .iter()
                .find_map(|(section, label)| {
                    (*section == self.command_center_section).then_some(*label)
                })
                .unwrap_or("Sessions");
            let picker = egui::ComboBox::from_id_salt("command-center-section-picker")
                .selected_text(selected_label)
                .width((rail_rect.width() - 16.0).max(100.0))
                .show_ui(&mut rail_ui, |ui| {
                    for (section, label) in CommandCenterSection::ALL {
                        let response = ui
                            .selectable_value(&mut self.command_center_section, section, label)
                            .accessible_name(format!("Command Center section: {label}"));
                        if response.changed() {
                            load_system |= section == CommandCenterSection::System;
                            load_usage |= section == CommandCenterSection::Usage;
                            load_maintenance |= section == CommandCenterSection::Maintenance;
                        }
                    }
                });
            picker.response.accessible_name("Command Center sections");
        }
        if load_system {
            self.request_command_center_system();
        }
        if load_usage {
            self.request_command_center_usage();
        }
        if load_maintenance {
            self.request_command_center_maintenance_snapshot();
        }

        let ui = &mut main_ui;
        ui.add_space(8.0);
        ui.horizontal(|ui| {
            ui.label(RichText::new("Command Center").small().color(MUTED))
                .accessible_name("Command Center breadcrumb root");
            ui.label(RichText::new("›").small().color(MUTED));
            let section_label = CommandCenterSection::ALL
                .iter()
                .find_map(|(section, label)| {
                    (*section == self.command_center_section).then_some(*label)
                })
                .unwrap_or("Sessions");
            ui.label(RichText::new(section_label).small())
                .accessible_name(format!("Command Center current section: {section_label}"));

            if self.command_center_section == CommandCenterSection::Sessions {
                let max_search_width = ui.ctx().viewport_rect().width() * 0.4;
                let search_width = ui.available_width().min(max_search_width).max(80.0);
                let search = ui
                    .with_layout(Layout::right_to_left(Align::Center), |ui| {
                        ui.add_sized(
                            [search_width, 26.0],
                            egui::TextEdit::singleline(&mut self.command_center_query)
                                .hint_text("Search sessions"),
                        )
                    })
                    .inner
                    .accessible_name("Search Command Center sessions");
                if search.changed() {
                    self.command_center_query_changed_at = Some(std::time::Instant::now());
                }
            }
        });
        ui.add_space(10.0);

        match self.command_center_section {
            CommandCenterSection::Sessions => {
                if let Some(wait) =
                    self.update_command_center_search_debounce(std::time::Instant::now())
                {
                    ui.ctx().request_repaint_after(wait);
                }

                let query = self.command_center_debounced_query.trim().to_lowercase();
                let mut sessions = self
                    .sessions
                    .iter()
                    .filter(|session| !session.archived)
                    .filter(|session| command_center_session_matches(session, &query))
                    .cloned()
                    .collect::<Vec<_>>();
                sessions.sort_by(|left, right| {
                    let left_time = command_center_session_recency(left);
                    let right_time = command_center_session_recency(right);
                    right_time.total_cmp(&left_time)
                });

                if let Some(error) = self.session_list_error.as_deref() {
                    ui.colored_label(Color32::from_rgb(220, 150, 100), error);
                }
                if sessions.is_empty() {
                    let message = if !query.is_empty() {
                        "No sessions match your search."
                    } else if self.gateway_connected {
                        "No sessions yet."
                    } else {
                        "Connect to Hermes to load sessions."
                    };
                    ui.label(RichText::new(message).color(MUTED));
                    return;
                }

                let mut pin_update = None;
                let mut export_request = None;
                let mut delete_confirmation = None;
                let mut focused_session_actions = None;
                let has_more_sessions = query.is_empty()
                    && self.session_profiles_truncated.values().any(|value| *value);
                let list_height = ui.available_height();
                egui::ScrollArea::vertical()
                    .id_salt("command-center-sessions")
                    .max_height(list_height)
                    .show(ui, |ui| {
                        for session in sessions {
                            let action_key = self.session_summary_identity_key(&session);
                            let row_rect = Rect::from_min_size(
                                ui.cursor().min,
                                egui::vec2(ui.available_width(), 42.0),
                            );
                            let row_hovered = ui
                                .ctx()
                                .pointer_hover_pos()
                                .is_some_and(|position| row_rect.contains(position));
                            let reveal_actions = row_hovered
                                || self.command_center_focused_session_actions.as_deref()
                                    == Some(action_key.as_str());
                            let pin_pending = self.pending_session_pins.contains_key(&action_key);
                            let export_pending =
                                self.pending_session_exports.contains_key(&action_key);
                            let delete_pending =
                                self.pending_session_deletes.contains_key(&action_key);
                            let pinned = session.pinned;
                            let pin_label = if pinned {
                                format!("Unpin Command Center session {}", session.id)
                            } else {
                                format!("Pin Command Center session {}", session.id)
                            };
                            ui.horizontal(|ui| {
                                let action_width = 3.0 * 24.0 + 2.0 * ui.spacing().item_spacing.x;
                                let title_width =
                                    (ui.available_width() - action_width - 24.0).max(80.0);
                                let mut title_focused = false;
                                ui.allocate_ui_with_layout(
                                    egui::vec2(title_width, 38.0),
                                    Layout::top_down(Align::Min),
                                    |ui| {
                                        let title = command_center_session_title(&session);
                                        let open = ui
                                            .add_sized(
                                                [title_width, 22.0],
                                                egui::Button::new(" ")
                                                    .left_text(RichText::new(title).strong())
                                                    .frame(false),
                                            )
                                            .accessible_name(format!("Open session: {title}"));
                                        title_focused = open.has_focus();
                                        if open.clicked() {
                                            self.execute_registered_action(
                                                RegisteredUiAction::OpenSession {
                                                    session_id: session.id.clone(),
                                                    profile: session.profile.clone(),
                                                },
                                            )
                                            .unwrap_or_else(|error| self.status = error);
                                        }
                                        let timestamp =
                                            command_center_session_display_time(&session);
                                        ui.label(RichText::new(timestamp).small().color(MUTED));
                                    },
                                );
                                let pin = ui
                                    .add_enabled(
                                        self.gateway_connected && !pin_pending && !delete_pending,
                                        egui::Button::new(
                                            RichText::new(if pinned { "★" } else { "☆" }).color(
                                                if reveal_actions {
                                                    ui.visuals().text_color()
                                                } else {
                                                    Color32::TRANSPARENT
                                                },
                                            ),
                                        )
                                        .min_size(egui::vec2(24.0, 22.0))
                                        .frame_when_inactive(false),
                                    )
                                    .accessible_name(pin_label)
                                    .on_hover_text(if pinned {
                                        "Unpin session"
                                    } else {
                                        "Pin session"
                                    });
                                if pin.clicked() {
                                    pin_update = Some((session.clone(), !pinned));
                                }
                                let export = ui
                                    .add_enabled(
                                        self.gateway_connected
                                            && !export_pending
                                            && !delete_pending,
                                        egui::Button::new(RichText::new("⇩").color(
                                            if reveal_actions {
                                                ui.visuals().text_color()
                                            } else {
                                                Color32::TRANSPARENT
                                            },
                                        ))
                                        .min_size(egui::vec2(24.0, 22.0))
                                        .frame_when_inactive(false),
                                    )
                                    .accessible_name(format!(
                                        "Export Command Center session {}",
                                        session.id
                                    ))
                                    .on_hover_text("Export session");
                                if export.clicked() {
                                    export_request = Some(session.clone());
                                }
                                let delete = ui
                                    .add_enabled(
                                        self.gateway_connected && !delete_pending,
                                        egui::Button::new(RichText::new("×").color(
                                            if reveal_actions {
                                                ui.visuals().text_color()
                                            } else {
                                                Color32::TRANSPARENT
                                            },
                                        ))
                                        .min_size(egui::vec2(24.0, 22.0))
                                        .frame_when_inactive(false),
                                    )
                                    .accessible_name(format!(
                                        "Delete Command Center session {}",
                                        session.id
                                    ))
                                    .on_hover_text("Delete session");
                                if delete.clicked() {
                                    delete_confirmation = Some(session.clone());
                                }
                                if title_focused
                                    || pin.has_focus()
                                    || export.has_focus()
                                    || delete.has_focus()
                                {
                                    focused_session_actions = Some(action_key.clone());
                                }
                            });
                            ui.add_space(6.0);
                        }
                    });
                if self.command_center_focused_session_actions != focused_session_actions {
                    self.command_center_focused_session_actions = focused_session_actions;
                    ui.ctx().request_repaint();
                }
                if has_more_sessions
                    && ui
                        .add_enabled(
                            self.gateway_connected && self.session_list_refresh_pending.is_none(),
                            egui::Button::new("Load more (+50)"),
                        )
                        .accessible_name("Load more Command Center sessions")
                        .clicked()
                {
                    self.session_list_limit = (self.session_list_limit + 50).min(2_000);
                    self.request_session_list_refresh();
                }
                if let Some((session, pinned)) = pin_update {
                    self.start_session_pin_update(session, pinned);
                }
                if let Some(session) = export_request {
                    self.start_session_export(session);
                }
                if let Some(session) = delete_confirmation {
                    self.queue_command_center_session_delete_confirmation(session);
                }
            }
            CommandCenterSection::System => {
                let mut refresh = false;
                ui.horizontal_wrapped(|ui| {
                    ui.label("Recent logs");
                    for file in ["agent", "errors", "gateway", "desktop"] {
                        if ui
                            .selectable_value(
                                &mut self.command_center_system_log_file,
                                file.to_owned(),
                                file,
                            )
                            .accessible_name(format!("Command Center log file: {file}"))
                            .clicked()
                        {
                            refresh = true;
                        }
                    }
                    for level in ["ALL", "INFO", "WARNING", "ERROR"] {
                        let label = if level == "ALL" {
                            "all"
                        } else {
                            &level.to_lowercase()
                        };
                        if ui
                            .selectable_value(
                                &mut self.command_center_system_log_level,
                                level.to_owned(),
                                label,
                            )
                            .accessible_name(format!("Command Center log level: {level}"))
                            .clicked()
                        {
                            refresh = true;
                        }
                    }
                    if ui
                        .button("Refresh")
                        .accessible_name("Refresh Command Center system status and logs")
                        .clicked()
                    {
                        refresh = true;
                    }
                });
                ui.add(
                    egui::TextEdit::singleline(&mut self.command_center_system_log_query)
                        .hint_text("Search recent logs")
                        .desired_width(f32::INFINITY),
                )
                .accessible_name("Search Command Center logs");
                if refresh {
                    self.request_command_center_system();
                }

                let owner = self.gateway_endpoint.as_ref().map(|endpoint| {
                    (
                        endpoint.profile_id.as_str(),
                        endpoint.instance_id.as_str(),
                        endpoint.authority_epoch,
                    )
                });
                let cached = self
                    .command_center_system
                    .as_ref()
                    .filter(|cached| {
                        owner.is_some_and(|(profile, instance_id, epoch)| {
                            cached.profile == profile
                                && cached.endpoint_instance_id == instance_id
                                && cached.authority_epoch == epoch
                        })
                    })
                    .cloned();
                if let Some(cached) = cached.as_ref() {
                    let mut requested_system_action = None;
                    let system_action_busy = self.command_center_system_action_pending.is_some()
                        || self
                            .command_center_system_action_status
                            .as_ref()
                            .is_some_and(|status| status.running);
                    let concrete_connected = self.gateway_connected
                        && self.gateway_endpoint.as_ref().is_some_and(|endpoint| {
                            !endpoint.profile_id.eq_ignore_ascii_case("all")
                        });
                    ui.group(|ui| {
                        ui.horizontal_wrapped(|ui| {
                            let running = cached.snapshot.status.gateway_running;
                            let color = if running {
                                Color32::from_rgb(72, 188, 126)
                            } else {
                                Color32::from_rgb(227, 169, 79)
                            };
                            ui.colored_label(color, "●");
                            ui.strong(if running {
                                "Gateway running"
                            } else {
                                "Gateway stopped"
                            });
                            if ui
                                .add_enabled(
                                    concrete_connected && !system_action_busy,
                                    egui::Button::new("Restart gateway"),
                                )
                                .accessible_name("Restart Command Center gateway")
                                .clicked()
                            {
                                requested_system_action =
                                    Some(CommandCenterSystemAction::RestartGateway);
                            }
                            if ui
                                .add_enabled(
                                    concrete_connected && !system_action_busy,
                                    egui::Button::new("Update Hermes"),
                                )
                                .accessible_name("Update Command Center Hermes")
                                .clicked()
                            {
                                requested_system_action =
                                    Some(CommandCenterSystemAction::UpdateHermes);
                            }
                        });
                        ui.label(format!(
                            "Hermes {} · {} active sessions",
                            cached.snapshot.status.version, cached.snapshot.status.active_sessions
                        ));
                        if let Some(action_status) =
                            self.command_center_system_action_status.as_ref()
                        {
                            let state_label = if action_status.running {
                                "Running"
                            } else if action_status.exit_code == Some(0) {
                                "Done"
                            } else {
                                "Failed"
                            };
                            ui.label(
                                RichText::new(format!("{} · {state_label}", action_status.name))
                                    .color(MUTED),
                            );
                        }
                        if let Some(age) = cached.snapshot.status.gateway_heartbeat_stale_s {
                            ui.colored_label(
                                Color32::LIGHT_RED,
                                format!("Gateway heartbeat is stale ({age:.0}s)"),
                            );
                        }
                        if let Some(reason) = cached.snapshot.status.gateway_exit_reason.as_deref()
                        {
                            if !reason.trim().is_empty() {
                                ui.label(format!("Gateway exit reason: {reason}"));
                            }
                        }
                    });
                    if let Some(action) = requested_system_action {
                        self.command_center_system_action_status = None;
                        self.command_center_system_action_name = None;
                        self.command_center_system_next_poll = None;
                        self.request_command_center_system_action(
                            CommandCenterSystemOperation::StartAction { action },
                        );
                    }
                    let logs_match = cached.log_file == self.command_center_system_log_file
                        && cached.log_level == self.command_center_system_log_level;
                    if logs_match {
                        let query = self.command_center_system_log_query.trim().to_lowercase();
                        let visible_lines = cached
                            .snapshot
                            .logs
                            .lines
                            .iter()
                            .filter(|line| query.is_empty() || line.to_lowercase().contains(&query))
                            .collect::<Vec<_>>();
                        ui.label(format!(
                            "{} log lines · {} matches",
                            cached.snapshot.logs.lines.len(),
                            visible_lines.len()
                        ));
                        egui::ScrollArea::vertical()
                            .id_salt("command-center-system-logs")
                            .max_height(420.0)
                            .show(ui, |ui| {
                                for line in visible_lines {
                                    ui.monospace(line);
                                }
                            });
                    } else if self.command_center_system_pending.is_some() {
                        ui.label(RichText::new("Loading selected log filter…").color(MUTED));
                    }
                } else if self.command_center_system_pending.is_some() {
                    ui.label(RichText::new("Loading Hermes system status…").color(MUTED));
                } else if self.command_center_system_error.is_none() {
                    ui.label(RichText::new("System status has not been loaded.").color(MUTED));
                }
                if let Some(error) = self.command_center_system_error.as_deref() {
                    ui.colored_label(
                        Color32::LIGHT_RED,
                        format!("System data unavailable: {error}"),
                    );
                }
            }
            CommandCenterSection::Usage => {
                let mut period_changed = false;
                ui.horizontal_wrapped(|ui| {
                    ui.label("Usage period");
                    for period in [7, 30, 90] {
                        if ui
                            .selectable_value(
                                &mut self.command_center_usage_period_days,
                                period,
                                format!("{period} days"),
                            )
                            .accessible_name(format!("Command Center usage period: {period} days"))
                            .clicked()
                        {
                            period_changed = true;
                        }
                    }
                    if ui
                        .button("Refresh")
                        .accessible_name("Refresh Command Center usage analytics")
                        .clicked()
                    {
                        period_changed = true;
                    }
                });
                if period_changed {
                    self.request_command_center_usage();
                }

                let owner = self.gateway_endpoint.as_ref().map(|endpoint| {
                    (
                        endpoint.profile_id.as_str(),
                        endpoint.instance_id.as_str(),
                        endpoint.authority_epoch,
                    )
                });
                let cached = self
                    .command_center_usage
                    .as_ref()
                    .filter(|cached| {
                        owner.is_some_and(|(profile, instance_id, epoch)| {
                            cached.profile == profile
                                && cached.endpoint_instance_id == instance_id
                                && cached.authority_epoch == epoch
                        })
                    })
                    .cloned();
                let has_cached_usage = cached.is_some();
                if let Some(cached) = cached.as_ref() {
                    let totals = &cached.snapshot.totals;
                    ui.horizontal_wrapped(|ui| {
                        usage_stat(ui, "Sessions", format_compact_count(totals.total_sessions));
                        usage_stat(
                            ui,
                            "API calls",
                            format_optional_compact_count(totals.total_api_calls),
                        );
                        let tokens = format!(
                            "{} / {}",
                            format_optional_compact_count(totals.total_input),
                            format_optional_compact_count(totals.total_output)
                        );
                        usage_stat(ui, "Input / output tokens", tokens);
                    });
                    ui.separator();
                    ui.horizontal(|ui| {
                        ui.label(RichText::new("Daily tokens").strong());
                        ui.add_space(12.0);
                        ui.colored_label(Color32::from_rgb(98, 150, 235), "■ Input");
                        ui.colored_label(Color32::from_rgb(92, 185, 132), "■ Output");
                    });
                    if cached.snapshot.daily.is_empty() {
                        ui.label(RichText::new("No daily activity").color(MUTED));
                    } else {
                        let max_tokens = cached
                            .snapshot
                            .daily
                            .iter()
                            .map(|day| day.input_tokens.saturating_add(day.output_tokens))
                            .max()
                            .unwrap_or(1)
                            .max(1) as f64;
                        let chart_height = 96.0;
                        let available = ui.available_width().max(80.0);
                        let (rect, _) = ui.allocate_exact_size(
                            egui::vec2(available, chart_height + 26.0),
                            egui::Sense::hover(),
                        );
                        let painter = ui.painter_at(rect);
                        let bar_width = rect.width() / cached.snapshot.daily.len() as f32;
                        for (index, day) in cached.snapshot.daily.iter().enumerate() {
                            let x0 = rect.left() + index as f32 * bar_width;
                            let input_h = ((day.input_tokens as f64 / max_tokens)
                                * chart_height as f64)
                                as f32;
                            let output_h = ((day.output_tokens as f64 / max_tokens)
                                * chart_height as f64)
                                as f32;
                            let input_rect = egui::Rect::from_min_max(
                                egui::pos2(x0, rect.bottom() - 26.0 - input_h),
                                egui::pos2(x0 + bar_width.max(1.0), rect.bottom() - 26.0),
                            );
                            let output_rect = egui::Rect::from_min_max(
                                egui::pos2(x0, rect.bottom() - 26.0 - input_h - output_h),
                                egui::pos2(x0 + bar_width.max(1.0), rect.bottom() - 26.0 - input_h),
                            );
                            if day.input_tokens > 0 {
                                painter.rect_filled(
                                    input_rect,
                                    1.0,
                                    Color32::from_rgb(98, 150, 235),
                                );
                            }
                            if day.output_tokens > 0 {
                                painter.rect_filled(
                                    output_rect,
                                    1.0,
                                    Color32::from_rgb(92, 185, 132),
                                );
                            }
                            if day.input_tokens > 0 || day.output_tokens > 0 {
                                ui.interact(
                                    egui::Rect::from_min_max(
                                        egui::pos2(x0, rect.top()),
                                        egui::pos2(x0 + bar_width.max(1.0), rect.bottom() - 20.0),
                                    ),
                                    ui.scope_id().with(("command-center-usage-day", &day.day)),
                                    egui::Sense::hover(),
                                )
                                .on_hover_text(format!(
                                    "{} · in {} · out {}",
                                    day.day,
                                    format_compact_count(day.input_tokens),
                                    format_compact_count(day.output_tokens)
                                ));
                            }
                        }
                        ui.horizontal(|ui| {
                            if let Some(first) = cached.snapshot.daily.first() {
                                ui.label(RichText::new(&first.day).small().color(MUTED));
                            }
                            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                                if let Some(last) = cached.snapshot.daily.last() {
                                    ui.label(RichText::new(&last.day).small().color(MUTED));
                                }
                            });
                        });
                    }
                    ui.separator();
                    ui.columns(2, |columns| {
                        columns[0].strong("Top models");
                        let models = cached.snapshot.by_model.iter().take(6).collect::<Vec<_>>();
                        if models.is_empty() {
                            columns[0].label(RichText::new("No model usage").color(MUTED));
                        }
                        for model in models {
                            columns[0].horizontal(|ui| {
                                ui.monospace(&model.model);
                                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                                    ui.label(format_compact_count(
                                        model.input_tokens.saturating_add(model.output_tokens),
                                    ));
                                });
                            });
                        }
                        columns[1].strong("Top skills");
                        let skills = cached
                            .snapshot
                            .skills
                            .top_skills
                            .iter()
                            .take(6)
                            .collect::<Vec<_>>();
                        if skills.is_empty() {
                            columns[1].label(RichText::new("No skill activity").color(MUTED));
                        }
                        for skill in skills {
                            columns[1].horizontal(|ui| {
                                ui.monospace(&skill.skill);
                                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                                    ui.label(format!(
                                        "{} actions",
                                        format_compact_count(skill.total_count)
                                    ));
                                });
                            });
                        }
                    });
                } else if self.command_center_usage_pending.is_some() {
                    ui.label(RichText::new("Loading usage analytics…").color(MUTED));
                } else if let Some(error) = self.command_center_usage_error.as_deref() {
                    ui.colored_label(
                        Color32::LIGHT_RED,
                        format!("Usage data unavailable: {error}"),
                    );
                    if ui.button("Retry").clicked() {
                        self.request_command_center_usage();
                    }
                } else {
                    ui.label(RichText::new("Usage data has not been loaded.").color(MUTED));
                    if ui.button("Refresh").clicked() {
                        self.request_command_center_usage();
                    }
                }
                if has_cached_usage && let Some(error) = self.command_center_usage_error.as_deref()
                {
                    ui.colored_label(Color32::LIGHT_RED, format!("Usage refresh failed: {error}"));
                }
            }
            CommandCenterSection::Maintenance => self.command_center_maintenance_content(ui),
        }
    }

    fn show_route_overlay(&mut self, ctx: &egui::Context) {
        if !self.route.is_overlay() {
            return;
        }
        let mut close = false;
        egui::Modal::new(Id::unique("hermes-route-overlay")).show(ctx, |ui| {
            if self.route == AppRoute::CommandCenter {
                let viewport = ctx.viewport_rect();
                let overlay_size = egui::vec2(
                    (viewport.width() - 108.0).max(420.0),
                    (viewport.height() - 108.0).max(420.0),
                );
                ui.set_min_size(overlay_size);
                ui.set_max_size(overlay_size);
                let modal_rect = ui.available_rect_before_wrap();
                let close_rect = Rect::from_min_size(
                    egui::pos2(modal_rect.right() - 34.0, modal_rect.top()),
                    egui::vec2(30.0, 28.0),
                );
                let mut close_ui = ui.new_child(
                    egui::UiBuilder::new()
                        .max_rect(close_rect)
                        .layout(Layout::top_down(Align::Center)),
                );
                close = close_ui
                    .add_sized([30.0, 28.0], egui::Button::new("×").frame(false))
                    .accessible_name("Close Command Center")
                    .on_hover_text("Close")
                    .clicked();
                self.command_center_content(ui);
            } else {
                ui.set_min_width(420.0);
                ui.set_max_width(640.0);
                ui.horizontal(|ui| {
                    ui.heading(self.route.title());
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        close = ui.button("Close").clicked();
                    });
                });
                ui.separator();
                match self.route {
                    AppRoute::Settings => self.show_settings(ui),
                    AppRoute::Cron => self.cron_content(ui),
                    _ => {
                        ui.label(
                            RichText::new("Connect to Hermes to load this screen.").color(MUTED),
                        );
                    }
                }
            }
        });
        if close {
            self.execute_registered_action(RegisteredUiAction::Navigate {
                path: self.overlay_return.path(),
            })
            .unwrap_or_else(|error| self.status = error);
        }
    }

    fn show_rename_dialog(&mut self, ctx: &egui::Context) {
        let Some(session) = self.rename_session.clone() else {
            return;
        };
        let action_key = self.session_summary_identity_key(&session);
        let pending = self.pending_session_renames.contains_key(&action_key);
        let uncertain = self.uncertain_session_renames.contains(&action_key);
        let mut save = false;
        let mut retry = false;
        let mut cancel = false;
        egui::Window::new("Rename session")
            .collapsible(false)
            .resizable(false)
            .show(ctx, |ui| {
                ui.label(format!("Session {}", session.id));
                ui.add_enabled_ui(!pending, |ui| {
                    ui.text_edit_singleline(&mut self.rename_draft)
                        .accessible_name("Session title");
                });
                ui.horizontal(|ui| {
                    if uncertain {
                        retry = ui
                            .button("Retry same request")
                            .accessible_name("Retry session rename with original request")
                            .clicked();
                    }
                    save = ui
                        .add_enabled(!pending, egui::Button::new("Save"))
                        .accessible_name("Save session title")
                        .clicked();
                    cancel = ui
                        .add_enabled(!pending, egui::Button::new("Cancel"))
                        .accessible_name("Cancel session rename")
                        .clicked();
                });
            });
        if save {
            self.start_session_rename_update(session);
        } else if retry {
            self.retry_uncertain_session_rename(session);
        } else if cancel {
            self.rename_session = None;
        }
    }

    fn empty_panel(&self, ui: &mut egui::Ui, message: &str) {
        ui.add_space(8.0);
        ui.label(RichText::new(message).size(12.0).color(MUTED));
    }

    fn session_pane_content(&mut self, ui: &mut Ui, descriptor: &doofusdock_core::PanelDescriptor) {
        let (Some(session_id), Some(profile_value)) = (
            descriptor.metadata.get("hermes.session.id"),
            descriptor.metadata.get("hermes.session.profile"),
        ) else {
            self.empty_panel(ui, "This session pane has incomplete identity metadata");
            return;
        };
        let session_id = session_id.clone();
        let profile = (!profile_value.is_empty()).then(|| profile_value.clone());
        let descriptor_connection = descriptor
            .metadata
            .get("hermes.session.connection_id")
            .filter(|connection_id| !connection_id.is_empty())
            .map(String::as_str);
        let connection_id = descriptor_connection.or_else(|| self.untagged_pane_connection_id());
        let Some(connection_id) = connection_id else {
            self.empty_panel(
                ui,
                "This older session pane has no saved Gateway identity. Open the session from its row to create a connection-specific tab.",
            );
            return;
        };
        if connection_id != self.active_gateway_connection_id() {
            self.empty_panel(
                ui,
                "This session belongs to another Hermes connection. Switch to that connection to open it.",
            );
            return;
        }
        let key = self.session_identity_key_for_connection(
            descriptor_connection.or(self.gateway_connection_id.as_deref()),
            &session_id,
            profile.as_deref(),
        );

        self.save_active_chat_view();
        let previous_route = self.route.clone();
        let previous_profile = self.active_session_profile.clone();
        let previous_runtime = self.active_runtime_session_id.clone();
        let previous_transcript = std::mem::take(&mut self.transcript);
        let previous_message_count = self.transcript_message_count;
        let previous_has_more = self.transcript_has_more;
        let previous_older_request = self.older_transcript_request.take();
        let previous_older_error = self.older_transcript_error.take();
        let previous_draft = std::mem::take(&mut self.draft);

        let view = self
            .session_chat_views
            .get(&key)
            .cloned()
            .unwrap_or_else(|| SessionChatViewState {
                profile: profile.clone(),
                ..SessionChatViewState::default()
            });
        self.route = AppRoute::Session(session_id.clone());
        self.active_session_profile = profile;
        self.active_runtime_session_id = view.runtime_session_id;
        self.transcript = view.transcript;
        self.transcript_message_count = view.transcript_message_count;
        self.transcript_has_more = view.transcript_has_more;
        self.older_transcript_request = view.older_transcript_request;
        self.older_transcript_error = view.older_transcript_error;
        self.draft = view.draft;

        if self.active_runtime_session_id.is_none() {
            self.ensure_session_resume(&session_id, self.active_session_profile.clone());
        }

        self.session_content(ui, &session_id);
        self.approval_cards(ui);
        self.clarify_cards(ui);
        self.batch_clarify_cards(ui);
        self.composer(ui);
        self.save_active_chat_view();

        self.route = previous_route;
        self.active_session_profile = previous_profile;
        self.active_runtime_session_id = previous_runtime;
        self.transcript = previous_transcript;
        self.transcript_message_count = previous_message_count;
        self.transcript_has_more = previous_has_more;
        self.older_transcript_request = previous_older_request;
        self.older_transcript_error = previous_older_error;
        self.draft = previous_draft;
    }

    fn session_pane_is_busy(&self, panel: &PanelId) -> bool {
        let document = self.workspace.dock.snapshot().document;
        let Some(descriptor) = document.descriptor(panel) else {
            return false;
        };
        let (Some(session_id), Some(profile_value)) = (
            descriptor.metadata.get("hermes.session.id"),
            descriptor.metadata.get("hermes.session.profile"),
        ) else {
            return false;
        };
        let profile = (!profile_value.is_empty()).then_some(profile_value.as_str());
        let connection_id = descriptor
            .metadata
            .get("hermes.session.connection_id")
            .filter(|connection_id| !connection_id.is_empty())
            .map(String::as_str)
            .or_else(|| self.untagged_pane_connection_id());
        let Some(connection_id) = connection_id else {
            return false;
        };
        let key_connection = descriptor
            .metadata
            .get("hermes.session.connection_id")
            .filter(|connection_id| !connection_id.is_empty())
            .map(String::as_str)
            .or(self.gateway_connection_id.as_deref());
        let key = self.session_identity_key_for_connection(key_connection, session_id, profile);
        let runtime = self
            .session_chat_views
            .get(&key)
            .and_then(|view| view.runtime_session_id.clone())
            .or_else(|| {
                (self.gateway_connection_id.as_deref() == Some(connection_id)
                    && self.route == AppRoute::Session(session_id.clone())
                    && self.active_session_profile.as_deref() == profile)
                    .then(|| self.active_runtime_session_id.clone())
                    .flatten()
            });
        let Some(runtime) = runtime else {
            return false;
        };
        let runtime_key =
            self.session_identity_key_for_connection(key_connection, &runtime, profile);
        self.pending_submissions.contains_key(&runtime_key)
            || self
                .pending_interrupt
                .as_ref()
                .is_some_and(|(_, session)| session == &runtime)
            || self
                .approval_prompts
                .values()
                .any(|prompt| prompt.session_id == runtime)
            || self
                .clarify_prompts
                .values()
                .any(|prompt| prompt.session_id == runtime)
            || self
                .batch_clarify_prompts
                .values()
                .any(|prompt| prompt.session_id == runtime)
    }

    fn close_session_pane(&mut self, panel: &PanelId) {
        let before = self.workspace.dock.snapshot();
        let closed_session = before
            .document
            .descriptor(panel)
            .filter(|descriptor| descriptor.role == "hermes_session_tile")
            .and_then(|descriptor| {
                Some((
                    descriptor.metadata.get("hermes.session.id")?.clone(),
                    descriptor
                        .metadata
                        .get("hermes.session.profile")
                        .filter(|profile| !profile.is_empty())
                        .cloned(),
                ))
            });
        let closing_active_route = closed_session
            .as_ref()
            .is_some_and(|(session_id, profile)| {
                self.route == AppRoute::Session(session_id.clone())
                    && self.active_session_profile == *profile
            });
        match self.workspace.close_session_pane(panel) {
            Ok(()) => {
                if closing_active_route {
                    let after = self.workspace.dock.snapshot();
                    let workspace_group = collect_dock_tab_groups(after.document.root.as_deref())
                        .into_iter()
                        .find(|group| group.panels.contains(&PanelId::from(WORKSPACE)));
                    let selected = workspace_group
                        .and_then(|group| group.panels.get(group.active_index).cloned());
                    if let Some(selected) = selected
                        && selected != PanelId::from(WORKSPACE)
                        && let Some(descriptor) = after.document.descriptor(&selected)
                        && descriptor.role == "hermes_session_tile"
                        && let Some(session_id) = descriptor.metadata.get("hermes.session.id")
                    {
                        self.save_active_chat_view();
                        self.active_session_profile = descriptor
                            .metadata
                            .get("hermes.session.profile")
                            .filter(|profile| !profile.is_empty())
                            .cloned();
                        self.navigate_after_save(AppRoute::Session(session_id.clone()));
                    } else {
                        self.new_chat_draft.clear();
                        self.navigate(AppRoute::NewChat);
                        self.active_session_profile = closed_session
                            .as_ref()
                            .and_then(|(_, profile)| profile.clone());
                    }
                }
                self.status = "Session tab closed · Hermes continues in the background".into()
            }
            Err(error) => self.status = error,
        }
    }

    fn close_active_tab(&mut self) -> Result<(), String> {
        let snapshot = self.workspace.dock.snapshot();
        let groups = collect_dock_tab_groups(snapshot.document.root.as_deref());
        let workspace_panel = PanelId::from(WORKSPACE);
        let active_group = close_target_tab_group(
            &groups,
            self.hovered_dock_group.as_ref(),
            self.focused_dock_group.as_ref(),
            &snapshot.document,
            &workspace_panel,
        );
        let active_panel = active_group
            .and_then(|group| group.panels.get(group.active_index))
            .cloned()
            .unwrap_or_else(|| workspace_panel.clone());

        if active_panel != workspace_panel {
            if snapshot
                .document
                .descriptor(&active_panel)
                .is_some_and(|descriptor| descriptor.role == "hermes_session_tile")
            {
                self.request_close_session_pane(&active_panel);
            }
            return Ok(());
        }

        let AppRoute::Session(current_session_id) = self.route.clone() else {
            return Ok(());
        };
        if let Some((panel, session_id, profile)) =
            next_session_pane_for_workspace(&snapshot.document)
        {
            self.save_active_chat_view();
            self.workspace.close_session_pane(&panel)?;
            self.workspace.select_panel(&PanelId::from(WORKSPACE))?;
            self.active_session_profile = profile;
            self.navigate_after_save(AppRoute::Session(session_id));
            self.status = format!("Promoted the next session tab from {current_session_id}");
            return Ok(());
        }

        self.new_chat_draft.clear();
        self.navigate(AppRoute::NewChat);
        self.status = "Closed the workspace chat · New session".into();
        Ok(())
    }

    fn cycle_active_dock_tab(&mut self, direction: isize) -> bool {
        let snapshot = self.workspace.dock.snapshot();
        let groups = collect_dock_tab_groups(snapshot.document.root.as_deref());
        let Some(group) = cycle_target_tab_group(
            &groups,
            self.hovered_dock_group.as_ref(),
            self.focused_dock_group.as_ref(),
            &snapshot.document,
            &PanelId::from(WORKSPACE),
        ) else {
            return false;
        };
        let group_node = group.node.clone();
        let panels = group.panels.clone();
        let active_index = group.active_index.min(panels.len().saturating_sub(1));
        let next_index = cycle_tab_index(active_index, panels.len(), direction);
        let target = panels[next_index].clone();
        self.focused_dock_group = Some(group_node.clone());
        if next_index != active_index {
            match self.workspace.dock.transact(
                snapshot.revision,
                CommandId::from(format!("cycle-dock-tab-{}-{next_index}", group_node.0)),
                [Operation::SelectTab {
                    tabs: group_node,
                    index: next_index,
                }],
            ) {
                Ok(_) => self.workspace.save_layout(),
                Err(error) => {
                    self.status = error.to_string();
                    return true;
                }
            }
        }

        if target.0 == WORKSPACE {
            if !matches!(self.route, AppRoute::NewChat | AppRoute::Session(_)) {
                self.save_active_chat_view();
                self.active_session_profile = self.last_chat_profile.clone();
                self.navigate_after_save(self.last_chat_route.clone());
            }
        } else if let Some(descriptor) = snapshot.document.descriptor(&target)
            && descriptor.role == "hermes_session_tile"
            && let Some(session_id) = descriptor.metadata.get("hermes.session.id")
        {
            let session_id = session_id.clone();
            let profile = descriptor
                .metadata
                .get("hermes.session.profile")
                .filter(|profile| !profile.is_empty())
                .cloned();
            self.save_active_chat_view();
            self.active_session_profile = profile;
            self.navigate_after_save(AppRoute::Session(session_id));
        }
        true
    }

    fn step_recent_session_switcher(&mut self, direction: isize, now: std::time::Instant) {
        if let Some(switcher) = &mut self.recent_session_switcher {
            if switcher.open {
                switcher.index =
                    cycle_tab_index(switcher.index, switcher.sessions.len(), direction);
                switcher.tab_down = true;
                return;
            }
            if switcher.pending_browse {
                switcher.pending_browse = false;
                switcher.open = true;
                switcher.index =
                    cycle_tab_index(switcher.index, switcher.sessions.len(), direction);
                switcher.tab_down = true;
                return;
            }
        }

        let sessions = self
            .sessions
            .iter()
            .filter(|session| !session.archived && session.profile == self.active_session_profile)
            .cloned()
            .collect::<Vec<_>>();
        if sessions.len() < 2 {
            self.recent_session_switcher = None;
            return;
        }

        let current_session = match &self.route {
            AppRoute::Session(session_id) => Some(session_id.as_str()),
            _ => None,
        };
        let current_index = current_session
            .and_then(|session_id| sessions.iter().position(|session| session.id == session_id));
        let start = current_index.unwrap_or(if direction >= 0 {
            sessions.len() - 1
        } else {
            0
        });
        let index = cycle_tab_index(start, sessions.len(), direction);
        let target = sessions[index].clone();
        self.recent_session_switcher = Some(RecentSessionSwitcher {
            sessions,
            index,
            pending_browse: true,
            open: false,
            tab_down: true,
            reveal_at: now + SESSION_SWITCHER_REVEAL_DELAY,
        });
        self.open_recent_session(&target);
    }

    fn open_recent_session(&mut self, session: &SessionSummary) {
        if let Err(error) = self.execute_registered_action(RegisteredUiAction::OpenSession {
            session_id: session.id.clone(),
            profile: session.profile.clone(),
        }) {
            self.status = error;
        }
    }

    fn release_recent_session_switcher_tab(&mut self) {
        if let Some(switcher) = &mut self.recent_session_switcher {
            switcher.tab_down = false;
            if !switcher.open && !switcher.pending_browse {
                self.recent_session_switcher = None;
            }
        }
    }

    fn commit_recent_session_switcher(&mut self) {
        let target = self.recent_session_switcher.take().and_then(|switcher| {
            switcher
                .open
                .then(|| switcher.sessions.get(switcher.index).cloned())
                .flatten()
        });
        if let Some(target) = target {
            self.open_recent_session(&target);
        }
    }

    fn close_recent_session_switcher(&mut self) {
        self.recent_session_switcher = None;
    }

    fn update_recent_session_switcher(&mut self, ctx: &egui::Context) {
        if !ctx.input(|input| input.focused) {
            self.close_recent_session_switcher();
            return;
        }
        let now = std::time::Instant::now();
        let switcher_open = self
            .recent_session_switcher
            .as_ref()
            .is_some_and(|switcher| switcher.open);
        let (tab_released, page_released, ctrl_down, escape_pressed) = ctx.input_mut(|input| {
            let tab_released = input.key_released(egui::Key::Tab);
            let page_released =
                input.key_released(egui::Key::PageDown) || input.key_released(egui::Key::PageUp);
            let ctrl_down = input.modifiers.ctrl;
            let escape_pressed =
                switcher_open && input.consume_key(input.modifiers, egui::Key::Escape);
            (tab_released, page_released, ctrl_down, escape_pressed)
        });

        if tab_released || page_released {
            self.release_recent_session_switcher_tab();
        }
        if escape_pressed
            && self
                .recent_session_switcher
                .as_ref()
                .is_some_and(|switcher| switcher.open)
        {
            self.close_recent_session_switcher();
        } else if self
            .recent_session_switcher
            .as_ref()
            .is_some_and(|switcher| switcher.open && !ctrl_down)
        {
            self.commit_recent_session_switcher();
        } else if !ctrl_down
            && self
                .recent_session_switcher
                .as_ref()
                .is_some_and(|switcher| switcher.pending_browse)
        {
            self.close_recent_session_switcher();
        }
        self.reveal_recent_session_switcher_if_due(ctx, now);
    }

    fn reveal_recent_session_switcher_if_due(
        &mut self,
        ctx: &egui::Context,
        now: std::time::Instant,
    ) {
        if let Some(switcher) = &mut self.recent_session_switcher
            && switcher.pending_browse
            && switcher.tab_down
        {
            if now >= switcher.reveal_at {
                switcher.pending_browse = false;
                switcher.open = true;
            } else {
                ctx.request_repaint_after(switcher.reveal_at - now);
            }
        }
    }

