    #[test]
    fn panel_drop_regions_match_center_and_each_edge() {
        let rect = Rect::from_min_max(egui::pos2(10.0, 20.0), egui::pos2(210.0, 120.0));
        assert_eq!(
            compute_drop_edge(rect, egui::pos2(110.0, 70.0)),
            DropEdge::Center
        );
        assert_eq!(
            compute_drop_edge(rect, egui::pos2(20.0, 70.0)),
            DropEdge::Left
        );
        assert_eq!(
            compute_drop_edge(rect, egui::pos2(200.0, 70.0)),
            DropEdge::Right
        );
        assert_eq!(
            compute_drop_edge(rect, egui::pos2(110.0, 25.0)),
            DropEdge::Top
        );
        assert_eq!(
            compute_drop_edge(rect, egui::pos2(110.0, 115.0)),
            DropEdge::Bottom
        );
    }

    #[test]
    fn panel_drop_regions_match_pinned_radial_geometry() {
        let square = Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(100.0, 100.0));
        assert_eq!(
            compute_drop_edge(square, egui::pos2(50.0, 50.0)),
            DropEdge::Center
        );
        assert_eq!(
            compute_drop_edge(square, egui::pos2(80.5, 50.0)),
            DropEdge::Center,
            "inside the 0.62 center radius remains a tab-stack target"
        );
        assert_eq!(
            compute_drop_edge(square, egui::pos2(81.5, 50.0)),
            DropEdge::Right,
            "outside the center radius targets the dominant axis"
        );
        assert_eq!(
            compute_drop_edge(square, egui::pos2(0.0, 0.0)),
            DropEdge::Left,
            "equal corner axes resolve horizontally like the pinned source"
        );

        let wide = Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(240.0, 100.0));
        assert_eq!(
            compute_drop_edge(wide, egui::pos2(120.0, 5.0)),
            DropEdge::Top
        );
        assert_eq!(
            compute_drop_edge(wide, egui::pos2(5.0, 50.0)),
            DropEdge::Left
        );

        let tall = Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(100.0, 240.0));
        assert_eq!(
            compute_drop_edge(tall, egui::pos2(50.0, 5.0)),
            DropEdge::Top
        );
        assert_eq!(
            compute_drop_edge(tall, egui::pos2(50.0, 235.0)),
            DropEdge::Bottom
        );
    }

    #[test]
    fn split_resize_preserves_weight_pair_and_clamps_each_side() {
        let centered = resized_split_weights(&[0.25, 0.75, 0.4], 0, 25.0, 100.0);
        assert!((centered[0] - 0.5).abs() < 1e-9);
        assert!((centered[1] - 0.5).abs() < 1e-9);
        assert_eq!(centered[2], 0.4);
        let upper_clamped = resized_split_weights(&[0.25, 0.75], 0, 100.0, 100.0);
        assert!((upper_clamped[0] - 0.95).abs() < 1e-9);
        assert!((upper_clamped[1] - 0.05).abs() < 1e-9);
        let lower_clamped = resized_split_weights(&[0.25, 0.75], 0, -100.0, 100.0);
        assert!((lower_clamped[0] - 0.05).abs() < 1e-9);
        assert!((lower_clamped[1] - 0.95).abs() < 1e-9);
        assert_eq!(
            resized_split_weights(&[0.25, 0.75], 2, 20.0, 100.0),
            vec![0.25, 0.75]
        );
        assert_eq!(
            resized_split_weights(&[0.25, 0.75], 0, 20.0, 0.0),
            vec![0.25, 0.75]
        );
    }

    fn isolated_app() -> (HermesNativeApp, std::path::PathBuf) {
        let nonce = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("system clock")
            .as_nanos();
        let profile = std::env::temp_dir().join(format!(
            "HermesNative-Agent-Test-{}-{nonce}",
            std::process::id()
        ));
        std::fs::create_dir(&profile).expect("create isolated test profile");
        (
            HermesNativeApp::new_for_automation(profile.clone()),
            profile,
        )
    }

    #[test]
    fn prepared_image_restore_is_scoped_and_does_not_send() {
        let (mut app, profile_dir) = isolated_app();
        app.route = AppRoute::Session("stored-session".into());
        app.active_runtime_session_id = Some("runtime-session".into());
        app.active_session_profile = Some("work".into());
        let connection_id = app.active_gateway_connection_id().to_owned();
        let draft = PreparedImageDraft {
            version: 1,
            id: "prepared-image-recovery-1".into(),
            connection_id: connection_id.clone(),
            profile: Some("work".into()),
            stored_session_id: "stored-session".into(),
            text: "Describe this image".into(),
            attachments: vec![PreparedImageAttachment {
                path: "attachments/image.png".into(),
                source_path: "C:\\images\\image.png".into(),
                name: "image.png".into(),
                mime: "image/png".into(),
                ref_text: Some("[image attached]".into()),
            }],
            created_at_unix_seconds: 10,
        };
        crate::prepared_image_drafts::write(app.workspace.data_directory(), &draft)
            .expect("persist recovery draft");
        app.prepared_image_drafts =
            crate::prepared_image_drafts::load(app.workspace.data_directory())
                .expect("load recovery draft");
        app.prepared_image_drafts.push(PreparedImageDraft {
            connection_id: "another-connection".into(),
            id: "wrong-owner".into(),
            ..draft.clone()
        });

        let visible = app.matching_prepared_image_drafts();
        assert_eq!(visible, [draft.clone()], "only the exact owner is visible");
        app.restore_prepared_image_draft(&draft.id);
        assert_eq!(app.draft, draft.text);
        assert_eq!(app.composer_attachments.len(), 1);
        assert_eq!(
            app.composer_attachments[0].attached_session_id.as_deref(),
            Some("runtime-session")
        );
        assert!(
            app.gateway_discovery.is_none(),
            "restore must not require or call Gateway"
        );
        assert_eq!(
            crate::prepared_image_drafts::load(app.workspace.data_directory()).unwrap(),
            [draft],
            "restoring only hides the item locally and does not retire it"
        );

        app.draft = "keep existing text".into();
        app.composer_attachments.clear();
        app.restore_prepared_image_draft("prepared-image-recovery-1");
        assert_eq!(
            app.draft, "keep existing text",
            "occupied composer is unchanged"
        );
        drop(app);
        std::fs::remove_dir_all(profile_dir).expect("remove isolated test profile");
    }

