    #[cfg(feature = "agent-automation")]
    #[test]
    fn first_run_setup_matches_pinned_copy_and_gates_remote_actions_by_credentials() {
        let (mut app, profile_dir) = isolated_app();
        app.first_run_setup_visible = true;
        let app = std::rc::Rc::new(std::cell::RefCell::new(app));
        let frame_app = app.clone();
        let mut harness = egui_kittest::Harness::builder()
            .with_size(egui::vec2(1220.0, 800.0))
            .build_ui(move |ui| frame_app.borrow_mut().draw(ui));

        harness
            .get_by_label("Install Hermes locally. Download Hermes, create its Python environment, and run the backend on this computer.")
            .click();
        harness.run();
        assert_eq!(
            app.borrow().first_run_setup_error.as_deref(),
            Some("Local Hermes bootstrap is not implemented in this Rust client yet.")
        );

        harness
            .get_by_label("Connect to existing Hermes. Use a remote backend with a session token or browser sign-in. No local install will start.")
            .click();
        harness.run();
        assert!(app.borrow().first_run_remote_setup_open);
        assert!(
            harness
                .get_by_label("Apply remote")
                .accesskit_node()
                .is_disabled()
        );
        assert!(
            harness
                .get_by_label("Test connection")
                .accesskit_node()
                .is_disabled()
        );
        app.borrow_mut().first_run_gateway_url = "https://gateway.example.com/hermes".into();
        app.borrow_mut().first_run_remote_probe_report = Some(RemoteProbeReport {
            base_url: "https://gateway.example.com/hermes".into(),
            auth_mode: RemoteAuthMode::Token,
            supports_native_pkce: false,
            version: Some("2026.11".into()),
            providers: Vec::new(),
        });
        harness.run();
        assert!(
            harness
                .get_by_label("Test connection")
                .accesskit_node()
                .is_disabled()
        );
        app.borrow_mut().first_run_remote_token = Zeroizing::new("fixture-token".into());
        harness.run();
        assert!(
            !harness
                .get_by_label("Test connection")
                .accesskit_node()
                .is_disabled()
        );
        assert!(
            harness
                .query_all_by(|node| {
                    node.label().as_deref() == Some("Hermes session token")
                        && format!("{:?}", node.role()) == "PasswordInput"
                })
                .next()
                .is_some()
        );
        assert!(
            harness
                .get_by_label("Apply remote")
                .accesskit_node()
                .is_disabled()
        );
        {
            let mut app = app.borrow_mut();
            app.first_run_remote_test_report = Some(RemoteConnectionTestReport {
                base_url: "https://gateway.example.com/hermes".into(),
                version: Some("2026.11".into()),
            });
            app.first_run_remote_tested_payload_key = app.first_run_remote_payload_key();
        }
        harness.run();
        assert!(
            !harness
                .get_by_label("Apply remote")
                .accesskit_node()
                .is_disabled()
        );
        app.borrow_mut().first_run_remote_token = Zeroizing::new("changed-token".into());
        harness.run();
        assert!(
            harness
                .get_by_label("Apply remote")
                .accesskit_node()
                .is_disabled()
        );

        app.borrow_mut().first_run_remote_token = Zeroizing::new("fixture-token".into());
        harness.run();
        harness.get_by_label("Apply remote").click();
        harness.run();
        assert_eq!(
            app.borrow().workspace.last_remote_gateway_url(),
            Some("https://gateway.example.com/hermes")
        );
        assert_eq!(
            crate::native_token_store::load_session_token(
                &profile_dir,
                "https://gateway.example.com/hermes"
            )
            .unwrap()
            .as_deref()
            .map(String::as_str),
            Some("fixture-token")
        );
        assert!(app.borrow().gateway_discovery.is_some());
        assert!(app.borrow().gateway_endpoint.is_none());
        harness
            .get_by_label("Connect to existing Hermes. Use a remote backend with a session token or browser sign-in. No local install will start.")
            .click();
        harness.run();
        assert_eq!(
            app.borrow().first_run_gateway_url,
            "https://gateway.example.com/hermes"
        );
        let token_report = RemoteProbeReport {
            base_url: "https://gateway.example.com/hermes".into(),
            auth_mode: RemoteAuthMode::Token,
            supports_native_pkce: false,
            version: Some("2026.11".into()),
            providers: Vec::new(),
        };
        app.borrow_mut()
            .restore_saved_remote_credential(&token_report);
        assert_eq!(&*app.borrow().first_run_remote_token, "fixture-token");
        let oauth_report = RemoteProbeReport {
            auth_mode: RemoteAuthMode::OAuth,
            ..token_report
        };
        app.borrow_mut()
            .restore_saved_remote_credential(&oauth_report);
        assert!(app.borrow().first_run_remote_token.is_empty());
        assert!(app.borrow().first_run_oauth_session.is_none());

        drop(harness);
        drop(app);
        std::fs::remove_dir_all(profile_dir).expect("remove isolated test profile");
    }

    #[test]
    fn first_run_gateway_url_requires_http_scheme_and_host() {
        for accepted in [
            "https://gateway.example.com/hermes",
            "HTTP://localhost:9119",
            "https://[::1]:9119/api",
            "gateway.example.com/hermes",
        ] {
            assert!(is_valid_http_gateway_url(accepted), "{accepted}");
        }
        for rejected in [
            "",
            "ftp://gateway.example.com",
            "https://",
            "https://.invalid/path",
            "https://gateway.example.com with credentials",
            "https://user:pass@gateway.example.com",
            "https://gateway.example.com:notaport",
            "https://[::1",
            "https://[::1]suffix",
        ] {
            assert!(!is_valid_http_gateway_url(rejected), "{rejected}");
        }
    }

    #[test]
    fn native_oauth_support_matches_pinned_provider_decision() {
        let mut report = RemoteProbeReport {
            base_url: "https://gateway.example.com".into(),
            auth_mode: RemoteAuthMode::OAuth,
            supports_native_pkce: true,
            version: None,
            providers: vec![crate::remote_probe::RemoteAuthProvider {
                name: "basic".into(),
                display_name: "Password".into(),
                supports_password: true,
            }],
        };
        assert!(!native_oauth_login_supported(&report));
        report
            .providers
            .push(crate::remote_probe::RemoteAuthProvider {
                name: "nous".into(),
                display_name: "Nous Research".into(),
                supports_password: false,
            });
        assert!(native_oauth_login_supported(&report));
        report.providers.clear();
        assert!(native_oauth_login_supported(&report));
        report.supports_native_pkce = false;
        assert!(!native_oauth_login_supported(&report));
    }

    fn seed_pending_submission(
        app: &mut HermesNativeApp,
        submission_id: &str,
        admission_id: Option<&str>,
        uncertain: bool,
    ) {
        let session_id = "runtime-session";
        let profile = Some("work".to_owned());
        app.active_session_profile = profile.clone();
        app.pending_submissions.insert(
            session_identity_key(session_id, profile.as_deref()),
            PendingPrompt {
                session_id: session_id.into(),
                profile,
                submission_id: submission_id.into(),
                text: "hello".into(),
                display_text: "hello".into(),
                attachments: Vec::new(),
                uncertain,
                admission_id: admission_id.map(str::to_owned),
                execution_generation: None,
                resolving_unknown: false,
                retrying_failed_turn: false,
            },
        );
    }

    #[test]
    fn message_stream_events_project_into_the_active_runtime_transcript() {
        let (mut app, profile) = isolated_app();
        app.route = AppRoute::Session("stored-session".into());
        app.active_runtime_session_id = Some("runtime-session".into());
        seed_pending_submission(&mut app, "submission-1", Some("admission-1"), false);

        app.handle_server_event(serde_json::json!({
            "type":"message.start","session_id":"runtime-session",
            "payload":{"turn_id":"turn-1"}
        }));
        app.handle_server_event(serde_json::json!({
            "type":"message.delta","session_id":"runtime-session",
            "payload":{"text":"Hello "}
        }));
        app.handle_server_event(serde_json::json!({
            "type":"message.delta","session_id":"runtime-session",
            "payload":{"text":"Hermes"}
        }));
        app.handle_server_event(serde_json::json!({
            "type":"message.complete","session_id":"runtime-session",
            "payload":{"admission_id":"admission-1","text":"Hello Hermes!","status":"complete"}
        }));

        assert_eq!(app.transcript.len(), 1);
        assert_eq!(app.transcript[0]["role"], "assistant");
        assert_eq!(app.transcript[0]["content"], "Hello Hermes!");
        assert_eq!(app.transcript[0]["streaming"], false);
        assert!(app.pending_submissions.is_empty());
        assert_eq!(app.status, "Hermes response complete");
        drop(app);
        std::fs::remove_dir_all(profile).expect("remove isolated test profile");
    }

    #[test]
    fn incremental_assistant_delta_is_visible_before_terminal_message_complete() {
        let (mut app, profile_dir) = isolated_app();
        app.gateway_connected = true;
        app.route = AppRoute::Session("stored-session".into());
        app.active_runtime_session_id = Some("runtime-session".into());
        app.active_session_profile = Some("work".into());
        seed_pending_submission(
            &mut app,
            "submission-stream",
            Some("admission-stream"),
            false,
        );
        app.handle_server_event(serde_json::json!({
            "type":"message.start","session_id":"runtime-session","profile":"work",
            "payload":{"turn_id":"turn-stream"}
        }));
        app.handle_server_event(serde_json::json!({
            "type":"message.delta","session_id":"runtime-session","profile":"work",
            "payload":{"text":"First streamed chunk"}
        }));

        let app = Rc::new(RefCell::new(app));
        let frame_app = Rc::clone(&app);
        let mut harness = egui_kittest::Harness::builder()
            .with_size(egui::vec2(1440.0, 1000.0))
            .build_ui(move |ui| frame_app.borrow_mut().draw(ui));
        assert_eq!(
            app.borrow().transcript[0]["content"],
            "First streamed chunk",
            "the reducer must hold the live text before the UI is inspected"
        );
        let accessible_text = harness
            .query_all_by(|_| true)
            .map(|node| format!("{:?}", node.accesskit_node().label()))
            .collect::<Vec<_>>();
        assert!(
            harness
                .query_all_by(
                    |node| node.label().as_deref() == Some("assistant: First streamed chunk")
                )
                .next()
                .is_some(),
            "the live assistant delta is rendered before message.complete; accessible text: {accessible_text:?}"
        );
        assert_eq!(app.borrow().transcript[0]["streaming"], true);
        assert!(harness.query_by_label("Stop response").is_some());

        app.borrow_mut().handle_server_event(serde_json::json!({
            "type":"message.delta","session_id":"runtime-session","profile":"work",
            "payload":{"text":" and another chunk"}
        }));
        harness.run();
        assert!(
            harness
                .query_all_by(|node| node.label().as_deref()
                    == Some("assistant: First streamed chunk and another chunk"))
                .next()
                .is_some(),
            "the visible assistant bubble grows with each delta"
        );

        app.borrow_mut().handle_server_event(serde_json::json!({
            "type":"message.complete","session_id":"runtime-session","profile":"work",
            "payload":{"admission_id":"admission-stream","text":"First streamed chunk and another chunk.","status":"complete"}
        }));
        harness.run();
        assert!(
            harness
                .query_all_by(|node| node.label().as_deref()
                    == Some("assistant: First streamed chunk and another chunk."))
                .next()
                .is_some(),
            "the final text replaces the live bubble without duplication"
        );
        assert_eq!(app.borrow().transcript.len(), 1);
        assert_eq!(app.borrow().transcript[0]["streaming"], false);
        assert!(app.borrow().pending_submissions.is_empty());
        assert!(harness.query_by_label("Stop response").is_none());
        drop(harness);
        drop(app);
        std::fs::remove_dir_all(profile_dir).expect("remove isolated test profile");
    }

    #[test]
    fn interim_assistant_event_seals_one_bubble_and_final_text_opens_the_next() {
        let mut transcript = vec![serde_json::json!({"role":"user","content":"Investigate"})];
        apply_stream_event_to_transcript(
            &mut transcript,
            "message.start",
            &serde_json::json!({}),
            None,
        );
        apply_stream_event_to_transcript(
            &mut transcript,
            "message.delta",
            &serde_json::json!({"text":"Checking the config."}),
            None,
        );
        apply_stream_event_to_transcript(
            &mut transcript,
            "message.interim",
            &serde_json::json!({"text":"Checking the config."}),
            None,
        );
        apply_stream_event_to_transcript(
            &mut transcript,
            "tool.start",
            &serde_json::json!({"tool_id":"read-1","name":"read_file"}),
            Some(1),
        );
        apply_stream_event_to_transcript(
            &mut transcript,
            "message.interim",
            &serde_json::json!({"text":"Checking the config."}),
            None,
        );
        apply_stream_event_to_transcript(
            &mut transcript,
            "message.delta",
            &serde_json::json!({"text":"The final answer is 42."}),
            None,
        );
        apply_stream_event_to_transcript(
            &mut transcript,
            "message.complete",
            &serde_json::json!({"text":"The final answer is 42.","status":"complete"}),
            None,
        );

        let assistants = transcript
            .iter()
            .filter(|message| {
                message.get("role").and_then(|value| value.as_str()) == Some("assistant")
            })
            .collect::<Vec<_>>();
        assert_eq!(assistants.len(), 2);
        assert_eq!(assistants[0]["content"], "Checking the config.");
        assert_eq!(assistants[0]["interim"], true);
        assert_eq!(assistants[0]["streaming"], false);
        assert_eq!(assistants[1]["content"], "The final answer is 42.");
        assert_eq!(assistants[1]["interim"], false);
        assert_eq!(assistants[1]["streaming"], false);
        assert!(transcript.iter().any(|message| {
            message.get("type").and_then(|value| value.as_str()) == Some("tool_call")
        }));
    }

