    #[test]
    fn tool_start_and_complete_render_generation_scoped_transcript_cards() {
        let (mut app, profile) = isolated_app();
        app.route = AppRoute::Session("stored-session".into());
        app.active_runtime_session_id = Some("runtime-session".into());
        app.handle_server_event(serde_json::json!({
            "type":"tool.start",
            "session_id":"runtime-session",
            "execution_generation":3,
            "payload":{"tool_id":"reused-id","name":"terminal","args":{"command":"pwd"}}
        }));
        app.handle_server_event(serde_json::json!({
            "type":"tool.complete",
            "session_id":"runtime-session",
            "execution_generation":3,
            "payload":{"tool_id":"reused-id","name":"terminal","result_text":"C:/project"}
        }));
        app.handle_server_event(serde_json::json!({
            "type":"tool.start",
            "session_id":"runtime-session",
            "execution_generation":4,
            "payload":{"tool_id":"reused-id","name":"terminal","args":{"command":"git status"}}
        }));
        app.handle_server_event(serde_json::json!({
            "type":"tool.complete",
            "session_id":"runtime-session",
            "execution_generation":4,
            "payload":{"tool_id":"reused-id","name":"terminal","summary":"Working tree clean"}
        }));

        assert_eq!(app.transcript.len(), 2);
        assert_eq!(app.transcript[0]["execution_generation"], 3);
        assert_eq!(app.transcript[0]["status"], "complete");
        assert_eq!(app.transcript[1]["execution_generation"], 4);
        assert_eq!(app.transcript[1]["status"], "complete");
        assert_eq!(
            transcript_message(&app.transcript[0]),
            ("terminal · complete".into(), "C:/project".into())
        );
        assert_eq!(
            transcript_message(&app.transcript[1]),
            ("terminal · complete".into(), "Working tree clean".into())
        );

        let harness = egui_kittest::Harness::builder()
            .with_size(egui::vec2(1440.0, 4000.0))
            .build_ui(|ui| app.draw(ui));
        let labels = harness
            .query_all_by(|_| true)
            .filter_map(|node| node.accesskit_node().label())
            .collect::<Vec<_>>();
        assert_eq!(
            harness
                .query_all_by(|node| {
                    node.label()
                        .is_some_and(|label| label.starts_with("terminal · complete:"))
                })
                .count(),
            2,
            "tool call states must appear in the accessible transcript; labels: {labels:?}"
        );
        drop(harness);
        drop(app);
        std::fs::remove_dir_all(profile).expect("remove isolated test profile");
    }

    #[test]
    fn tool_payload_disclosure_expands_arguments_and_result_accessibly() {
        let (mut app, profile_dir) = isolated_app();
        app.workspace.preferences.mode = InterfaceMode::Advanced;
        app.route = AppRoute::Session("stored-session".into());
        app.active_runtime_session_id = Some("runtime-session".into());
        app.active_session_profile = Some("work".into());
        app.handle_server_event(json!({
            "type":"tool.start",
            "session_id":"runtime-session",
            "profile":"work",
            "execution_generation":12,
            "payload":{
                "tool_id":"call_payload",
                "name":"terminal",
                "args":{"command":"git status"}
            }
        }));
        app.handle_server_event(json!({
            "type":"tool.complete",
            "session_id":"runtime-session",
            "profile":"work",
            "execution_generation":12,
            "payload":{
                "tool_id":"call_payload",
                "name":"terminal",
                "result":{"stdout":"working tree clean"}
            }
        }));

        assert_eq!(
            tool_payload_trace(&app.transcript[0]).as_deref(),
            Some(
                "Arguments:\n{\n  \"command\": \"git status\"\n}\n\nResult:\n{\n  \"stdout\": \"working tree clean\"\n}"
            )
        );

        let mut harness = egui_kittest::Harness::builder()
            .with_size(egui::vec2(1440.0, 1800.0))
            .build_ui(|ui| app.draw(ui));
        let labels_before = harness
            .query_all_by(|_| true)
            .filter_map(|node| node.accesskit_node().label())
            .collect::<Vec<_>>();
        assert!(
            harness.query_by_label("Tool payload").is_some(),
            "collapsed payload disclosure should be accessible: {labels_before:?}"
        );
        assert!(
            !labels_before
                .iter()
                .any(|label| label.contains("Arguments:")),
            "payload body must remain collapsed by default: {labels_before:?}"
        );
        harness.get_by_label("Tool payload").click_accesskit();
        harness.run();
        let visible_text = harness
            .query_all_by(|_| true)
            .flat_map(|node| [node.accesskit_node().label(), node.accesskit_node().value()])
            .flatten()
            .collect::<Vec<_>>();
        assert!(
            visible_text
                .iter()
                .any(|label| label.contains("Arguments:")),
            "expanded payload should expose arguments: {visible_text:?}"
        );
        assert!(
            visible_text.iter().any(|text| text.contains("Result:")),
            "expanded payload should expose result: {visible_text:?}"
        );
        drop(harness);
        drop(app);
        std::fs::remove_dir_all(profile_dir).expect("remove isolated test profile");
    }

