    #[test]
    fn tool_payload_trace_formats_json_and_bounds_large_results() {
        let payload = json!({
            "type":"tool_call",
            "args_text":"{\"path\":\"C:/work\"}",
            "result_text":"done"
        });
        assert_eq!(
            tool_payload_trace(&payload).as_deref(),
            Some("Arguments:\n{\n  \"path\": \"C:/work\"\n}\n\nResult:\ndone")
        );
        let null_primary_payload = json!({
            "type":"tool_call",
            "args":null,
            "args_text":"fallback args",
            "result":null,
            "result_text":"fallback result"
        });
        assert_eq!(
            tool_payload_trace(&null_primary_payload).as_deref(),
            Some("Arguments:\nfallback args\n\nResult:\nfallback result")
        );
        assert_eq!(tool_payload_trace(&json!({"type":"tool_call"})), None);

        let large = json!({
            "type":"tool_call",
            "args":"x".repeat(20_100)
        });
        let rendered = tool_payload_trace(&large).expect("arguments produce a payload");
        assert!(rendered.chars().count() < 20_100);
        assert!(rendered.ends_with("more characters truncated."));
    }

    #[test]
    fn tool_image_reference_follows_result_then_arguments_and_filters_non_images() {
        assert_eq!(
            tool_image_reference(&json!({
                "type":"tool_call",
                "image_path":"C:/work/render.png"
            }))
            .as_deref(),
            Some("C:/work/render.png")
        );
        assert_eq!(
            tool_image_reference(&json!({
                "result":{"image_url":"https://example.test/render.webp?size=large"},
                "args":{"path":"C:/work/input.png"}
            }))
            .as_deref(),
            Some("https://example.test/render.webp?size=large")
        );
        assert_eq!(
            tool_image_reference(&json!({
                "result_text":"{\"path\":\"C:/work/render.svg\"}"
            }))
            .as_deref(),
            Some("C:/work/render.svg")
        );
        assert_eq!(
            tool_image_reference(&json!({
                "result":{"path":"C:/work/readme.txt"}
            })),
            None
        );
        assert_eq!(
            tool_image_reference(&json!({
                "result":{"image_url":"data:image/png;base64,AA=="}
            })),
            None
        );
    }

